def patch_info_plist_bgtask(tg: Path) -> None:
    """Add BGTaskSchedulerPermittedIdentifiers key to Info.plist so iOS allows BGAppRefreshTask."""
    for name in ("Info.plist", "InfoBazel.plist"):
        path = tg / "Telegram/Telegram-iOS" / name
        if not path.is_file():
            continue
        with path.open("rb") as f:
            pl = plistlib.load(f)
        key = "BGTaskSchedulerPermittedIdentifiers"
        task_id = "com.aorusgram.dmc.sync"
        existing = pl.get(key, [])
        if task_id not in existing:
            pl[key] = existing + [task_id]
            with path.open("wb") as f:
                plistlib.dump(pl, f, fmt=plistlib.FMT_XML)
            print(f"{name}: added BGTaskSchedulerPermittedIdentifiers = [{task_id}]")
        else:
            print(f"{name}: BGTaskSchedulerPermittedIdentifiers already present")


def patch_info_plist_speech_usage(tg: Path) -> None:
    """Add NSSpeechRecognitionUsageDescription to Info.plist.

    Without this key, calling SFSpeechRecognizer.requestAuthorization triggers
    an immediate hard crash with the system message:
      "This app has crashed because it attempted to access privacy-sensitive
       data without a usage description."
    Required by both the VoiceTranscriberView (microphone live recording) and
    the long-press transcribe action on voice messages.

    NSMicrophoneUsageDescription is already present upstream (Telegram uses it
    for voice messages), so we only need to add the speech recognition key.
    """
    description = (
        "AorusGram использует распознавание речи для транскрипции голосовых "
        "сообщений прямо на устройстве (никакие данные не покидают ваш телефон)."
    )
    for name in ("Info.plist", "InfoBazel.plist"):
        path = tg / "Telegram/Telegram-iOS" / name
        if not path.is_file():
            continue
        with path.open("rb") as f:
            pl = plistlib.load(f)
        if pl.get("NSSpeechRecognitionUsageDescription"):
            print(f"{name}: NSSpeechRecognitionUsageDescription already present")
            continue
        pl["NSSpeechRecognitionUsageDescription"] = description
        with path.open("wb") as f:
            plistlib.dump(pl, f, fmt=plistlib.FMT_XML)
        print(f"{name}: added NSSpeechRecognitionUsageDescription")


def patch_info_plist_face_id(tg: Path) -> None:
    """Add NSFaceIDUsageDescription to Info.plist for the Chat Lock feature.

    LAContext.evaluatePolicy(.deviceOwnerAuthentication) hard-crashes on Face ID devices
    when this key is absent ("attempted to access privacy-sensitive data without a usage
    description"). Touch ID / passcode-only devices do not need it, but the key must be
    present for the feature to be usable at all on modern hardware.
    """
    description = (
        "AorusGram использует Face ID, чтобы открывать защищённые чаты только вам. "
        "Биометрия обрабатывается системой и не покидает устройство."
    )
    for name in ("Info.plist", "InfoBazel.plist"):
        path = tg / "Telegram/Telegram-iOS" / name
        if not path.is_file():
            continue
        with path.open("rb") as f:
            pl = plistlib.load(f)
        if pl.get("NSFaceIDUsageDescription"):
            print(f"{name}: NSFaceIDUsageDescription already present")
            continue
        pl["NSFaceIDUsageDescription"] = description
        with path.open("wb") as f:
            plistlib.dump(pl, f, fmt=plistlib.FMT_XML)
        print(f"{name}: added NSFaceIDUsageDescription")


def patch_info_plist_file_sharing(tg: Path) -> None:
    """Keep the app container private.

    Exposing all of Documents through Files.app also exposes unrelated account and feature data
    and is unnecessary.
    """
    for name in ("Info.plist", "InfoBazel.plist"):
        path = tg / "Telegram/Telegram-iOS" / name
        if not path.is_file():
            continue
        with path.open("rb") as f:
            pl = plistlib.load(f)
        changed = False
        for key in ("UIFileSharingEnabled", "LSSupportsOpeningDocumentsInPlace"):
            if key in pl:
                del pl[key]
                changed = True
        if changed:
            with path.open("wb") as f:
                plistlib.dump(pl, f, fmt=plistlib.FMT_XML)
            print(f"{name}: removed global Documents sharing")
        else:
            print(f"{name}: Documents sharing already disabled")


# Inline Swift that builds Telegram's SOCKS settings for the in-process REALITY
# endpoint. While a subscription is active, the persistent requirement marker
# keeps Telegram on a deliberately closed loopback port until libXray is ready. This
# is fail-closed: provisioning or core failures cannot silently reopen a direct route.
# Without a subscription the marker is false and Telegram retains its direct path.
# The user's own imported VLESS configuration publishes the same two markers from the same
# process, so it needs nothing here beyond not being judged by the hybrid lane's switches.
_AORUS_PROXY_SNIPPET = (
    "({ () -> MTSocksProxySettings? in\n"
    "                // App extensions do not own the in-process libXray core. Do not\n"
    "                // inherit the main app's PID-bound closed loopback endpoint.\n"
    "                if Bundle.main.bundleURL.pathExtension.lowercased() == \"appex\" { return nil }\n"
    "                guard let aorusStore = UserDefaults(suiteName: \"ng.session.store\") else {\n"
    "                    return MTSocksProxySettings(ip: \"127.0.0.1\", port: 38190, username: nil, password: nil, secret: nil)\n"
    "                }\n"
    "                let aorusCurrentPid = ProcessInfo.processInfo.processIdentifier\n"
    "                // The user imported their own VLESS configuration and switched it on. That\n"
    "                // lane owns the core instead of the hybrid one, and the switches below are\n"
    "                // the hybrid lane's — reading them here would send MTProto around the only\n"
    "                // inbound this client has. The mirror is written to a single predicate:\n"
    "                // enabled AND pointed at a server, so it is never true with nothing behind it.\n"
    "                let aorusUserVPN = aorusStore.bool(forKey: \"aorusgram_uservpn_enabled\")\n"
    "                // The user switched the built-in bypass off, so this client never\n"
    "                // redirects MTProto: it is stock Telegram on whatever proxy the user\n"
    "                // configured. The flag is mirrored out of the keychain on first access in\n"
    "                // every process, so its absence means \"not answered yet\" and keeps the\n"
    "                // fail-closed default below.\n"
    "                if !aorusUserVPN,\n"
    "                   aorusStore.object(forKey: \"aorusgram_connection_bypass_enabled\") != nil,\n"
    "                   !aorusStore.bool(forKey: \"aorusgram_connection_bypass_enabled\") {\n"
    "                    return nil\n"
    "                }\n"
    "                let aorusRequirement = aorusStore.dictionary(forKey: \"b4f013e2-54e9-4e4d-b2e1-30edc1e5b7ca\")\n"
    "                let aorusRequirementPid = aorusRequirement?[\"pid\"] as? NSNumber\n"
    "                let aorusRequired = aorusRequirementPid?.int32Value == aorusCurrentPid\n"
    "                    ? ((aorusRequirement?[\"required\"] as? NSNumber)?.boolValue ?? true)\n"
    "                    : true\n"
    "                guard aorusRequired else { return nil }\n"
    "                if let aorusEndpoint = aorusStore.dictionary(forKey: \"71d447f8-9128-4d18-b63c-ec11ef43ba26\"),\n"
    "                   let aorusPid = aorusEndpoint[\"pid\"] as? NSNumber,\n"
    "                   aorusPid.int32Value == aorusCurrentPid,\n"
    "                   let aorusPortValue = aorusEndpoint[\"port\"] as? NSNumber {\n"
    "                    let aorusPort = aorusPortValue.intValue\n"
    "                    if aorusPort > 0 && aorusPort <= 65535 {\n"
    "                        return MTSocksProxySettings(ip: \"127.0.0.1\", port: UInt16(aorusPort), username: nil, password: nil, secret: nil)\n"
    "                    }\n"
    "                }\n"
    "                return MTSocksProxySettings(ip: \"127.0.0.1\", port: 38190, username: nil, password: nil, secret: nil)\n"
    "            })()"
)


def patch_system_proxy_network_override(tg: Path) -> None:
    """Force the in-process REALITY endpoint onto every MTProto connection.

    The loopback proxy is applied at the network layer (MTApiEnvironment) and is NEVER
    stored in ProxySettings, so it never appears in the proxy list UI, has no
    on/off toggle, shows no proxy status icon and cannot be copied as a link.
    The remote VLESS/REALITY profile remains owned by AorusGram/libXray.
    """
    path = tg / "submodules/TelegramCore/Sources/Network/Network.swift"
    if not path.is_file():
        print("Network.swift not found, skip system proxy override")
        return
    t = path.read_text(encoding="utf-8")
    if "ng.session.store" in t:
        print("Network.swift: system proxy override already present")
        return
    anchor = (
        "            if let effectiveActiveServer = proxySettings?.effectiveActiveServer {\n"
        "                apiEnvironment = apiEnvironment.withUpdatedSocksProxySettings(effectiveActiveServer.mtProxySettings)\n"
        "            }\n"
    )
    injection = anchor + (
        "            // AorusGram: system proxy overrides any user setting and is applied\n"
        "            // invisibly at the network layer (never stored in ProxySettings).\n"
        "            if let aorusSystemProxy = " + _AORUS_PROXY_SNIPPET + " {\n"
        "                apiEnvironment = apiEnvironment.withUpdatedSocksProxySettings(aorusSystemProxy)\n"
        "            }\n"
    )
    if anchor in t:
        t = t.replace(anchor, injection, 1)
        path.write_text(t, encoding="utf-8")
        print("Network.swift: injected AorusGram system proxy override")
    else:
        print("WARNING: Network.swift proxy anchor not found — system proxy NOT applied")


def patch_system_proxy_runtime_monitor(tg: Path) -> None:
    """Keep the system proxy applied at runtime and reconnect when it arrives.

    1. The existing shared-data proxy monitor is patched so the AorusGram system
       proxy always wins over whatever (if anything) is in ProxySettings.
    2. A NotificationCenter observer reacts to `aorusgram_proxy_config_updated`
       (posted after libXray starts or stops) and re-applies the endpoint plus
       drops the connection, so first launch needs no relaunch.
    """
    path = tg / "submodules/TelegramCore/Sources/Account/Account.swift"
    if not path.is_file():
        print("Account.swift not found, skip system proxy runtime monitor")
        return
    t = path.read_text(encoding="utf-8")
    if "aorusgram_proxy_config_updated" in t:
        print("Account.swift: system proxy runtime monitor already present")
        return
    # 1) Force system proxy to win inside the existing monitor.
    monitor_anchor = (
        "        |> distinctUntilChanged).start(next: { activeServer in\n"
        "            let updated = activeServer.flatMap { activeServer -> MTSocksProxySettings? in\n"
        "                return activeServer.mtProxySettings\n"
        "            }\n"
    )
    monitor_replacement = (
        "        |> distinctUntilChanged).start(next: { activeServer in\n"
        "            var updated = activeServer.flatMap { activeServer -> MTSocksProxySettings? in\n"
        "                return activeServer.mtProxySettings\n"
        "            }\n"
        "            if let aorusSystemProxy = " + _AORUS_PROXY_SNIPPET + " { updated = aorusSystemProxy }\n"
    )

    # 2) Observer block, injected right after the monitor's closing `}))`.
    monitor_close = monitor_replacement + (
        "            network.context.updateApiEnvironment { environment in\n"
        "                let current = environment?.socksProxySettings\n"
        "                let updateNetwork: Bool\n"
        "                if let current = current, let updated = updated {\n"
        "                    updateNetwork = !current.isEqual(updated)\n"
        "                } else {\n"
        "                    updateNetwork = (current != nil) != (updated != nil)\n"
        "                }\n"
        "                if updateNetwork {\n"
        "                    network.dropConnectionStatus()\n"
        "                    return environment?.withUpdatedSocksProxySettings(updated)\n"
        "                } else {\n"
        "                    return nil\n"
        "                }\n"
        "            }\n"
        "        }))\n"
    )

    observer_block = monitor_close + (
        "        // AorusGram: apply the loopback endpoint as soon as libXray starts.\n"
        "        self.managedOperationsDisposable.add({ () -> Disposable in\n"
        "            let aorusObserver = NotificationCenter.default.addObserver(forName: NSNotification.Name(\"aorusgram_proxy_config_updated\"), object: nil, queue: nil) { _ in\n"
        "                let updated = " + _AORUS_PROXY_SNIPPET + "\n"
        "                network.context.updateApiEnvironment { environment in\n"
        "                    let current = environment?.socksProxySettings\n"
        "                    let updateNetwork: Bool\n"
        "                    if let current = current, let updated = updated {\n"
        "                        updateNetwork = !current.isEqual(updated)\n"
        "                    } else {\n"
        "                        updateNetwork = (current != nil) != (updated != nil)\n"
        "                    }\n"
        "                    if updateNetwork {\n"
        "                        network.dropConnectionStatus()\n"
        "                        return environment?.withUpdatedSocksProxySettings(updated)\n"
        "                    } else {\n"
        "                        return nil\n"
        "                    }\n"
        "                }\n"
        "            }\n"
        "            return ActionDisposable { NotificationCenter.default.removeObserver(aorusObserver) }\n"
        "        }())\n"
        "        // AorusGram: MTProto-level proxy-health beacon. A TCP probe cannot tell a\n"
        "        // degraded proxy (still accepts TCP but the MTProto handshake stalls) from a\n"
        "        // healthy one, so mirror the engine's own connection status into a defaults\n"
        "        // key that AorusProxyManager's watchdog reads. `proxyHasConnectionIssues` is\n"
        "        // the exact signal: when it stays set past the manager's threshold the current\n"
        "        // server is penalised and the client fails over to the best alternative.\n"
        "        self.managedOperationsDisposable.add(network.connectionStatus.start(next: { status in\n"
        "            let aorusDefaults = UserDefaults.standard\n"
        "            let aorusUnhealthyKey = \"aorusgram_proxy_unhealthy_since\"\n"
        "            let aorusConnectionKey = \"aorusgram_vless_connection_state\"\n"
        "            let aorusConnectionState: String\n"
        "            switch status {\n"
        "            case .waitingForNetwork:\n"
        "                aorusConnectionState = \"waiting_for_network\"\n"
        "            case let .connecting(_, aorusProxyHasIssues):\n"
        "                aorusConnectionState = aorusProxyHasIssues ? \"proxy_issue\" : \"connecting\"\n"
        "            case .updating:\n"
        "                aorusConnectionState = \"updating\"\n"
        "            case .online:\n"
        "                aorusConnectionState = \"online\"\n"
        "            }\n"
        "            let aorusNow = Date().timeIntervalSince1970\n"
        "            let aorusPrevious = aorusDefaults.dictionary(forKey: aorusConnectionKey)\n"
        "            let aorusSameProcess = (aorusPrevious?[\"pid\"] as? NSNumber)?.int32Value == ProcessInfo.processInfo.processIdentifier\n"
        "            let aorusSameState = (aorusPrevious?[\"state\"] as? String) == aorusConnectionState\n"
        "            let aorusStateSince = aorusSameProcess && aorusSameState\n"
        "                ? ((aorusPrevious?[\"since\"] as? NSNumber)?.doubleValue ?? aorusNow)\n"
        "                : aorusNow\n"
        "            aorusDefaults.set([\n"
        "                \"pid\": Int(ProcessInfo.processInfo.processIdentifier),\n"
        "                \"state\": aorusConnectionState,\n"
        "                \"since\": aorusStateSince,\n"
        "                \"updatedAt\": aorusNow\n"
        "            ], forKey: aorusConnectionKey)\n"
        "            if case let .connecting(_, aorusProxyHasIssues) = status, aorusProxyHasIssues {\n"
        "                // Stamp the first moment issues appeared; keep it until they clear.\n"
        "                if aorusDefaults.double(forKey: aorusUnhealthyKey) == 0 {\n"
        "                    aorusDefaults.set(Date().timeIntervalSince1970, forKey: aorusUnhealthyKey)\n"
        "                }\n"
        "            } else {\n"
        "                // Stalled updating/plain connecting is evaluated separately by\n"
        "                // AorusProxyManager using the preserved state timestamp.\n"
        "                if aorusDefaults.double(forKey: aorusUnhealthyKey) != 0 {\n"
        "                    aorusDefaults.set(0, forKey: aorusUnhealthyKey)\n"
        "                }\n"
        "            }\n"
        "        }))\n"
    )

    # The full original block we are replacing (monitor_anchor + its body + close).
    original_block = (
        monitor_anchor +
        "            network.context.updateApiEnvironment { environment in\n"
        "                let current = environment?.socksProxySettings\n"
        "                let updateNetwork: Bool\n"
        "                if let current = current, let updated = updated {\n"
        "                    updateNetwork = !current.isEqual(updated)\n"
        "                } else {\n"
        "                    updateNetwork = (current != nil) != (updated != nil)\n"
        "                }\n"
        "                if updateNetwork {\n"
        "                    network.dropConnectionStatus()\n"
        "                    return environment?.withUpdatedSocksProxySettings(updated)\n"
        "                } else {\n"
        "                    return nil\n"
        "                }\n"
        "            }\n"
        "        }))\n"
    )

    if original_block in t:
        t = t.replace(original_block, observer_block, 1)
        path.write_text(t, encoding="utf-8")
        print("Account.swift: injected system proxy runtime monitor + config-update observer")
    else:
        print("WARNING: Account.swift proxy monitor block not found — runtime monitor NOT applied")


def patch_unauthorized_system_proxy_runtime_monitor(tg: Path) -> None:
    """Hot-apply REALITY to the phone/code authorization network.

    Telegram's UnauthorizedAccount is created before a clean-install trial can be
    activated.  Its Network therefore starts on the fail-closed loopback port, but
    unlike an authorized Account it has no shared-data proxy monitor.  Observe the
    process-local endpoint publication for the lifetime of UnauthorizedAccount and
    replace the API environment in place once libXray is actually ready.
    """
    path = tg / "submodules/TelegramCore/Sources/Account/Account.swift"
    if not path.is_file():
        raise FileNotFoundError("Account.swift not found for unauthorized system proxy runtime monitor")
    t = path.read_text(encoding="utf-8")
    sentinel = "AorusGram: hot-apply REALITY to the unauthorized login network"
    if sentinel in t:
        print("Account.swift: unauthorized system proxy runtime monitor already present")
        return

    class_start = t.find("public class UnauthorizedAccount")
    class_end = t.find("\nfunc accountNetworkUsageInfoPath", class_start)
    if class_start < 0 or class_end < 0:
        raise RuntimeError("UnauthorizedAccount source boundaries not found")
    block = t[class_start:class_end]

    property_anchor = "    let stateManager: UnauthorizedAccountStateManager\n"
    property_replacement = (
        property_anchor
        + "    private var aorusProxyObserver: NSObjectProtocol?\n"
        + "    private var aorusConnectionStatusDisposable: Disposable?\n"
    )
    reset_anchor = "        self.stateManager.reset()\n"
    reset_index = block.find(reset_anchor)
    method_anchor = "    public func changedMasterDatacenterId"
    method_index = block.find(method_anchor, reset_index + len(reset_anchor))
    if property_anchor not in block:
        raise RuntimeError("UnauthorizedAccount state-manager anchor not found")
    if reset_index < 0 or method_index < 0:
        raise RuntimeError("UnauthorizedAccount initializer boundary not found")
    initializer_tail = block[reset_index + len(reset_anchor):method_index]
    if initializer_tail.strip() != "}":
        raise RuntimeError("Unexpected declarations after UnauthorizedAccount initializer")

    init_replacement = (
        "        self.stateManager.reset()\n"
        "\n"
        "        // AorusGram: hot-apply REALITY to the unauthorized login network.\n"
        "        // A clean-install trial is activated after this Network already exists,\n"
        "        // so the authorized Account observer cannot update phone/code requests.\n"
        "        self.aorusProxyObserver = NotificationCenter.default.addObserver(\n"
        "            forName: NSNotification.Name(\"aorusgram_proxy_config_updated\"),\n"
        "            object: nil,\n"
        "            queue: nil\n"
        "        ) { [weak network] _ in\n"
        "            guard let network else { return }\n"
        "            let updated = " + _AORUS_PROXY_SNIPPET + "\n"
        "            network.context.updateApiEnvironment { environment in\n"
        "                let current = environment?.socksProxySettings\n"
        "                let updateNetwork: Bool\n"
        "                if let current, let updated {\n"
        "                    updateNetwork = !current.isEqual(updated)\n"
        "                } else {\n"
        "                    updateNetwork = (current != nil) != (updated != nil)\n"
        "                }\n"
        "                guard updateNetwork else { return nil }\n"
        "                network.dropConnectionStatus()\n"
        "                return environment?.withUpdatedSocksProxySettings(updated)\n"
        "            }\n"
        "        }\n"
        "        self.aorusConnectionStatusDisposable = network.connectionStatus.start(next: { status in\n"
        "            let defaults = UserDefaults.standard\n"
        # UnauthorizedAccount exists only for phone/code login and can overlap the
        # newly-created authorized Account briefly. Never let its stale connection
        # status overwrite the authorized watchdog state during that handoff.
        "            let connectionKey = \"aorusgram_vless_unauthorized_connection_state\"\n"
        "            let state: String\n"
        "            switch status {\n"
        "            case .waitingForNetwork:\n"
        "                state = \"waiting_for_network\"\n"
        "            case let .connecting(_, proxyHasIssues):\n"
        "                state = proxyHasIssues ? \"proxy_issue\" : \"connecting\"\n"
        "            case .updating:\n"
        "                state = \"updating\"\n"
        "            case .online:\n"
        "                state = \"online\"\n"
        "            }\n"
        "            let now = Date().timeIntervalSince1970\n"
        "            let previous = defaults.dictionary(forKey: connectionKey)\n"
        "            let sameProcess = (previous?[\"pid\"] as? NSNumber)?.int32Value == ProcessInfo.processInfo.processIdentifier\n"
        "            let sameState = (previous?[\"state\"] as? String) == state\n"
        "            let since = sameProcess && sameState\n"
        "                ? ((previous?[\"since\"] as? NSNumber)?.doubleValue ?? now)\n"
        "                : now\n"
        "            defaults.set([\n"
        "                \"pid\": Int(ProcessInfo.processInfo.processIdentifier),\n"
        "                \"state\": state,\n"
        "                \"since\": since,\n"
        "                \"updatedAt\": now\n"
        "            ], forKey: connectionKey)\n"
        "        })\n"
        "    }\n"
        "\n"
        "    deinit {\n"
        "        if let aorusProxyObserver {\n"
        "            NotificationCenter.default.removeObserver(aorusProxyObserver)\n"
        "        }\n"
        "        self.aorusConnectionStatusDisposable?.dispose()\n"
        "    }\n"
        "    \n"
    )
    block = block[:reset_index] + init_replacement + block[method_index:]
    block = block.replace(property_anchor, property_replacement, 1)
    t = t[:class_start] + block + t[class_end:]
    path.write_text(t, encoding="utf-8")
    print("Account.swift: injected unauthorized system proxy runtime monitor")


def patch_chat_lock(tg: Path) -> None:
    """Chat Lock — protect selected chats behind Face ID / Touch ID / passcode.

    Three injection points, chosen so there is no way around the lock:

      1. navigateToChatControllerImpl (TelegramUI) — the single funnel EVERY chat opening goes
         through: tapping the chat list, notifications, deep links, forwards, search results,
         shared-media jumps. Gating here means one check covers them all. On a protected chat we
         prompt, and only re-enter the original navigation when authentication succeeds.
      2. activateChatPreview (ChatListUI) — long-press peek/preview does NOT go through
         navigation, so it would otherwise leak the chat's content. Cancel the gesture outright.
      3. ChatListItem (ChatListUI) — draw a lock badge. This reuses the existing secret-chat icon
         slot, so the row layout (icon width, title offset) is stock-tested and untouched.

    The badge deliberately only lands in the chat list. Peer pickers (adding an admin, contact
    search, forward target) use ContactsPeerItem, which is not patched — so no lock icons leak
    into those flows, exactly as requested.
    """
    ok = True

    # --- 1. Universal open-chat gate ------------------------------------------------------
    nav = tg / "submodules/TelegramUI/Sources/NavigateToChatController.swift"
    if nav.is_file():
        t = nav.read_text(encoding="utf-8")
        if "AorusGram: Chat Lock gate" in t:
            print("ChatLock: navigate gate already patched")
        else:
            if "import AorusGramUI\n" not in t:
                t = t.replace("import AccountContext\n", "import AccountContext\nimport AorusGramUI\n", 1)
            anchor = "public func navigateToChatControllerImpl(_ params: NavigateToChatControllerParams) {\n"
            inject = (
                anchor
                + "    // AorusGram: Chat Lock gate — every chat opening funnels through here, so a\n"
                + "    // protected chat cannot be reached by any route (list tap, notification, deep\n"
                + "    // link, forward, search) without authenticating first.\n"
                + "    if aorusChatLockRequiresAuth(params.context.account.id.int64, params.chatLocation.peerId.toInt64()) {\n"
                + "        aorusChatLockAuthenticate(params.context.account.id.int64) { success in\n"
                + "            if success {\n"
                + "                navigateToChatControllerImpl(params)\n"
                + "            }\n"
                + "        }\n"
                + "        return\n"
                + "    }\n"
            )
            if anchor in t:
                t = t.replace(anchor, inject, 1)
                nav.write_text(t, encoding="utf-8")
                print("ChatLock: gated navigateToChatControllerImpl")
            else:
                print("ChatLock: WARNING navigateToChatControllerImpl anchor not found")
                ok = False
    else:
        print("ChatLock: NavigateToChatController.swift not found — skip")
        ok = False

    # --- 2. Long-press preview gate --------------------------------------------------------
    cl = tg / "submodules/ChatListUI/Sources/ChatListController.swift"
    if cl.is_file():
        t = cl.read_text(encoding="utf-8")
        if "AorusGram: Chat Lock — never reveal" in t:
            print("ChatLock: preview gate already patched")
        else:
            if "import AorusGramUI\n" not in t:
                t = t.replace("import AccountContext\n", "import AccountContext\nimport AorusGramUI\n", 1)
            anchor = (
                "        self.chatListDisplayNode.mainContainerNode.activateChatPreview = "
                "{ [weak self] item, threadId, node, gesture, location in\n"
                "            guard let strongSelf = self else {\n"
                "                gesture?.cancel()\n"
                "                return\n"
                "            }\n"
            )
            inject = (
                anchor
                + "            // AorusGram: Chat Lock — never reveal a protected chat through the\n"
                + "            // long-press preview; it bypasses navigation and would leak content.\n"
                + "            if case let .peer(aorusPeerData) = item.content, let aorusPeer = aorusPeerData.peer.peer,\n"
                + "               aorusChatLockRequiresAuth(strongSelf.context.account.id.int64, aorusPeer.id.toInt64()) {\n"
                + "                gesture?.cancel()\n"
                + "                return\n"
                + "            }\n"
            )
            if anchor in t:
                t = t.replace(anchor, inject, 1)
                cl.write_text(t, encoding="utf-8")
                print("ChatLock: gated long-press chat preview")
            else:
                print("ChatLock: WARNING activateChatPreview anchor not found")
                ok = False
    else:
        print("ChatLock: ChatListController.swift not found — skip")
        ok = False

    # --- 3. Lock badge in the chat list ----------------------------------------------------
    item = tg / "submodules/ChatListUI/Sources/Node/ChatListItem.swift"
    if item.is_file():
        t = item.read_text(encoding="utf-8")
        if "AorusGram: Chat Protection badge" in t:
            print("ChatLock: badge already patched")
        else:
            if "import AorusGramUI\n" not in t:
                t = t.replace("import Foundation\n", "import Foundation\nimport AorusGramUI\n", 1)
            # Reuse the secret-chat icon slot: it is laid out before the title and its width is
            # already folded into titleIconsWidth, so the row geometry stays stock.
            anchor = (
                "            if isSecret {\n"
                "                currentSecretIconImage = PresentationResourcesChatList.secretIcon(item.presentationData.theme)\n"
                "            }\n"
            )
            inject = (
                anchor
                + "            // AorusGram: Chat Protection badge — a constant lock marks the chat as\n"
                + "            // protected regardless of the unlock state, so it never flickers between\n"
                + "            // shapes. Reuses the secret-chat icon slot, leaving row layout unchanged.\n"
                + "            if !isSecret && !isPeerGroup, case let .chatList(aorusIndex) = item.index,\n"
                + "               aorusChatLockIsProtected(item.context.account.id.int64, aorusIndex.messageIndex.id.peerId.toInt64()) {\n"
                + "                currentSecretIconImage = PresentationResourcesChatList.statusLockIcon(item.presentationData.theme)\n"
                + "            }\n"
            )
            if anchor in t:
                t = t.replace(anchor, inject, 1)
            else:
                print("ChatLock: WARNING secretIcon anchor not found — badge NOT added")
                ok = False

            # 3b. Hide the last-message preview. Protecting the chat but leaving its latest
            #     message readable in the list defeats the "someone picked up my phone" case.
            #     messageText/entities are already mutable here (stock reassigns messageText
            #     for PSA chats a few lines above), so this is a plain reassignment.
            legacy_text_anchor = (
                "                    contentData = .chat(itemPeer: itemPeer, threadInfo: threadInfo, peer: peer, "
                "hideAuthor: hideAuthor, messageText: messageText, messageEntities: messageEntities, "
                "spoilers: spoilers, customEmojiRanges: customEmojiRanges)\n"
            )
            rich_text_anchor = (
                "                    contentData = .chat(itemPeer: itemPeer, threadInfo: threadInfo, peer: peer, "
                "hideAuthor: hideAuthor, messageText: messageText, messageEntities: messageEntities, "
                "spoilers: spoilers, customEmojiRanges: customEmojiRanges, richTextPreview: richTextPreview)\n"
            )
            text_anchor = rich_text_anchor if rich_text_anchor in t else legacy_text_anchor
            text_inject = (
                "                    // AorusGram: Chat Protection — replace the preview of a protected\n"
                "                    // chat's last message, and drop its entities/spoilers/emoji so no\n"
                "                    // formatting artefacts survive. hideAuthor also suppresses the\n"
                "                    // \"Name:\" prefix in groups.\n"
                "                    if case let .chatList(aorusIdx) = item.index,\n"
                "                       aorusChatLockRequiresAuth(item.context.account.id.int64, aorusIdx.messageIndex.id.peerId.toInt64()) {\n"
                "                        messageText = aorusChatLockHiddenMessageText(item.presentationData.strings.baseLanguageCode)\n"
                "                        messageEntities = []\n"
                # spoilers / customEmojiRanges are Optionals: nil means \"none\", whereas an
                # empty array would still read as \"has spoilers\" downstream.
                "                        spoilers = nil\n"
                "                        customEmojiRanges = nil\n"
                + ("                        richTextPreview = nil\n" if text_anchor == rich_text_anchor else "")
                + "                        hideAuthor = true\n"
                + "                    }\n"
                + text_anchor
            )
            if text_anchor in t:
                t = t.replace(text_anchor, text_inject, 1)
            else:
                print("ChatLock: WARNING contentData anchor not found — preview NOT hidden")
                ok = False

            # 3c. Hide media thumbnails too — an attached photo is as revealing as the text.
            #     Reuses the stock displayMediaPreviews flag (already used for secret chats).
            media_anchor = (
                "                        var displayMediaPreviews = true\n"
                "                        if message._asMessage().containsSecretMedia {\n"
            )
            media_inject = (
                "                        var displayMediaPreviews = true\n"
                "                        // AorusGram: Chat Protection — no media thumbnails for protected chats.\n"
                "                        if aorusChatLockRequiresAuth(item.context.account.id.int64, message.id.peerId.toInt64()) {\n"
                "                            displayMediaPreviews = false\n"
                "                        }\n"
                "                        if message._asMessage().containsSecretMedia {\n"
            )
            if media_anchor in t:
                t = t.replace(media_anchor, media_inject, 1)
            else:
                print("ChatLock: WARNING displayMediaPreviews anchor not found — thumbnails NOT hidden")
                ok = False

            item.write_text(t, encoding="utf-8")
            print("ChatLock: added lock badge + hid message preview and media thumbnails")
    else:
        print("ChatLock: ChatListItem.swift not found — skip")
        ok = False

    # --- 3d. Hide drafts in protected rows without touching stored draft data ---------------
    #     ChatListItem renders draftState/mediaDraftContentType in a separate branch after
    #     the normal last-message preview. Clearing only these local presentation variables
    #     prevents a draft from bypassing the hidden-message text while leaving Postbox intact,
    #     so unlocking the chat restores the native draft immediately.
    if item.is_file():
        t = item.read_text(encoding="utf-8")
        draft_marker = "AorusGram: Chat Protection — hide drafts while locked"
        if draft_marker in t:
            print("ChatLock: protected draft presentation already patched")
        else:
            draft_anchor = (
                "                    draftState = draftStateValue\n"
                "                    mediaDraftContentType = peerData.mediaDraftContentType\n"
            )
            draft_inject = (
                "                    // AorusGram: Chat Protection — hide drafts while locked.\n"
                "                    // This only changes row presentation; the Postbox draft remains stored\n"
                "                    // and reappears natively as soon as the chat is unlocked.\n"
                "                    let aorusHideProtectedDraft: Bool\n"
                "                    if let aorusDraftPeer = peerValue.peer {\n"
                "                        aorusHideProtectedDraft = aorusChatLockRequiresAuth(item.context.account.id.int64, aorusDraftPeer.id.toInt64())\n"
                "                    } else {\n"
                "                        aorusHideProtectedDraft = false\n"
                "                    }\n"
                "                    draftState = aorusHideProtectedDraft ? nil : draftStateValue\n"
                "                    mediaDraftContentType = aorusHideProtectedDraft ? nil : peerData.mediaDraftContentType\n"
            )
            if t.count(draft_anchor) == 1:
                t = t.replace(draft_anchor, draft_inject, 1)
                item.write_text(t, encoding="utf-8")
                print("ChatLock: hid text/media drafts in locked chat rows")
            else:
                print(f"ChatLock: WARNING draft presentation anchor count={t.count(draft_anchor)} (expected 1)")
                ok = False

    # --- 3e. Keep protected chats out of message search ------------------------------------
    #     Global/local search would otherwise hand back the very message text the lock is
    #     meant to hide. Filtering at the single point where the pane returns its entries
    #     covers local, remote and public-post results at once. Matching on `stableId`
    #     (.messageId) rather than the 15-associated-value `.message` case keeps this robust.
    #     Uses isProtected, so clearing the switch — or removing the chat from the list —
    #     immediately makes its messages searchable again.
    search = tg / "submodules/ChatListUI/Sources/ChatListSearchListPaneNode.swift"
    if search.is_file():
        t = search.read_text(encoding="utf-8")
        if "AorusGram: Chat Protection — keep protected chats out of search" in t:
            print("ChatLock: search filter already patched")
        else:
            if "import AorusGramUI\n" not in t:
                t = t.replace("import AccountContext\n", "import AccountContext\nimport AorusGramUI\n", 1)
            anchor = "                return (entries, isSearching, query)\n"
            inject = (
                "                // AorusGram: Chat Protection — keep protected chats out of search\n"
                "                // results, otherwise search leaks the message text the lock hides.\n"
                "                entries = entries.filter { aorusEntry in\n"
                "                    if case let .messageId(aorusMessageId, _) = aorusEntry.stableId {\n"
                "                        return !aorusChatLockRequiresAuth(context.account.id.int64, aorusMessageId.peerId.toInt64())\n"
                "                    }\n"
                "                    return true\n"
                "                }\n"
                + anchor
            )
            if t.count(anchor) == 1:
                t = t.replace(anchor, inject, 1)
                search.write_text(t, encoding="utf-8")
                print("ChatLock: filtered protected chats out of message search")
            else:
                print(f"ChatLock: WARNING search return anchor count={t.count(anchor)} (expected 1)")
                ok = False
    else:
        print("ChatLock: ChatListSearchListPaneNode.swift not found — skip")
        ok = False

    # --- 3g. Forum (topic) groups ----------------------------------------------------------
    #     A forum group opens its TOPIC LIST inline, inside the same chat-list screen, without
    #     going through navigateToChatController — so the main gate never saw it and the topic
    #     list was readable (only entering a topic was blocked). Gate the inline path here, and
    #     the separate navigateToForumChannel entry point below.
    if cl.is_file():
        t = cl.read_text(encoding="utf-8")
        if "AorusGram: Chat Protection — a protected forum" in t:
            print("ChatLock: inline forum gate already patched")
        else:
            forum_anchor = (
                "                    if openAsInlineForum, case let .channel(channel) = peer, channel.isForum, threadId == nil {\n"
                "                        self.chatListDisplayNode.clearHighlightAnimated(true)\n"
                "                        if self.chatListDisplayNode.inlineStackContainerNode?.location == .forum(peerId: channel.id) {\n"
                "                            self.setInlineChatList(location: nil)\n"
                "                        } else {\n"
                "                            self.setInlineChatList(location: .forum(peerId: channel.id))\n"
                "                        }\n"
                "                        return\n"
                "                    }\n"
            )
            forum_repl = (
                "                    if openAsInlineForum, case let .channel(channel) = peer, channel.isForum, threadId == nil {\n"
                "                        // AorusGram: Chat Protection — a protected forum must not reveal even\n"
                "                        // its topic list, which opens inline and bypasses chat navigation.\n"
                "                        let aorusOpenForum: () -> Void = { [weak self] in\n"
                "                            guard let self else {\n"
                "                                return\n"
                "                            }\n"
                "                            self.chatListDisplayNode.clearHighlightAnimated(true)\n"
                "                            if self.chatListDisplayNode.inlineStackContainerNode?.location == .forum(peerId: channel.id) {\n"
                "                                self.setInlineChatList(location: nil)\n"
                "                            } else {\n"
                "                                self.setInlineChatList(location: .forum(peerId: channel.id))\n"
                "                            }\n"
                "                        }\n"
                "                        if aorusChatLockRequiresAuth(self.context.account.id.int64, channel.id.toInt64()) {\n"
                "                            aorusChatLockAuthenticate(self.context.account.id.int64) { success in\n"
                "                                if success {\n"
                "                                    aorusOpenForum()\n"
                "                                }\n"
                "                            }\n"
                "                        } else {\n"
                "                            aorusOpenForum()\n"
                "                        }\n"
                "                        return\n"
                "                    }\n"
            )
            if forum_anchor in t:
                t = t.replace(forum_anchor, forum_repl, 1)
                cl.write_text(t, encoding="utf-8")
                print("ChatLock: gated inline forum topic list")
            else:
                print("ChatLock: WARNING inline forum anchor not found — topic list NOT gated")
                ok = False

    if nav.is_file():
        t = nav.read_text(encoding="utf-8")
        if "AorusGram: Chat Protection — gate the forum" in t:
            print("ChatLock: forum navigation gate already patched")
        else:
            fn_anchor = (
                "public func navigateToForumChannelImpl(context: AccountContext, peerId: EnginePeer.Id, navigationController: NavigationController) {\n"
            )
            fn_inject = (
                fn_anchor
                + "    // AorusGram: Chat Protection — gate the forum topic list opened via this entry\n"
                + "    // point too (profile / deep links), not just the inline chat-list path.\n"
                + "    if aorusChatLockRequiresAuth(context.account.id.int64, peerId.toInt64()) {\n"
                + "        aorusChatLockAuthenticate(context.account.id.int64) { success in\n"
                + "            if success {\n"
                + "                navigateToForumChannelImpl(context: context, peerId: peerId, navigationController: navigationController)\n"
                + "            }\n"
                + "        }\n"
                + "        return\n"
                + "    }\n"
            )
            if fn_anchor in t:
                t = t.replace(fn_anchor, fn_inject, 1)
                nav.write_text(t, encoding="utf-8")
                print("ChatLock: gated navigateToForumChannel")
            else:
                print("ChatLock: WARNING navigateToForumChannelImpl anchor not found")
                ok = False

    # --- 3f. Observe protection changes in the chat list controller ------------------------
    if cl.is_file():
        t = cl.read_text(encoding="utf-8")
        if "AorusGram: Chat Protection — refresh rows" in t:
            print("ChatLock: chat-list observer already patched")
        else:
            anchor = "    override public func loadDisplayNode() {\n"
            inject = (
                anchor
                + "        // AorusGram: Chat Protection — refresh rows whenever protection changes\n"
                + "        // (chat added/removed, switch flipped, unlocked, or grace period lapsed),\n"
                + "        // so the badge and hidden preview update without leaving the screen.\n"
                + "        let aorusProtectionObserver = NotificationCenter.default.addObserver(forName: AorusChatLock.changedNotification, object: nil, queue: OperationQueue.main) { [weak self] _ in\n"
                + "            guard let self else {\n"
                + "                return\n"
                + "            }\n"
                + "            // Refresh the main list AND any inline (forum topics) stack:\n"
                + "            // effectiveContainerNode returns only the inline one while it is open,\n"
                + "            // which would leave the list behind it stale.\n"
                + "            let aorusRefresh: (ChatListContainerNode) -> Void = { container in\n"
                + "                container.updateState { state in\n"
                + "                var state = state\n"
                + "                // Rebuild the presentation data as a NEW object. Rows are only re-laid\n"
                + "                // out when the entries differ, and both ChatListNodeState and the peer\n"
                + "                // entries compare presentationData by identity (!==) — so an identical\n"
                + "                // copy is exactly the nudge needed, without altering appearance.\n"
                + "                let aorusPD = state.presentationData\n"
                + "                state.presentationData = ChatListPresentationData(theme: aorusPD.theme, fontSize: aorusPD.fontSize, strings: aorusPD.strings, dateTimeFormat: aorusPD.dateTimeFormat, nameSortOrder: aorusPD.nameSortOrder, nameDisplayOrder: aorusPD.nameDisplayOrder, disableAnimations: aorusPD.disableAnimations)\n"
                + "                return state\n"
                + "                }\n"
                + "            }\n"
                + "            aorusRefresh(self.chatListDisplayNode.mainContainerNode)\n"
                + "            if let aorusInline = self.chatListDisplayNode.inlineStackContainerNode {\n"
                + "                aorusRefresh(aorusInline)\n"
                + "            }\n"
                + "        }\n"
                + "        self.actionDisposables.add(ActionDisposable {\n"
                + "            NotificationCenter.default.removeObserver(aorusProtectionObserver)\n"
                + "        })\n"
            )
            if anchor in t:
                t = t.replace(anchor, inject, 1)
                cl.write_text(t, encoding="utf-8")
                print("ChatLock: chat list refreshes live on protection changes")
            else:
                print("ChatLock: WARNING loadDisplayNode anchor not found for observer")
                ok = False

    # --- 4. ChatListUI needs the AorusGramUI dep -------------------------------------------
    cl_build = tg / "submodules/ChatListUI/BUILD"
    if cl_build.is_file():
        t = cl_build.read_text(encoding="utf-8")
        dep = '        "//submodules/AorusGramUI:AorusGramUI",\n'
        if "//submodules/AorusGramUI:AorusGramUI" in t:
            print("ChatLock: ChatListUI BUILD dep already present")
        else:
            needle = '        "//submodules/TelegramPresentationData:TelegramPresentationData",\n'
            if needle in t:
                t = t.replace(needle, needle + dep, 1)
                cl_build.write_text(t, encoding="utf-8")
                print("ChatLock: added AorusGramUI dep to ChatListUI BUILD")
            else:
                print("ChatLock: WARNING ChatListUI BUILD needle not found")
                ok = False

    if not ok:
        print("ChatLock: NOT fully applied (see warnings above)")


def patch_show_stories_toggle(tg: Path) -> None:
    """Hide the chat-list Stories strip when the "Show Stories" toggle is off (default on).

    Every render path that shows the horizontal stories tray at the top of the chat list
    routes through the single predicate `shouldDisplayStoriesInChatListHeader(...)`. Gating
    that function to early-return false when `aorusgram_show_stories` is false cleanly hides
    the strip everywhere. Absent key = true (stock behaviour), so untouched installs keep
    stories. Idempotent.
    """
    path = tg / "submodules/ChatListUI/Sources/ChatListControllerNode.swift"
    if not path.is_file():
        print("ShowStories: ChatListControllerNode.swift not found — skip")
        return
    t = path.read_text(encoding="utf-8")
    if "AorusGram: hide the chat-list stories strip" in t:
        print("ShowStories: already patched")
        return
    anchor = "func shouldDisplayStoriesInChatListHeader(storySubscriptions: EngineStorySubscriptions, isHidden: Bool) -> Bool {\n"
    inject = (
        anchor
        + "    // AorusGram: hide the chat-list stories strip entirely when \"Show Stories\" is\n"
        + "    // off (default on). Every strip render path routes through this predicate.\n"
        + "    if !((UserDefaults.standard.object(forKey: \"aorusgram_show_stories\") as? Bool) ?? true) {\n"
        + "        return false\n"
        + "    }\n"
    )
    if anchor in t:
        t = t.replace(anchor, inject, 1)
        path.write_text(t, encoding="utf-8")
        print("ShowStories: gated stories strip on aorusgram_show_stories (default on)")
    else:
        print("ShowStories: WARNING shouldDisplayStoriesInChatListHeader anchor not found")


def patch_show_stories_live_refresh(tg: Path) -> None:
    """Apply the Show Stories toggle live (no restart) by re-laying out the chat list.

    `shouldDisplayStoriesInChatListHeader` re-reads `aorusgram_show_stories` on every layout
    (it runs inside updateNavigationBar), so all we need to apply a toggle live is to force a
    layout pass when the setting changes. Observe the `aorusgram_settings_changed` notification
    (posted by the settings screen) in loadDisplayNode and call requestLayout. The observer is
    added to the controller's existing actionDisposables set, so it is cleaned up in deinit.
    Idempotent.
    """
    path = tg / "submodules/ChatListUI/Sources/ChatListController.swift"
    if not path.is_file():
        print("ShowStoriesLive: ChatListController.swift not found — skip")
        return
    t = path.read_text(encoding="utf-8")
    if "AorusGram: apply the Show Stories toggle live" in t:
        print("ShowStoriesLive: already patched")
        return
    anchor = "    override public func loadDisplayNode() {\n"
    inject = (
        anchor
        + "        // AorusGram: apply the Show Stories toggle live (no restart). When settings\n"
        + "        // change, re-lay-out the chat list so the header re-reads aorusgram_show_stories.\n"
        + "        let aorusStoriesObserver = NotificationCenter.default.addObserver(forName: NSNotification.Name(\"aorusgram_settings_changed\"), object: nil, queue: OperationQueue.main) { [weak self] _ in\n"
        + "            self?.requestLayout(transition: .animated(duration: 0.4, curve: .spring))\n"
        + "        }\n"
        + "        self.actionDisposables.add(ActionDisposable {\n"
        + "            NotificationCenter.default.removeObserver(aorusStoriesObserver)\n"
        + "        })\n"
    )
    if anchor in t:
        t = t.replace(anchor, inject, 1)
        path.write_text(t, encoding="utf-8")
        print("ShowStoriesLive: chat list re-lays-out on settings change (live apply)")
    else:
        print("ShowStoriesLive: WARNING loadDisplayNode anchor not found")


def patch_disable_call_p2p(tg: Path) -> None:
    """Force every call through Telegram relays — never direct peer-to-peer.

    With P2P the two devices exchange UDP directly, exposing each other's real
    IP. Forcing relay keeps the user's IP private (the peer only ever sees a
    Telegram reflector). Call signalling already rides the proxied MTProto
    connection; the media leg uses Telegram relays. (MTProxy cannot tunnel the
    WebRTC/UDP media leg itself — that is a Telegram protocol limitation, so
    relay-forcing is the strongest available privacy guarantee for calls.)
    """
    path = tg / "submodules/TelegramVoip/Sources/OngoingCallContext.swift"
    if not path.is_file():
        print("OngoingCallContext.swift not found, skip call P2P disable")
        return
    t = path.read_text(encoding="utf-8")
    if "AorusGram: never use direct peer-to-peer" in t:
        print("OngoingCallContext.swift: call P2P disable already present")
        return

    anchor = "                var allowP2P = allowP2P\n"
    replacement = (
        "                var allowP2P = allowP2P\n"
        "                // AorusGram: never use direct peer-to-peer for calls — forces\n"
        "                // media through Telegram relays so the user's IP is never\n"
        "                // exposed to the call peer.\n"
        "                allowP2P = false\n"
    )
    if anchor in t:
        t = t.replace(anchor, replacement, 1)
        path.write_text(t, encoding="utf-8")
        print("OngoingCallContext.swift: forced allowP2P = false (relay-only calls)")
    else:
        print("WARNING: OngoingCallContext.swift allowP2P anchor not found — P2P NOT disabled")


def patch_conversation_export(tg: Path) -> None:
    """Add a "Download conversation" item to the profile "…" action menu.

    Injects a ContextMenuActionItem into the `.more` menu builder in
    PeerInfoScreenPerformButtonAction.swift. The item calls AorusConversationExport.start
    (a helper file copied into the same module by the workflow), which reads the chat's
    local text history, renders a native-looking PDF and opens the system share sheet.
    Inserted just before the menu builder's final `return .single(items)` so it appears
    for every chat type, at the bottom of the menu. Idempotent.
    """
    path = tg / "submodules/TelegramUI/Components/PeerInfo/PeerInfoScreen/Sources/PeerInfoScreenPerformButtonAction.swift"
    if not path.is_file():
        print("PeerInfoScreenPerformButtonAction.swift not found, skip conversation export")
        return
    t = path.read_text(encoding="utf-8")
    if "AorusConversationExport.start" in t:
        print("Conversation export: menu item already present")
        return
    # Place the item directly ABOVE the per-branch "clear history / delete" action.
    # The clearPeerHistory line is identical (20-space indent) in the user, channel
    # and group branches; injecting before each makes the item appear above Delete
    # for every chat type (only one branch executes at a time).
    anchor = "                    let clearPeerHistory = ClearPeerHistory(context: strongSelf.context, peer: "
    item = (
        "                    items.append(.action(ContextMenuActionItem(text: aorusL(\"Экспорт чата\", \"Export Chat\"), icon: { theme in\n"
        "                        return generateTintedImage(image: UIImage(bundleImageName: \"Chat/Context Menu/Download\"), color: theme.contextMenu.primaryColor)\n"
        "                    }, action: { [weak self] _, f in\n"
        "                        f(.dismissWithoutContent)\n"
        "                        if let strongSelf = self, let exportPeer = strongSelf.data?.peer {\n"
        "                            AorusConversationExport.start(context: strongSelf.context, peer: exportPeer, parentController: strongSelf.controller)\n"
        "                        }\n"
        "                    })))\n"
    )
    if anchor in t:
        count = t.count(anchor)
        t = t.replace(anchor, item + anchor)
        path.write_text(t, encoding="utf-8")
        print(f"Conversation export: injected Download Conversation menu item ({count}x, above Delete)")
    else:
        print("WARNING: PeerInfoScreenPerformButtonAction clear-history anchor not found — export item NOT added")


