def patch_unlimited_recent_stickers(tg: Path) -> None:
    """Keep the complete local recent-sticker history instead of Telegram's 20-item tail.

    Telegram inserts recent stickers through four independent paths. All four must stop
    trimming, and the server reconciliation must merge its short cloud list with the local
    tail instead of replacing it. GIFs and every other ordered list retain stock limits.
    """
    insertion_files = (
        (
            tg / "submodules/TelegramCore/Sources/State/SynchronizeRecentlyUsedMediaOperations.swift",
            1,
        ),
        (
            tg / "submodules/TelegramCore/Sources/State/ApplyUpdateMessage.swift",
            2,
        ),
        (
            tg / "submodules/TelegramCore/Sources/State/AccountStateManagementUtils.swift",
            1,
        ),
    )
    marker = "// AorusGram: unlimited recent stickers — preserve the complete local history."
    for path, expected_count in insertion_files:
        if not path.is_file():
            print(f"Unlimited recent stickers: {path.name} not found")
            continue
        t = path.read_text(encoding="utf-8")
        old = "removeTailIfCountExceeds: 20"
        relevant_old = [
            line for line in t.splitlines()
            if "CloudRecentStickers" in line and old in line
        ]
        relevant_new = [
            line for line in t.splitlines()
            if "CloudRecentStickers" in line and "removeTailIfCountExceeds: nil" in line
        ]
        if len(relevant_old) == expected_count:
            for line in relevant_old:
                t = t.replace(line, line.replace(old, "removeTailIfCountExceeds: nil"), 1)
        elif len(relevant_old) == 0 and len(relevant_new) == expected_count:
            print(f"Unlimited recent stickers: {path.name} insertion limits already patched")
        else:
            print(
                f"WARNING: {path.name} recent-sticker limiter count "
                f"old={len(relevant_old)} new={len(relevant_new)}, expected={expected_count}"
            )
        if marker not in t:
            import_anchor = "import Foundation\n"
            if import_anchor in t:
                t = t.replace(import_anchor, import_anchor + "\n" + marker + "\n", 1)
            else:
                t = marker + "\n" + t
        path.write_text(t, encoding="utf-8")

    managed = tg / "submodules/TelegramCore/Sources/State/ManagedRecentStickers.swift"
    if not managed.is_file():
        print("Unlimited recent stickers: ManagedRecentStickers.swift not found")
        return
    t = managed.read_text(encoding="utf-8")
    hash_marker = "AorusGram: hash only Telegram's cloud window"
    if hash_marker not in t:
        hash_anchor = (
            "        var itemIds = transaction.getOrderedListItemIds(collectionId: collectionId).compactMap(extractItemId)\n"
            "        if reverseHashOrder {\n"
        )
        hash_inject = (
            "        var itemIds = transaction.getOrderedListItemIds(collectionId: collectionId).compactMap(extractItemId)\n"
            "        // AorusGram: hash only Telegram's cloud window. The remaining entries are\n"
            "        // local history and must not force a needless full fetch on every sync.\n"
            "        if collectionId == Namespaces.OrderedItemList.CloudRecentStickers {\n"
            "            itemIds = Array(itemIds.prefix(20))\n"
            "        }\n"
            "        if reverseHashOrder {\n"
        )
        if t.count(hash_anchor) == 1:
            t = t.replace(hash_anchor, hash_inject, 1)
        else:
            print(f"WARNING: ManagedRecentStickers hash anchor count={t.count(hash_anchor)} (expected 1)")

    merge_marker = "AorusGram: unlimited recent stickers — retain the local tail"
    if merge_marker in t:
        managed.write_text(t, encoding="utf-8")
        print("Unlimited recent stickers: cloud merge already patched")
        return
    merge_anchor = (
        "                    return postbox.transaction { transaction -> Void in\n"
        "                        transaction.replaceOrderedItemListItems(collectionId: collectionId, items: items)\n"
        "                    }\n"
    )
    merge_inject = (
        "                    return postbox.transaction { transaction -> Void in\n"
        "                        // AorusGram: unlimited recent stickers — retain the local tail\n"
        "                        // when Telegram returns its shorter cloud list. Remote order stays\n"
        "                        // authoritative at the front; only unique local history is appended.\n"
        "                        if collectionId == Namespaces.OrderedItemList.CloudRecentStickers {\n"
        "                            var mergedIds = Set(items.compactMap { extractItemId($0.id) })\n"
        "                            for localItem in transaction.getOrderedListItems(collectionId: collectionId) {\n"
        "                                if let localId = extractItemId(localItem.id) {\n"
        "                                    if mergedIds.insert(localId).inserted {\n"
        "                                        items.append(localItem)\n"
        "                                    }\n"
        "                                } else {\n"
        "                                    items.append(localItem)\n"
        "                                }\n"
        "                            }\n"
        "                        }\n"
        "                        transaction.replaceOrderedItemListItems(collectionId: collectionId, items: items)\n"
        "                    }\n"
    )
    if t.count(merge_anchor) == 1:
        t = t.replace(merge_anchor, merge_inject, 1)
        managed.write_text(t, encoding="utf-8")
        print("Unlimited recent stickers: removed local cap and preserved cloud-sync tail")
    else:
        print(f"WARNING: ManagedRecentStickers merge anchor count={t.count(merge_anchor)} (expected 1)")


def patch_unlimited_pinned_chats(tg: Path) -> None:
    """Unlimited pinned chats: lift the toggle cap, keep pin icons past the stock limit
    of 5, and stop server sync from dropping extra local pins.

    Stock Telegram ties the pin *icon* to pinningIndex in the chat-list index. The toggle
    cap (maxPinnedChatCount = 5) is only one piece: sync can still replace a 6+ local pin
    list with the server's ~5 dialogs, and folder filters strip pinningIndex in the
    includePinnedAsUnpinned space. All three are patched here. (Idempotent.)
    """
    # 1) Lift the client-side cap when pinning / unpinning.
    toggle = tg / "submodules/TelegramCore/Sources/TelegramEngine/Peers/TogglePeerChatPinned.swift"
    if toggle.is_file():
        t = toggle.read_text(encoding="utf-8")
        if "AorusGram: unlimited pins" in t:
            print("Unlimited pins: TogglePeerChatPinned already patched")
        else:
            replacements = [
                ("limitCount = Int(userLimitsConfiguration.maxPinnedChatCount)",
                 "limitCount = Int.max // AorusGram: unlimited pins"),
                ("limitCount = Int(userLimitsConfiguration.maxArchivedPinnedChatCount)",
                 "limitCount = Int.max // AorusGram: unlimited pins"),
            ]
            changed = 0
            for old, new in replacements:
                if old in t:
                    t = t.replace(old, new, 1)
                    changed += 1
            if changed > 0:
                toggle.write_text(t, encoding="utf-8")
                print(f"Unlimited pins: patched {changed} toggle limit(s) → Int.max")
            else:
                print("WARNING: TogglePeerChatPinned limit assignments not found")
    else:
        print("TogglePeerChatPinned.swift not found, skip toggle cap")

    # 2) Sync: when local and remote baselines match but the server returns fewer pins
    #    (dialogs_pinned_limit ≈ 5), keep the longer local list so pinningIndex survives.
    sync = tg / "submodules/TelegramCore/Sources/State/ManagedSynchronizePinnedChatsOperations.swift"
    if sync.is_file():
        t = sync.read_text(encoding="utf-8")
        if "AorusGram: unlimited pins sync" in t:
            print("Unlimited pins: sync already patched")
        else:
            anchor = (
                "            if initialRemoteItemIds == localItemIds {\n"
                "                resultingItemIds = remoteItemIds\n"
            )
            inject = (
                "            if initialRemoteItemIds == localItemIds {\n"
                "                // AorusGram: unlimited pins sync — server caps at ~5; never drop extra local pins.\n"
                "                if remoteItemIds.count < localItemIds.count {\n"
                "                    resultingItemIds = localItemIds\n"
                "                } else {\n"
                "                    resultingItemIds = remoteItemIds\n"
                "                }\n"
            )
            if anchor in t:
                t = t.replace(anchor, inject, 1)
                sync.write_text(t, encoding="utf-8")
                print("Unlimited pins: patched ManagedSynchronizePinnedChatsOperations (keep local overflow)")
            else:
                print("WARNING: ManagedSynchronizePinnedChatsOperations sync anchor not found")
    else:
        print("ManagedSynchronizePinnedChatsOperations.swift not found, skip sync")

    # 3) UI: folder filters load global pins through includePinnedAsUnpinned, which stock
    #    code forces pinningIndex = nil (chat stays on top, pin icon hidden). Keep the
    #    postbox pinningIndex so the badge renders for pins 6+ inside folders too.
    view_state = tg / "submodules/Postbox/Sources/ChatListViewState.swift"
    if view_state.is_file():
        t = view_state.read_text(encoding="utf-8")
        if "AorusGram: unlimited pins icon" in t:
            print("Unlimited pins: ChatListViewState already patched")
        else:
            note = " // AorusGram: unlimited pins icon — keep pinningIndex so the pin badge shows for pins 6+ in folder tabs"
            # Replace the whole `var updatedIndex = index` + includePinnedAsUnpinned reset with
            # a plain `let updatedIndex = index`. This both preserves pinningIndex (so the pin
            # icon renders inside folders) and avoids a "never mutated; use let" Swift warning
            # that deleting only the reset block would leave behind. Three indent levels.
            pin_blocks = [
                (
                    "                    var updatedIndex = index\n"
                    "                    if case .includePinnedAsUnpinned = pinned {\n"
                    "                        updatedIndex = ChatListIndex(pinningIndex: nil, messageIndex: index.messageIndex)\n"
                    "                    }\n",
                    "                    let updatedIndex = index" + note + "\n",
                ),
                (
                    "                        var updatedIndex = index\n"
                    "                        if case .includePinnedAsUnpinned = pinned {\n"
                    "                            updatedIndex = ChatListIndex(pinningIndex: nil, messageIndex: index.messageIndex)\n"
                    "                        }\n",
                    "                        let updatedIndex = index" + note + "\n",
                ),
                (
                    "                                var updatedIndex = index\n"
                    "                                if case .includePinnedAsUnpinned = pinned {\n"
                    "                                    updatedIndex = ChatListIndex(pinningIndex: nil, messageIndex: index.messageIndex)\n"
                    "                                }\n",
                    "                                let updatedIndex = index" + note + "\n",
                ),
            ]
            changed = 0
            for old, new in pin_blocks:
                if old in t:
                    t = t.replace(old, new, 1)
                    changed += 1
            # In the .RemoveEntry branch `pinned` was bound only to feed the now-removed
            # includePinnedAsUnpinned reset; without it the build trips on the strict
            # "immutable value 'pinned' was never used" error, so silence that one binding.
            remove_old = (
                "                case let .RemoveEntry(indices):\n"
                "                    switch self.space {\n"
                "                    case let .group(spaceGroupId, pinned, _):\n"
            )
            remove_new = (
                "                case let .RemoveEntry(indices):\n"
                "                    switch self.space {\n"
                "                    case let .group(spaceGroupId, _, _):\n"
            )
            remove_fixed = remove_old in t
            if remove_fixed:
                t = t.replace(remove_old, remove_new, 1)
            if changed == 3 and remove_fixed:
                view_state.write_text(t, encoding="utf-8")
                print("Unlimited pins: patched ChatListViewState (3 sites, var→let, pinningIndex kept)")
            else:
                print(f"WARNING: ChatListViewState pin-icon sites: only {changed}/3 matched, remove-binding fixed={remove_fixed}")
    else:
        print("ChatListViewState.swift not found, skip pin icon UI")


def patch_user_messages_feature(tg: Path) -> None:
    """Wire up the "User's messages in a group" feature.

    The AorusUserMessagesChatContents class + openAorusUserMessages opener are compiled
    into TelegramUI (copied by the workflow). This patches the upstream chat code:
      1) Title — show the user's name for our customChatContents screen
         (ChatControllerContentData.swift).
      2) In that screen, the message long-press menu is a single "Go to message" action
         that jumps to the original message in the group
         (ChatInterfaceStateContextMenus.swift).
      3) In a group chat, a "User's Messages" item appears above Delete and opens the
         screen — only in groups/supergroups, with a real (non-anonymous) author, when
         the feature toggle is on (ChatInterfaceStateContextMenus.swift).
    All replacements are idempotent.
    """
    # --- 1. Title: user's name instead of the (empty) hashTagSearch title ---
    content_data = tg / "submodules/TelegramUI/Sources/ChatControllerContentData.swift"
    if content_data.is_file():
        t = content_data.read_text(encoding="utf-8")
        if "AorusUserMessagesChatContents" in t:
            print("User messages: title already patched")
        else:
            anchor = (
                "                    case .hashTagSearch:\n"
                "                        break\n"
                "                    case let .quickReplyMessageInput(shortcut, shortcutType):\n"
            )
            replacement = (
                "                    case .hashTagSearch:\n"
                "                        if let aorusUserMessages = customChatContents as? AorusUserMessagesChatContents {\n"
                "                            self.state.chatTitleContent = .custom(title: [ChatTitleContent.TitleTextItem(id: AnyHashable(0), content: .text(aorusUserMessages.peerName))], subtitle: nil, isEnabled: false)\n"
                "                        }\n"
                "                    case let .quickReplyMessageInput(shortcut, shortcutType):\n"
            )
            if anchor in t:
                t = t.replace(anchor, replacement, 1)
                content_data.write_text(t, encoding="utf-8")
                print("User messages: patched title (ChatControllerContentData)")
            else:
                print("WARNING: ChatControllerContentData hashTagSearch title anchor not found")
    else:
        print("ChatControllerContentData.swift not found, skip user-messages title")

    # --- 2 + 3. Context menu (single action inside screen + opener item in group) ---
    menus = tg / "submodules/TelegramUI/Sources/ChatInterfaceStateContextMenus.swift"
    if not menus.is_file():
        print("ChatInterfaceStateContextMenus.swift not found, skip user-messages menu")
        return
    t = menus.read_text(encoding="utf-8")
    if "openAorusUserMessages(" in t:
        print("User messages: context menu already patched")
        return

    # 2) In our screen, only "Go to message" — early-return with a single action.
    override_anchor = (
        "        var actions: [ContextMenuItem] = []\n"
        "\n"
        "        if isSharedMediaPolls && messages.count == 1 {\n"
    )
    override_block = (
        "        var actions: [ContextMenuItem] = []\n"
        "\n"
        "        if case let .customChatContents(aorusContents) = chatPresentationInterfaceState.subject, aorusContents is AorusUserMessagesChatContents, let aorusMsg = messages.first {\n"
        "            var aorusItems: [ContextMenuItem] = []\n"
        "            aorusItems.append(.action(ContextMenuActionItem(text: aorusL(\"Перейти к сообщению\", \"Go to Message\"), icon: { theme in\n"
        "                return generateTintedImage(image: UIImage(bundleImageName: \"Chat/Context Menu/GoToMessage\"), color: theme.actionSheet.primaryTextColor)\n"
        "            }, action: { c, _ in\n"
        "                c?.dismiss(completion: {\n"
        "                    guard let navigationController = controllerInteraction.navigationController() else {\n"
        "                        return\n"
        "                    }\n"
        "                    guard let aorusPeer = aorusMsg.peers[aorusMsg.id.peerId] else {\n"
        "                        return\n"
        "                    }\n"
        "                    context.sharedContext.navigateToChatController(NavigateToChatControllerParams(navigationController: navigationController, context: context, chatLocation: .peer(EnginePeer(aorusPeer)), subject: .message(id: .id(aorusMsg.id), highlight: ChatControllerSubject.MessageHighlight(quote: nil), timecode: nil, setupReply: false), keepStack: .always, useExisting: true))\n"
        "                })\n"
        "            })))\n"
        "            return ContextController.Items(content: .list(aorusItems), tip: nil)\n"
        "        }\n"
        "\n"
        "        if isSharedMediaPolls && messages.count == 1 {\n"
    )
    if override_anchor in t:
        t = t.replace(override_anchor, override_block, 1)
    else:
        print("WARNING: user-messages override anchor not found")

    # 3) "User's Messages" item directly above Delete, groups only, non-anonymous author.
    opener_anchor = "        if !isReplyThreadHead, (!data.messageActions.options.intersection([.deleteLocally, .deleteGlobally]).isEmpty || clearCacheAsDelete) {\n"
    opener_block = (
        "        if messages.count == 1, UserDefaults.standard.bool(forKey: \"aorusgram_feature_user_messages\"), let aorusChatPeer = chatPresentationInterfaceState.renderedPeer?.peer, let aorusAuthor = messages[0].author, aorusAuthor.id != aorusChatPeer.id {\n"
        "            var aorusIsGroup = false\n"
        "            if aorusChatPeer is TelegramGroup {\n"
        "                aorusIsGroup = true\n"
        "            } else if let aorusChannel = aorusChatPeer as? TelegramChannel, case .group = aorusChannel.info {\n"
        "                aorusIsGroup = true\n"
        "            }\n"
        "            if aorusIsGroup {\n"
        "                actions.append(.action(ContextMenuActionItem(text: aorusL(\"Сообщения пользователя\", \"User's Messages\"), icon: { theme in\n"
        "                    return generateTintedImage(image: UIImage(bundleImageName: \"Chat/Context Menu/GoToMessage\"), color: theme.actionSheet.primaryTextColor)\n"
        "                }, action: { c, _ in\n"
        "                    c?.dismiss(completion: {\n"
        "                        guard let navigationController = controllerInteraction.navigationController() else {\n"
        "                            return\n"
        "                        }\n"
        "                        openAorusUserMessages(context: context, groupPeerId: aorusChatPeer.id, author: aorusAuthor, navigationController: navigationController)\n"
        "                    })\n"
        "                })))\n"
        "            }\n"
        "        }\n"
        "        if !isReplyThreadHead, (!data.messageActions.options.intersection([.deleteLocally, .deleteGlobally]).isEmpty || clearCacheAsDelete) {\n"
    )
    if opener_anchor in t:
        t = t.replace(opener_anchor, opener_block, 1)
    else:
        print("WARNING: user-messages opener anchor not found")

    menus.write_text(t, encoding="utf-8")
    print("User messages: patched context menu (override + opener item)")


def patch_fix_blockquote_split(tg: Path) -> None:
    """Fix an upstream bug: a multi-line quote is sent as one quote per line.

    generateChatInputTextEntities turns the input's attributes into entities by walking
    enumerateAttributes, which starts a new run wherever the attribute dictionary changes.
    The newlines between quoted lines do not carry ChatTextInputAttributes.block, so a
    three-line quote becomes three BlockQuote entities separated by a one-character gap.

    Upstream has a merge pass for exactly this, and it is broken twice over: the `break
    scan` below the inner loop means only the FIRST blockquote is ever examined, so nothing
    after it merges, and it only joins ranges that touch exactly, which the newline gap
    prevents. The result is the per-line quote in the sent message — and, because the
    message round-trips back through these entities, in the edit field too.

    The replacement considers every blockquote and treats a single newline between two of
    them as the same quote continuing. A blank line (two or more newlines) still separates,
    so two quotes the user deliberately kept apart are not glued together. Idempotent.
    """
    path = tg / "submodules/TextFormat/Sources/GenerateTextEntities.swift"
    if not path.is_file():
        print("BlockQuoteSplit: GenerateTextEntities.swift not found — skip")
        return
    t = path.read_text(encoding="utf-8")
    if "aorusQuotesJoin" in t:
        print("BlockQuoteSplit: already patched")
        return
    anchor = (
        '    while true {\n'
        '        var hadReductions = false\n'
        '        \n'
        '        scan: for i in 0 ..< entities.count {\n'
        '            if case .BlockQuote = entities[i].type {\n'
        '                inner: for j in 0 ..< entities.count {\n'
        '                    if j == i {\n'
        '                        continue inner\n'
        '                    }\n'
        '                    if case .BlockQuote = entities[j].type {\n'
        '                        if entities[i].range.upperBound == entities[j].range.lowerBound || entities[i].range.lowerBound == entities[j].range.upperBound {\n'
        '                            entities[i].range = min(entities[i].range.lowerBound, entities[j].range.lowerBound) ..< max(entities[i].range.upperBound, entities[j].range.upperBound)\n'
        '                            entities.remove(at: j)\n'
        '                            \n'
        '                            hadReductions = true\n'
        '                            break scan\n'
        '                        }\n'
        '                    }\n'
        '                }\n'
        '                \n'
        '                break scan\n'
        '            }\n'
        '        }\n'
        '        \n'
        '        if !hadReductions {\n'
        '            break\n'
        '        }\n'
        '    }\n'
        '    \n'
    )
    replacement = (
        '    // AorusGram fix: put the pieces of one quote back together.\n'
        '    //\n'
        '    // enumerateAttributes above starts a new run wherever the attribute dictionary changes,\n'
        '    // and the newlines between the quoted lines do not carry the block attribute — so a\n'
        '    // three-line quote arrives here as three BlockQuote entities with a one-character gap\n'
        '    // between them, and the message is sent as one quote per line.\n'
        '    //\n'
        '    // Upstream already tries to merge, but it only ever examines the FIRST blockquote (the\n'
        '    // `break scan` that sat below the inner loop) and only joins ranges that touch exactly,\n'
        '    // so the newline defeats it. Both are fixed here: every blockquote is considered, and a\n'
        '    // single newline between two of them is treated as the same quote continuing onto the\n'
        '    // next paragraph. A blank line — two or more newlines — is a deliberate separation and\n'
        '    // is left alone, so two quotes the user meant to keep apart stay apart.\n'
        '    let aorusQuoteText = text.string as NSString\n'
        '    let aorusQuotesJoin: (Int, Int) -> Bool = { lower, upper in\n'
        '        if upper < lower {\n'
        '            return false\n'
        '        }\n'
        '        if upper == lower {\n'
        '            return true\n'
        '        }\n'
        '        if upper - lower != 1 || lower >= aorusQuoteText.length {\n'
        '            return false\n'
        '        }\n'
        '        return aorusQuoteText.character(at: lower) == 0x0a\n'
        '    }\n'
        '    while true {\n'
        '        var hadReductions = false\n'
        '\n'
        '        scan: for i in 0 ..< entities.count {\n'
        '            guard case .BlockQuote = entities[i].type else {\n'
        '                continue scan\n'
        '            }\n'
        '            inner: for j in 0 ..< entities.count {\n'
        '                if j == i {\n'
        '                    continue inner\n'
        '                }\n'
        '                guard case .BlockQuote = entities[j].type else {\n'
        '                    continue inner\n'
        '                }\n'
        '                let first = entities[i].range\n'
        '                let second = entities[j].range\n'
        '                if aorusQuotesJoin(first.upperBound, second.lowerBound) || aorusQuotesJoin(second.upperBound, first.lowerBound) {\n'
        '                    entities[i].range = min(first.lowerBound, second.lowerBound) ..< max(first.upperBound, second.upperBound)\n'
        '                    entities.remove(at: j)\n'
        '\n'
        '                    hadReductions = true\n'
        '                    break scan\n'
        '                }\n'
        '            }\n'
        '        }\n'
        '\n'
        '        if !hadReductions {\n'
        '            break\n'
        '        }\n'
        '    }\n'
        '\n'
    )
    if anchor not in t:
        print("WARNING: BlockQuoteSplit anchor not found — multi-line quotes stay split")
        return
    path.write_text(t.replace(anchor, replacement, 1), encoding="utf-8")
    print("BlockQuoteSplit: multi-line quotes now merge into one block")


def patch_fix_input_quote_split(tg: Path) -> None:
    """Draw a multi-line quote as ONE block in the composer, not one box per line.

    This is the same bug as BlockQuoteSplit, one layer earlier. The chat input no longer
    stores an NSAttributedString: ChatTextInputState keeps a structural ChatInputContent and
    derives the attributed string from it, so every keystroke round-trips through
    chatInputContent(from:) and attributedString(from:).

    chatInputContent(from:) cuts the text into paragraphs and gives every quoted paragraph
    its own .blockQuote block. attributedString(from:) then writes the block attribute over
    each block's own text and puts a plain "\n" between them, so the newline inside what the
    user selected as one quote carries no attribute. The composer draws a box per attributed
    run, hence a box per line — which is exactly what the screenshot shows, and what the user
    sees while typing even after the send path was fixed.

    The fix keeps a quote open across consecutive quoted lines: a second quoted paragraph is
    appended to the block the previous line opened instead of starting a new one. A line that
    is not quoted (a blank line, for instance) closes it, so two quotes the user deliberately
    kept apart stay apart.

    The flat text is untouched: ChatInputContent.plainText joins the inner paragraphs with the
    same "\n" that used to separate the two blocks, and blockFlatLength recurses into the
    interior, so every selection offset and length is the same before and after. Idempotent.
    """
    path = tg / "submodules/TextFormat/Sources/ChatInputContentConversion.swift"
    if not path.is_file():
        print("InputQuoteSplit: ChatInputContentConversion.swift not found — skip")
        return
    t = path.read_text(encoding="utf-8")
    if "aorusOpenQuote" in t:
        print("InputQuoteSplit: already patched")
        return

    loop_anchor = (
        "        paraRanges.append(NSRange(location: lineStart, length: end - lineStart))\n"
        "        for pr in paraRanges {\n"
    )
    if loop_anchor not in t:
        print("WARNING: InputQuoteSplit paragraph loop anchor not found — composer quotes stay split")
        return
    loop_replacement = (
        "        paraRanges.append(NSRange(location: lineStart, length: end - lineStart))\n"
        "        // AorusGram: index of the quote the previous line opened, if it is still open.\n"
        "        var aorusOpenQuote: Int? = nil\n"
        "        for pr in paraRanges {\n"
    )

    append_anchor = (
        "                blocks.append(.blockQuote(ChatInputBlockQuote(\n"
        "                    content: ChatInputContent(blocks: [.paragraph(ChatInputParagraph(style: .body, runs: runs))]),\n"
        "                    collapsed: quoteCollapsed)))\n"
        "            } else {\n"
        "                blocks.append(.paragraph(ChatInputParagraph(style: .body, runs: runs)))\n"
        "            }\n"
    )
    if append_anchor not in t:
        print("WARNING: InputQuoteSplit block anchor not found — composer quotes stay split")
        return
    append_replacement = (
        "                // AorusGram: a quote the previous line opened keeps going instead of a new\n"
        "                // block starting here. One block per line leaves the \"\\n\" between them\n"
        "                // unattributed, and the composer then draws a separate box per line.\n"
        "                if !quoteCollapsed, let aorusOpenIndex = aorusOpenQuote,\n"
        "                   case let .blockQuote(aorusOpen) = blocks[aorusOpenIndex], !aorusOpen.collapsed {\n"
        "                    var aorusMerged = aorusOpen.content.blocks\n"
        "                    aorusMerged.append(.paragraph(ChatInputParagraph(style: .body, runs: runs)))\n"
        "                    blocks[aorusOpenIndex] = .blockQuote(ChatInputBlockQuote(\n"
        "                        content: ChatInputContent(schemaVersion: aorusOpen.content.schemaVersion, blocks: aorusMerged),\n"
        "                        collapsed: false,\n"
        "                        author: aorusOpen.author))\n"
        "                } else {\n"
        "                    blocks.append(.blockQuote(ChatInputBlockQuote(\n"
        "                        content: ChatInputContent(blocks: [.paragraph(ChatInputParagraph(style: .body, runs: runs))]),\n"
        "                        collapsed: quoteCollapsed)))\n"
        "                    aorusOpenQuote = quoteCollapsed ? nil : blocks.count - 1\n"
        "                }\n"
        "            } else {\n"
        "                blocks.append(.paragraph(ChatInputParagraph(style: .body, runs: runs)))\n"
        "                aorusOpenQuote = nil\n"
        "            }\n"
    )

    t = t.replace(loop_anchor, loop_replacement, 1)
    t = t.replace(append_anchor, append_replacement, 1)
    path.write_text(t, encoding="utf-8")
    print("InputQuoteSplit: consecutive quoted lines now form one quote in the composer")


def patch_remove_send_logs(tg: Path) -> None:
    """Remove the debug "Send Logs" item from the message context menu.

    It only appears when file/console logging is enabled, but it's a developer affordance
    with no place in a shipping client. The enclosing `if` (and its condition) is kept so
    `downloadableMediaResourceInfos` / `loggingSettings` stay referenced — only the action
    body is dropped, avoiding unused-variable warnings under -warnings-as-errors. Idempotent.
    """
    path = tg / "submodules/TelegramUI/Sources/ChatInterfaceStateContextMenus.swift"
    if not path.is_file():
        print("ChatInterfaceStateContextMenus.swift not found, skip send-logs removal")
        return
    t = path.read_text(encoding="utf-8")
    if "AorusGram: removed the debug logs action" in t:
        print("Send Logs: already removed")
        return
    anchor = (
        "        if (loggingSettings.logToFile || loggingSettings.logToConsole) && !downloadableMediaResourceInfos.isEmpty {\n"
        "            actions.append(.action(ContextMenuActionItem(text: \"Send Logs\", icon: { theme in\n"
        "                return generateTintedImage(image: UIImage(bundleImageName: \"Chat/Context Menu/Message\"), color: theme.actionSheet.primaryTextColor)\n"
        "            }, action: { _, f in\n"
        "                triggerDebugSendLogsUI(context: context, additionalInfo: \"User has requested download logs for \\(downloadableMediaResourceInfos)\", pushController: { c in\n"
        "                    controllerInteraction.navigationController()?.pushViewController(c)\n"
        "                })\n"
        "                f(.default)\n"
        "            })))\n"
        "        }\n"
    )
    replacement = (
        "        if (loggingSettings.logToFile || loggingSettings.logToConsole) && !downloadableMediaResourceInfos.isEmpty {\n"
        "            // AorusGram: removed the debug logs action.\n"
        "        }\n"
    )
    if anchor in t:
        t = t.replace(anchor, replacement, 1)
        path.write_text(t, encoding="utf-8")
        print("Send Logs: removed debug context action")
    else:
        print("WARNING: Send Logs anchor not found — NOT removed")


def patch_app_bundle_name(tg: Path) -> None:
    """Rename the app bundle Telegram.app -> AorusGram.app.

    Adds bundle_name to the main ios_application. This renames the .app directory and the
    executable inside it; the Bazel target name ("Telegram"), the IPA artifact path and
    Make.py are unaffected (they key on the target name, not the bundle name). Idempotent.
    """
    path = tg / "Telegram/BUILD"
    if not path.is_file():
        print("Telegram/BUILD not found, skip app bundle_name rename")
        return
    t = path.read_text(encoding="utf-8")
    if 'bundle_name = "AorusGram"' in t:
        print("App bundle_name: already set")
        return
    anchor = (
        "ios_application(\n"
        "    name = \"Telegram\",\n"
        "    bundle_id ="
    )
    replacement = (
        "ios_application(\n"
        "    name = \"Telegram\",\n"
        "    bundle_name = \"AorusGram\",\n"
        "    bundle_id ="
    )
    if anchor in t:
        t = t.replace(anchor, replacement, 1)
        path.write_text(t, encoding="utf-8")
        print("App bundle_name: set to AorusGram (Telegram.app -> AorusGram.app)")
    else:
        print("WARNING: ios_application anchor not found — bundle_name NOT set")


def patch_call_proxy(tg: Path) -> None:
    """Route voice/video calls through the AorusGram SOCKS5 call proxy.

    PresentationCallManager creates each OngoingCallContext with `proxyServer:
    strongSelf.proxyServer` (sourced from the user's ProxySettings + useForCalls).
    We prefer the server-provided SOCKS5 call proxy (decoded fresh at call start by
    aorusCallProxyServerSettings(), copied into TelegramCallsUI), falling back to the
    user's setting when none is configured. Telegram only supports SOCKS5 for the call
    media leg — this keeps calls working where direct voice traffic is blocked.
    Reading at call start (not caching) means a freshly-fetched proxy is used
    immediately. Idempotent.
    """
    path = tg / "submodules/TelegramCallsUI/Sources/PresentationCallManager.swift"
    if not path.is_file():
        print("PresentationCallManager.swift not found, skip call proxy")
        return
    t = path.read_text(encoding="utf-8")
    if "aorusCallProxyServerSettings()" in t:
        print("Call proxy: already patched")
        return
    old = "proxyServer: strongSelf.proxyServer,"
    new = "proxyServer: aorusCallProxyServerSettings() ?? strongSelf.proxyServer,"
    count = t.count(old)
    if count > 0:
        t = t.replace(old, new)
        print(f"Call proxy: routed {count} call-start site(s) through SOCKS5 when configured")
    else:
        print("WARNING: PresentationCallManager proxyServer sites not found — call proxy NOT applied")

    # Force the active proxy to be used for calls whenever the proxy is enabled, even if
    # the user never flipped the "Use proxy for calls" toggle. Without this, proxyServer
    # is nil for calls on a proxied connection, so the call media has no path on networks
    # where direct voice is blocked → the call "connects" forever. Messages already work
    # because they always ride the proxied MTProto link; only the call leg was opting out.
    cond_old = ("                if settings.enabled && settings.useForCalls {\n"
                "                    strongSelf.proxyServer = settings.activeServer\n")
    cond_new = ("                if settings.enabled {\n"
                "                    // AorusGram: always route calls through the active proxy when the\n"
                "                    // proxy is enabled (ignore the per-user useForCalls toggle), so call\n"
                "                    // media has a working path wherever direct voice traffic is blocked.\n"
                "                    strongSelf.proxyServer = settings.activeServer\n")
    if cond_old in t:
        t = t.replace(cond_old, cond_new, 1)
        print("Call proxy: forced active proxy for calls (ignore useForCalls toggle)")
    else:
        print("WARNING: PresentationCallManager useForCalls condition not found — call proxy force NOT applied")

    path.write_text(t, encoding="utf-8")


def patch_tgcalls_v2_set_proxy(tg: Path) -> None:
    """Apply the SOCKS5 proxy to the v2 allocator, matching v1 NetworkManager.

    NativeNetworkingImpl stores `_proxy` but upstream v2 never forwards it to the
    allocator, so ReflectorPort sees an empty `proxy()`. The UDP transport patch uses
    that value to establish RFC 1928 UDP ASSOCIATE. Direct calls remain unchanged.
    """
    path = tg / "submodules/TgVoipWebrtc/tgcalls/tgcalls/v2/NativeNetworkingImpl.cpp"
    if not path.is_file():
        print("tgcalls set_proxy: NativeNetworkingImpl.cpp not found — skip")
        return
    t = path.read_text(encoding="utf-8")
    if "AorusGram: apply SOCKS5 proxy to the port allocator" in t:
        print("tgcalls set_proxy: already patched")
        return
    anchor = "    _portAllocator->set_step_delay(cricket::kMinimumStepDelay);\n"
    inject = (
        anchor
        + "\n"
        + "    // AorusGram: apply SOCKS5 proxy to the port allocator so reflector media can\n"
        + "    // use the call proxy. v1 NetworkManager::start() does\n"
        + "    // this; v2 omitted it, leaving Port::proxy() empty. Only when a proxy is\n"
        + "    // configured — direct calls are untouched.\n"
        + "    if (_proxy) {\n"
        + "        rtc::ProxyInfo proxyInfo;\n"
        + "        proxyInfo.type = rtc::ProxyType::PROXY_SOCKS5;\n"
        + "        proxyInfo.address = rtc::SocketAddress(_proxy->host, _proxy->port);\n"
        + "        proxyInfo.username = _proxy->login;\n"
        + "        proxyInfo.password = rtc::CryptString(CryptStringImpl(_proxy->password));\n"
        + "        _portAllocator->set_proxy(\"t/1.0\", proxyInfo);\n"
        + "    }\n"
    )
    if anchor in t:
        t = t.replace(anchor, inject, 1)
        path.write_text(t, encoding="utf-8")
        print("tgcalls set_proxy: applied SOCKS5 proxy to v2 port allocator")
    else:
        print("tgcalls set_proxy: WARNING set_step_delay anchor not found — NOT applied")


SOCKS5_CLIENT_CLASS = r"""// AorusGram: SOCKS5 client socket for the reflector TCP media leg.
// This WebRTC fork dropped rtc::AsyncSocksProxySocket (only PROXY_HTTPS survives in
// rtc_base/socket_adapters), so tgcalls could never actually tunnel call media through a
// SOCKS5 proxy. We implement a minimal, correct SOCKS5 client here (RFC 1928 + RFC 1929
// username/password auth) on top of this fork's BufferedReadAdapter, mirroring the historical
// WebRTC AsyncSocksProxySocket. It performs the handshake to the proxy on Connect(), then the
// tunnel behaves like a plain TCP socket to the reflector. Only ever instantiated when a
// SOCKS5 call proxy is configured, so direct calls never touch this code.
class AorusSocks5ProxySocket : public rtc::BufferedReadAdapter {
public:
    AorusSocks5ProxySocket(rtc::Socket* socket,
                           const rtc::SocketAddress& proxy,
                           const std::string& username,
                           const rtc::CryptString& password)
        : rtc::BufferedReadAdapter(socket, 1024),
          proxy_(proxy),
          user_(username),
          pass_(password),
          state_(SS_ERROR) {}

    AorusSocks5ProxySocket(const AorusSocks5ProxySocket&) = delete;
    AorusSocks5ProxySocket& operator=(const AorusSocks5ProxySocket&) = delete;

    int Connect(const rtc::SocketAddress& addr) override {
        dest_ = addr;
        state_ = SS_INIT;
        BufferInput(true);
        return rtc::BufferedReadAdapter::Connect(proxy_);
    }

    rtc::SocketAddress GetRemoteAddress() const override { return dest_; }

    int Close() override {
        state_ = SS_ERROR;
        return rtc::BufferedReadAdapter::Close();
    }

    rtc::Socket::ConnState GetState() const override {
        if (state_ < SS_TUNNEL) {
            return rtc::Socket::CS_CONNECTING;
        } else if (state_ == SS_TUNNEL) {
            return rtc::Socket::CS_CONNECTED;
        }
        return rtc::Socket::CS_CLOSED;
    }

protected:
    void OnConnectEvent(rtc::Socket* /*socket*/) override {
        SendHello();
    }

    void ProcessInput(char* data, size_t* len) override {
        if (state_ == SS_HELLO) {
            if (*len < 2) {
                return;
            }
            uint8_t ver = static_cast<uint8_t>(data[0]);
            uint8_t method = static_cast<uint8_t>(data[1]);
            Consume(data, len, 2);
            RTC_LOG(LS_INFO) << "AorusGram SOCKS5: hello reply ver=" << (int)ver << " method=" << (int)method;
            if (ver != 5) {
                Error(0);
                return;
            }
            if (method == 0) {
                SendConnect();
            } else if (method == 2) {
                SendAuth();
            } else {
                Error(method);
                return;
            }
        } else if (state_ == SS_AUTH) {
            if (*len < 2) {
                return;
            }
            uint8_t ver = static_cast<uint8_t>(data[0]);
            uint8_t status = static_cast<uint8_t>(data[1]);
            Consume(data, len, 2);
            RTC_LOG(LS_INFO) << "AorusGram SOCKS5: auth reply ver=" << (int)ver << " status=" << (int)status;
            if (ver != 1) {
                Error(255);
                return;
            }
            if (status != 0) {
                Error(status);
                return;
            }
            SendConnect();
        } else if (state_ == SS_CONNECT) {
            if (*len < 4) {
                return;
            }
            uint8_t ver = static_cast<uint8_t>(data[0]);
            uint8_t rep = static_cast<uint8_t>(data[1]);
            uint8_t atyp = static_cast<uint8_t>(data[3]);
            size_t needed;
            if (atyp == 1) {
                needed = 4 + 4 + 2;
            } else if (atyp == 4) {
                needed = 4 + 16 + 2;
            } else if (atyp == 3) {
                if (*len < 5) {
                    return;
                }
                needed = 4 + 1 + static_cast<uint8_t>(data[4]) + 2;
            } else {
                Error(0);
                return;
            }
            if (*len < needed) {
                return;
            }
            RTC_LOG(LS_INFO) << "AorusGram SOCKS5: connect reply ver=" << (int)ver << " rep=" << (int)rep << " atyp=" << (int)atyp;
            if (ver != 5 || rep != 0) {
                Error(rep);
                return;
            }
            Consume(data, len, needed);
            RTC_LOG(LS_INFO) << "AorusGram SOCKS5: tunnel established to the reflector via the proxy";
            state_ = SS_TUNNEL;
        }

        if (state_ != SS_TUNNEL) {
            return;
        }

        bool remainder = (*len > 0);
        BufferInput(false);
        SignalConnectEvent(this);
        // If SignalConnectEvent destroyed us we must not touch members; the callee owns
        // that contract exactly as the historical adapter did.
        if (remainder) {
            SignalReadEvent(this);
        }
    }

private:
    void Consume(char* data, size_t* len, size_t n) {
        *len -= n;
        if (*len > 0) {
            memmove(data, data + n, *len);
        }
    }

    void SendHello() {
        RTC_LOG(LS_INFO) << "AorusGram SOCKS5: connected to proxy, sending hello (auth=" << (user_.empty() ? "none" : "user/pass") << ")";
        rtc::ByteBufferWriter request;
        request.WriteUInt8(5);
        if (user_.empty()) {
            request.WriteUInt8(1);
            request.WriteUInt8(0);  // no authentication
        } else {
            request.WriteUInt8(2);
            request.WriteUInt8(0);  // no authentication
            request.WriteUInt8(2);  // username/password
        }
        DirectSend(request.Data(), request.Length());
        state_ = SS_HELLO;
    }

    void SendAuth() {
        rtc::ByteBufferWriter request;
        request.WriteUInt8(1);  // version of the auth subnegotiation
        request.WriteUInt8(static_cast<uint8_t>(user_.size()));
        request.WriteString(user_);
        size_t plen = pass_.GetLength();
        char* sensitive = new char[plen + 1];
        pass_.CopyTo(sensitive, true);
        request.WriteUInt8(static_cast<uint8_t>(plen));
        request.WriteBytes(reinterpret_cast<const uint8_t*>(sensitive), plen);
        DirectSend(request.Data(), request.Length());
        state_ = SS_AUTH;
        memset(sensitive, 0, plen);
        delete[] sensitive;
    }

    void SendConnect() {
        // Send the destination as a domain-name (ATYP=3) using the literal IP string.
        // Some SOCKS5 proxies reject raw IPv4/IPv6 CONNECT (RFC reply REP=8, "address type
        // not supported") but accept an IP passed in the domain field (their resolver
        // inet_pton's it). ATYP=3-with-IP-string is the broadly-compatible form.
        std::string destName;
        if (dest_.family() == AF_INET || dest_.family() == AF_INET6) {
            destName = dest_.ipaddr().ToString();
        } else {
            destName = dest_.hostname();
        }
        RTC_LOG(LS_INFO) << "AorusGram SOCKS5: sending CONNECT to " << destName << ":" << dest_.port() << " (atyp=domain)";
        rtc::ByteBufferWriter request;
        request.WriteUInt8(5);  // version
        request.WriteUInt8(1);  // command = connect
        request.WriteUInt8(0);  // reserved
        request.WriteUInt8(3);  // ATYP = domain name
        request.WriteUInt8(static_cast<uint8_t>(destName.size()));
        request.WriteString(destName);
        request.WriteUInt16(dest_.port());
        DirectSend(request.Data(), request.Length());
        state_ = SS_CONNECT;
    }

    void Error(int error) {
        RTC_LOG(LS_WARNING) << "AorusGram SOCKS5: FAILED at state=" << (int)state_ << " code=" << error << " (SS_HELLO=1 SS_AUTH=2 SS_CONNECT=3; at CONNECT rep 8=addr-type 2=not-allowed 5=refused)";
        state_ = SS_ERROR;
        BufferInput(false);
        Close();
        SetError(EPROTO);
        SignalCloseEvent(this, error);
    }

    rtc::SocketAddress proxy_;
    rtc::SocketAddress dest_;
    std::string user_;
    rtc::CryptString pass_;
    enum State {
        SS_INIT,
        SS_HELLO,
        SS_AUTH,
        SS_CONNECT,
        SS_TUNNEL,
        SS_ERROR
    } state_;
};

"""


def patch_tgcalls_reflector_socks5(tg: Path) -> None:
    """tgcalls: tunnel the reflector TCP media socket through the SOCKS5 proxy.

    CreateClientRawTcpSocket() in ReflectorPort.cpp takes a proxy_info argument but IGNORES
    it — it connects the raw socket straight to the reflector, so the Telegram relay leg never
    used the proxy even when one was set. Worse, this WebRTC fork removed rtc::AsyncSocksProxySocket
    entirely (its BasicPacketSocketFactory only honours PROXY_HTTPS), so there is no built-in
    SOCKS5 client to lean on. We inject a small, correct SOCKS5 client (AorusSocks5ProxySocket,
    RFC 1928 + RFC 1929) and wrap the reflector socket in it before Connect() when proxy_info is
    SOCKS5. The wrapper does the handshake to the proxy, then tunnels to the reflector address.
    Only triggers when proxy_info.type == PROXY_SOCKS5 — direct calls take the original path
    unchanged. Pairs with patch_tgcalls_v2_set_proxy (which populates proxy()). Idempotent.
    """
    path = tg / "submodules/TgVoipWebrtc/tgcalls/tgcalls/v2/ReflectorPort.cpp"
    if not path.is_file():
        print("tgcalls reflector SOCKS5: ReflectorPort.cpp not found — skip")
        return
    t = path.read_text(encoding="utf-8")
    if "AorusSocks5ProxySocket" in t:
        print("tgcalls reflector SOCKS5: already patched")
        return

    ok = True

    # a) includes: BufferedReadAdapter base, byte buffer, CryptString, memmove/memset.
    inc_anchor = "#include \"RawTcpSocket.h\"\n"
    inc_repl = (
        "#include \"rtc_base/socket_adapters.h\"\n"
        "#include \"rtc_base/byte_buffer.h\"\n"
        "#include \"rtc_base/crypt_string.h\"\n"
        "#include <cstring>\n"
        "#include <cerrno>\n"
        "#include \"RawTcpSocket.h\"\n"
    )
    if inc_anchor in t:
        t = t.replace(inc_anchor, inc_repl, 1)
    else:
        print("tgcalls reflector SOCKS5: WARNING include anchor not found")
        ok = False

    # b) define the SOCKS5 client class in the anonymous namespace, right before the
    #    CreateClientRawTcpSocket free function that uses it.
    class_anchor = "rtc::AsyncPacketSocket *CreateClientRawTcpSocket(\n"
    if class_anchor in t:
        t = t.replace(class_anchor, SOCKS5_CLIENT_CLASS + class_anchor, 1)
    else:
        print("tgcalls reflector SOCKS5: WARNING class-insertion anchor not found")
        ok = False

    # c) wrap the raw socket in the SOCKS5 client right before Connect().
    conn_anchor = (
        "    if (socket->Connect(remote_address) < 0) {\n"
        "        RTC_LOG(LS_ERROR) << \"TCP connect failed with error \" << socket->GetError();\n"
    )
    conn_repl = (
        "    // AorusGram: tunnel the reflector TCP socket through the SOCKS5 call proxy.\n"
        "    // Upstream ignores proxy_info here, so proxied calls could never reach the\n"
        "    // reflectors over the proxy. Only wraps when a SOCKS5 proxy is configured;\n"
        "    // direct calls take the original path unchanged.\n"
        "    if (proxy_info.type == rtc::ProxyType::PROXY_SOCKS5) {\n"
        "        RTC_LOG(LS_INFO) << \"AorusGram: routing reflector TCP socket via SOCKS5 proxy \"\n"
        "        << proxy_info.address.ToString();\n"
        "        socket = new AorusSocks5ProxySocket(socket, proxy_info.address, proxy_info.username, proxy_info.password);\n"
        "    }\n"
        "    \n"
        "    if (socket->Connect(remote_address) < 0) {\n"
        "        RTC_LOG(LS_ERROR) << \"TCP connect failed with error \" << socket->GetError();\n"
    )
    if conn_anchor in t:
        t = t.replace(conn_anchor, conn_repl, 1)
    else:
        print("tgcalls reflector SOCKS5: WARNING connect anchor not found")
        ok = False

    if ok:
        path.write_text(t, encoding="utf-8")
        print("tgcalls reflector SOCKS5: injected SOCKS5 client; reflector TCP now tunnels through the proxy")
    else:
        print("tgcalls reflector SOCKS5: NOT applied (anchor mismatch)")


def patch_intro_brand_logo(tg: Path) -> None:
    """Replace the OpenGL Telegram paper-plane logo on the intro/welcome screen
    with the AorusGram brand logo.

    The intro logo is rendered by an OpenGL GLKView (RMIntroViewController.m,
    fed by telegram_sphere.png / telegram_plane1.png textures). Rather than fight
    the GL animation we overlay an opaque UIImageView (the brand logo, embedded as
    a base64 PNG) as a subview of the GLKView, filling its bounds. Because it is a
    child of _glkView it inherits every position/scale transform the controller
    applies during page transitions, so it tracks the original logo exactly. The
    logo art sits on black, matching the intro background, so edges blend cleanly.
    """
    path = tg / "submodules/RMIntro/Sources/platform/ios/RMIntroViewController.m"
    if not path.is_file():
        print("IntroLogo: RMIntroViewController.m not found, skip")
        return
    t = path.read_text(encoding="utf-8")
    if "AorusGram: brand logo overlay" in t:
        print("IntroLogo: already injected")
        return
    anchor = "        [self.view addSubview:_glkView];\n"
    if anchor not in t:
        print("IntroLogo: addSubview:_glkView anchor not found — skipped")
        return
    inject = (
        "        // AorusGram: brand logo overlay (covers the GL Telegram logo)\n"
        "        {\n"
        "            UIImageView *aorusIntroLogo = [[UIImageView alloc] initWithFrame:_glkView.bounds];\n"
        "            aorusIntroLogo.contentMode = UIViewContentModeScaleAspectFit;\n"
        "            aorusIntroLogo.userInteractionEnabled = NO;\n"
        "            aorusIntroLogo.backgroundColor = _backgroundColor;\n"
        "            aorusIntroLogo.opaque = YES;\n"
        "            aorusIntroLogo.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;\n"
        "            NSData *aorusLogoData = [[NSData alloc] initWithBase64EncodedString:@\"\" options:NSDataBase64DecodingIgnoreUnknownCharacters];\n"
        "            if (aorusLogoData != nil) {\n"
        "                aorusIntroLogo.image = [UIImage imageWithData:aorusLogoData];\n"
        "            }\n"
        "            [_glkView addSubview:aorusIntroLogo];\n"
        "        }\n"
    )
    t = t.replace(anchor, anchor + inject, 1)
    path.write_text(t, encoding="utf-8")
    print("IntroLogo: brand logo overlay injected into RMIntroViewController.m")


def patch_intro_animation_snapshot(tg: Path) -> None:
    """Make the intro→login transition snapshot include the brand logo overlay.

    createAnimationSnapshot() captured `_glkView.snapshot`, which reads ONLY the
    OpenGL framebuffer (the original Telegram paper-plane) and ignores UIKit
    subviews — so our brand logo overlay was missing from the transition image and
    the Telegram logo flashed for a moment when the user tapped Continue. We render
    the full GLKView view hierarchy (GL content + opaque brand overlay on top)
    into the snapshot image instead. Idempotent.
    """
    path = tg / "submodules/RMIntro/Sources/platform/ios/RMIntroViewController.m"
    if not path.is_file():
        print("IntroSnapshot: RMIntroViewController.m not found, skip")
        return
    t = path.read_text(encoding="utf-8")
    if "AorusGram: snapshot full GLKView hierarchy" in t:
        print("IntroSnapshot: already patched")
        return
    old = "    UIImage *image = _glkView.snapshot;\n"
    if old not in t:
        print("IntroSnapshot: WARNING _glkView.snapshot anchor not found — skipped")
        return
    new = (
        "    // AorusGram: snapshot full GLKView hierarchy (GL content + brand logo\n"
        "    // overlay). _glkView.snapshot reads only the GL framebuffer (the original\n"
        "    // Telegram logo) and ignores UIKit subviews, which made that logo flash\n"
        "    // during the intro transition. Local strong ref avoids implicit self\n"
        "    // capture inside the block (-Wimplicit-retain-self).\n"
        "    GLKView *aorusGLKView = _glkView;\n"
        "    UIGraphicsImageRendererFormat *aorusFmt = [UIGraphicsImageRendererFormat preferredFormat];\n"
        "    aorusFmt.opaque = NO;\n"
        "    UIGraphicsImageRenderer *aorusRenderer = [[UIGraphicsImageRenderer alloc] initWithBounds:aorusGLKView.bounds format:aorusFmt];\n"
        "    UIImage *image = [aorusRenderer imageWithActions:^(UIGraphicsImageRendererContext * _Nonnull aorusCtx) {\n"
        "        [aorusGLKView drawViewHierarchyInRect:aorusGLKView.bounds afterScreenUpdates:NO];\n"
        "    }];\n"
    )
    t = t.replace(old, new, 1)
    path.write_text(t, encoding="utf-8")
    print("IntroSnapshot: createAnimationSnapshot now includes brand logo overlay")


def patch_alternate_icons(tg: Path) -> None:
    """Replace all alternate icons in Appearance settings with the user's icons.

    User icons live in patches/alticons/ as pre-rendered .alticon folders (loose
    PNGs, full iPhone+iPad size set) consumed by ios_application(alternate_icons);
    they switch the home-screen icon and double as the picker preview via
    UIImage(named:). The first entry "MainIcon" is the default
    (is_default=True): the picker shows the brand logo as "Основная" and selecting
    it reverts to the primary app icon. Old Telegram icons are deleted. BUILD
    alternate_icon_folders, AppDelegate getAvailableAlternateIcons list, and
    ThemeSettingsAppIconItem Russian display names are all patched atomically.
    """
    import shutil

    # (icon_name, display_name_ru, is_default)
    # "MainIcon" must be first and is_default=True (name avoids the Bazel target "Main"): selecting it calls
    # requestSetAlternateIconName(nil) which reverts to the primary brand icon
    # (AppIconLLC). Its preview appiconset (patches/alticons/Main.appiconset) is
    # rendered from the same brand logo, so the picker shows our icon as "Основная".
    # (icon_name, display_name_ru, display_name_en, is_default)
    ICONS = [
        ("MainIcon",   "Основная",     "Default",     True),
        ("Blue",       "Синяя",        "Blue",        False),
        ("Airplane",   "Самолет",      "Airplane",    False),
        ("Sky",        "Небо",         "Sky",         False),
        ("Ruby",       "Рубин",        "Ruby",        False),
        ("Sunset",     "Закат",        "Sunset",      False),
        ("Cosmos",     "Космос",       "Cosmos",      False),
        ("Cosmos2",    "Космос 2",     "Cosmos 2",    False),
        ("Duck",       "Утка",         "Ducky",       False),
        ("BlackWhite", "Черно-белая",  "Black White", False),
        ("Black",      "Черная",       "Black",       False),
        ("White",      "Белая",        "White",       False),
        ("GXCPlanet",  "GXC Планета",  "GXC Planet",  False),
        ("GXCClassic", "GXC Классика", "GXC Classic", False),
        ("OrbitBlack", "Орбита",       "Orbit",       False),
        ("OrbitWhite", "Орбита белая", "Orbit White", False),
    ]

    repo_root = Path(__file__).resolve().parent.parent
    alticons_src = repo_root / "patches/alticons"
    if not alticons_src.is_dir():
        print("AlternateIcons: patches/alticons not found, skip")
        return

    iosdir = tg / "Telegram/Telegram-iOS"
    if not iosdir.is_dir():
        print(f"AlternateIcons: {iosdir} not found, skip")
        return

    # Alternate icons in this build are .alticon folders of loose PNGs (no
    # Contents.json). The ios_application(alternate_icons=...) rule copies them to
    # the bundle root and synthesises CFBundleAlternateIcons; the settings picker
    # then loads previews via UIImage(named: "<Icon>") from those same bundle-root
    # PNGs. (AppIcons.xcassets is NOT bundled — its filegroup is unreferenced.)

    # Remove all stock .alticon folders so only our icons remain.
    for d in iosdir.glob("*.alticon"):
        shutil.rmtree(d)
        print(f"AlternateIcons: removed {d.name}")
    # Remove stock alternate appiconsets too (cosmetic — catalog is unused).
    xcassets = iosdir / "AppIcons.xcassets"
    if xcassets.is_dir():
        for name in ("BlackIcon", "BlackClassicIcon", "BlackFilledIcon",
                     "BlueClassicIcon", "BlueFilledIcon", "WhiteFilledIcon",
                     "New1", "New2", "Premium", "PremiumBlack", "PremiumTurbo"):
            d = xcassets / f"{name}.appiconset"
            if d.exists():
                shutil.rmtree(d)

    # Install our .alticon folders (pre-rendered loose PNGs from patches/alticons/).
    for icon_name, _, _, _ in ICONS:
        src_alticon = alticons_src / f"{icon_name}.alticon"
        if not src_alticon.is_dir():
            print(f"AlternateIcons: WARNING {icon_name}.alticon not in patches/alticons, skip")
            continue
        dst_alticon = iosdir / f"{icon_name}.alticon"
        if dst_alticon.exists():
            shutil.rmtree(dst_alticon)
        shutil.copytree(src_alticon, dst_alticon)
        print(f"AlternateIcons: installed {icon_name}.alticon ({len(list(src_alticon.glob('*.png')))} pngs)")

    # Update alternate_icon_folders in Telegram/BUILD
    build = tg / "Telegram/BUILD"
    if build.is_file():
        t = build.read_text(encoding="utf-8")
        new_folders = ", ".join(f'"{n}"' for n, _, _, _ in ICONS)
        t_new = re.sub(
            r"alternate_icon_folders\s*=\s*\[.*?\]",
            f"alternate_icon_folders = [{new_folders}]",
            t,
            flags=re.DOTALL,
        )
        if t_new != t:
            build.write_text(t_new, encoding="utf-8")
            print("AlternateIcons: updated alternate_icon_folders in BUILD")
        elif f"alternate_icon_folders = [{new_folders}]" in t:
            print("AlternateIcons: alternate_icon_folders already updated")
        else:
            print("AlternateIcons: WARNING alternate_icon_folders not found/changed in BUILD")

    # Patch AppDelegate.swift: replace getAvailableAlternateIcons icon list.
    # Idempotent: works on both the original Telegram tree (var icons = [)
    # and a cached tree that was already patched (let icons: [PresentationAppIcon]).
    delegate = tg / "submodules/TelegramUI/Sources/AppDelegate.swift"
    if delegate.is_file():
        t = delegate.read_text(encoding="utf-8")
        closure_marker = "getAvailableAlternateIcons: {"
        closure_idx = t.find(closure_marker)
        if closure_idx >= 0:
            return_icons_idx = t.find("return icons", closure_idx)
            # Accept both the original "var icons = [" and already-patched "let icons: [PresentationAppIcon]"
            icons_var_idx = -1
            for needle in ("var icons = [", "let icons: [PresentationAppIcon]"):
                idx = t.find(needle, closure_idx)
                if 0 <= idx < return_icons_idx:
                    icons_var_idx = idx
                    break
            if icons_var_idx >= 0 and return_icons_idx > icons_var_idx:
                # Replace the whole span from the declaration line through the end
                # of the "return icons" line, re-emitting both with clean indent.
                decl_line_start = t.rfind("\n", 0, icons_var_idx) + 1
                indent = " " * (icons_var_idx - decl_line_start)
                return_line_end = t.find("\n", return_icons_idx)
                if return_line_end < 0:
                    return_line_end = len(t)
                lines = [f'{indent}let icons: [PresentationAppIcon] = [']
                for n, _, _, is_default in ICONS:
                    default_arg = ", isDefault: true" if is_default else ""
                    lines.append(f'{indent}    PresentationAppIcon(name: "{n}", imageName: "{n}"{default_arg}),')
                lines.append(f'{indent}]')
                lines.append(f'{indent}return icons')
                new_block = "\n".join(lines)
                t = t[:decl_line_start] + new_block + t[return_line_end:]
                delegate.write_text(t, encoding="utf-8")
                print("AlternateIcons: patched AppDelegate getAvailableAlternateIcons")
            else:
                print("AlternateIcons: WARNING icons list not found in AppDelegate closure")
        else:
            print("AlternateIcons: WARNING getAvailableAlternateIcons not found in AppDelegate")

    # Patch ThemeSettingsAppIconItem.swift: add Russian display names to switch
    icon_item = tg / "submodules/SettingsUI/Sources/Themes/ThemeSettingsAppIconItem.swift"
    if icon_item.is_file():
        t = icon_item.read_text(encoding="utf-8")
        old_default = (
            "                                default:\n"
            "                                    name = icon.name"
        )
        # Idempotent cleanup: strip any previously-inserted AorusGram cases (including
        # the legacy "Main" name used before the rename to "MainIcon"). The name-
        # assignment RHS matches both the old plain-string form and the new
        # localized ternary form, so the patch is safe on fresh and cached trees.
        aorus_names = [n for n, _, _, _ in ICONS] + ["Main", "Violet"]
        for icon_name in aorus_names:
            t = re.sub(
                r'                                case "' + re.escape(icon_name) + r'":\n'
                r'                                    name = [^\n]*\n',
                '',
                t,
            )
        # Remove any previously-injected language flag line (idempotent re-inject below).
        # aorusL() reads the Telegram language itself, so no per-item flag is injected any
        # more. The line is still removed below so an older patched tree does not keep it.
        flag_line = (
            '                            let aorusIsRu = item.strings.baseLanguageCode == "ru" '
            '|| item.strings.baseLanguageCode.hasPrefix("ru-")\n'
        )
        switch_line = "                            switch icon.name {\n"
        t = t.replace(flag_line + switch_line, switch_line)

        if old_default in t and switch_line in t:
            # Inject the RU/EN selector once, right before the switch.
            # Localized cases: each name follows the in-app Telegram language.
            new_cases = "".join(
                f'                                case "{n}":\n'
                f'                                    name = aorusL("{ru}", "{en}")\n'
                for n, ru, en, _ in ICONS
            )
            t = t.replace(old_default, new_cases + old_default, 1)
            icon_item.write_text(t, encoding="utf-8")
            print("AlternateIcons: patched ThemeSettingsAppIconItem with localized names")
        else:
            print("AlternateIcons: WARNING default/switch branch not found in ThemeSettingsAppIconItem")

    # Patch ThemeSettingsController.swift: persist & restore the picker selection.
    # Telegram has no own storage for the chosen app icon — it relies solely on
    # UIApplication.alternateIconName. With our loose-PNG alternate icons that getter
    # reads back nil on relaunch / re-entering Appearance (even though the icon is
    # applied), so the picker fell back to the default. We remember the chosen name
    # on tap and use it to resolve the selection (system icon-setting is untouched).
    tsc = tg / "submodules/SettingsUI/Sources/Themes/ThemeSettingsController.swift"
    if tsc.is_file():
        t = tsc.read_text(encoding="utf-8")

        # (a) Robust selected-icon resolution: live alternateIconName (if it matches) ->
        #     our persisted choice -> default.
        read_anchor = (
            "    let currentAppIcon: PresentationAppIcon?\n"
            "    var appIcons = context.sharedContext.applicationBindings.getAvailableAlternateIcons()\n"
            "    if let alternateIconName = context.sharedContext.applicationBindings.getAlternateIconName() {\n"
            "        currentAppIcon = appIcons.filter { $0.name == alternateIconName }.first\n"
            "    } else {\n"
            "        currentAppIcon = appIcons.filter { $0.isDefault }.first\n"
            "    }\n"
        )
        read_new = (
            "    let currentAppIcon: PresentationAppIcon?\n"
            "    var appIcons = context.sharedContext.applicationBindings.getAvailableAlternateIcons()\n"
            "    // AorusGram: resolve the selected icon robustly (alternateIconName can read nil on relaunch).\n"
            "    let aorusStoredIcon = UserDefaults.standard.string(forKey: \"aorusgram_selected_app_icon\")\n"
            "    if let alternateIconName = context.sharedContext.applicationBindings.getAlternateIconName(), let aorusMatch = appIcons.first(where: { $0.name == alternateIconName }) {\n"
            "        currentAppIcon = aorusMatch\n"
            "    } else if let aorusStoredIcon = aorusStoredIcon, let aorusMatch = appIcons.first(where: { $0.name == aorusStoredIcon }) {\n"
            "        currentAppIcon = aorusMatch\n"
            "    } else {\n"
            "        currentAppIcon = appIcons.first(where: { $0.isDefault })\n"
            "    }\n"
        )

        # (b) Persist the chosen icon name when the user taps one.
        store_anchor = "                currentAppIconName.set(icon.name)\n"
        store_new = (
            "                currentAppIconName.set(icon.name)\n"
            "                UserDefaults.standard.set(icon.name, forKey: \"aorusgram_selected_app_icon\")\n"
        )

        if "aorusStoredIcon" in t or "aorusgram_selected_app_icon" in t:
            print("AppIconSelection: ThemeSettingsController already patched")
        elif read_anchor in t and store_anchor in t:
            t = t.replace(read_anchor, read_new, 1)
            t = t.replace(store_anchor, store_new, 1)
            tsc.write_text(t, encoding="utf-8")
            print("AppIconSelection: patched ThemeSettingsController (persist + restore selection)")
        else:
            print("AppIconSelection: WARNING ThemeSettingsController anchors not found — skip")


def patch_primary_app_icon(tg: Path) -> None:
    """Replace the primary home-screen app icon with the AorusGram brand icon.

    On the iOS 26 SDK the project's primary icon is produced from the Icon
    Composer bundle Telegram.icon (app_icons in Telegram/BUILD), which renders
    the stock blue Telegram plane. We switch the primary icon to a classic
    AppIconLLC.appiconset (fully supported on every SDK incl. 26) pre-rendered
    with the brand logo at all required sizes, and point app_icons at it. The
    Info.plist CFBundlePrimaryIcon is already CFBundleIconName=AppIconLLC, so the
    appiconset basename matches and actool wires it as the primary icon. The
    Icon Composer bundle and its filegroup stay defined but become unreferenced.

    Pre-rendered PNGs (no alpha, per Apple's requirement) live in the repo at
    patches/appicon/AppIconLLC.appiconset so the macOS runner needs no image
    tooling. Idempotent.
    """
    import shutil
    repo_root = Path(__file__).resolve().parent.parent
    src = repo_root / "patches/appicon/AppIconLLC.appiconset"
    if not src.is_dir():
        print(f"PrimaryIcon: source appiconset not found at {src}, skip")
        return
    dst = tg / "Telegram/Telegram-iOS/DefaultAppIcon.xcassets/AppIconLLC.appiconset"
    if not dst.parent.is_dir():
        print("PrimaryIcon: DefaultAppIcon.xcassets not found, skip")
        return
    # Replace the appiconset contents wholesale with the brand icon set.
    if dst.exists():
        shutil.rmtree(dst)
    shutil.copytree(src, dst)
    print(f"PrimaryIcon: installed brand AppIconLLC.appiconset ({len(list(src.glob('*.png')))} pngs)")

    # Point Telegram/BUILD app_icons at the appiconset instead of Icon Composer.
    build = tg / "Telegram/BUILD"
    if not build.is_file():
        print("PrimaryIcon: Telegram/BUILD not found, skip BUILD switch")
        return
    t = build.read_text(encoding="utf-8")
    new_line = '    app_icons = glob(["Telegram-iOS/DefaultAppIcon.xcassets/AppIconLLC.appiconset/*"]),  # AorusGram primary icon'
    if "DefaultAppIcon.xcassets/AppIconLLC.appiconset/*" in t:
        print("PrimaryIcon: BUILD app_icons already switched")
        return
    old_line = '    app_icons = [ ":{}_icon".format(name) for name in composer_icon_folders ],'
    if old_line in t:
        t = t.replace(old_line, new_line, 1)
        build.write_text(t, encoding="utf-8")
        print("PrimaryIcon: BUILD app_icons -> AppIconLLC.appiconset")
    else:
        print("PrimaryIcon: WARNING app_icons composer line not found — BUILD not switched")

def patch_app_delegate_language_bridge(tg: Path) -> None:
    """Persist the resolved AorusGram language (ru/en) to UserDefaults.

    The AorusGram client follows the in-app Telegram language. UI with direct
    access to PresentationData reads strings.baseLanguageCode itself; context-free
    call sites (the deleted-message chat bubble, TelegramCore postbox markers that
    write "Удалено"/"Оригинал") instead read the resolved value persisted here
    under the flat "aorusgram_lang" key. The observer fires on every presentation
    update, so a mid-session language change is picked up immediately.
    """
    delegate = tg / "submodules/TelegramUI/Sources/AppDelegate.swift"
    if not delegate.is_file():
        print("LanguageBridge: AppDelegate.swift not found — skipped")
        return
    t = delegate.read_text(encoding="utf-8")
    sentinel = "// AorusGram: persist resolved language for context-free call sites"
    if sentinel in t:
        print("LanguageBridge: already present")
        return
    anchor = "presentationDataPromise.set(sharedContext.presentationData)\n"
    idx = t.find(anchor)
    if idx < 0:
        print("LanguageBridge: anchor not found — skipped")
        return
    indent = " " * (idx - (t.rfind("\n", 0, idx) + 1))
    injection = (
        f"{indent}{sentinel}\n"
        f"{indent}let _ = (sharedContext.presentationData |> deliverOnMainQueue).start(next: {{ aorusPD in\n"
        f"{indent}    let aorusCode = aorusPD.strings.baseLanguageCode.lowercased()\n"
        f"{indent}    // The full Telegram base code. Everything AorusGram shows must follow the\n"
        f"{indent}    // language chosen INSIDE Telegram; the device language is only a fallback for\n"
        f"{indent}    // before this ever fires, i.e. a fresh install with no account yet.\n"
        f"{indent}    UserDefaults.standard.set(aorusCode, forKey: \"aorusgram_lang_code\")\n"
        f"{indent}    let aorusResolved = (aorusCode == \"ru\" || aorusCode.hasPrefix(\"ru-\") || aorusCode.hasPrefix(\"ru_\")) ? \"ru\" : \"en\"\n"
        f"{indent}    UserDefaults.standard.set(aorusResolved, forKey: \"aorusgram_lang\")\n"
        f"{indent}}})\n"
    )
    insert_at = idx + len(anchor)
    t = t[:insert_at] + injection + t[insert_at:]
    delegate.write_text(t, encoding="utf-8")
    print("LanguageBridge: injected presentationData language observer into AppDelegate")


def patch_default_dark_theme(tg: Path) -> None:
    """Make the dark theme the default for fresh installs.

    PresentationThemeSettings.defaultSettings ships with theme=.dayClassic and an
    automatic switch trigger of .system (so the app follows the device appearance).
    We pin a dark default that does not auto-switch: theme=.night and
    trigger=.explicitNone. Existing users keep their stored preference; only the
    default applied on first launch changes.
    """
    settings_file = tg / "submodules/TelegramUIPreferences/Sources/PresentationThemeSettings.swift"
    if not settings_file.is_file():
        print("DarkDefault: PresentationThemeSettings.swift not found — skipped")
        return
    t = settings_file.read_text(encoding="utf-8")
    old_default = (
        "return PresentationThemeSettings(theme: .builtin(.dayClassic), themePreferredBaseTheme: [:], "
        "themeSpecificAccentColors: [:], themeSpecificChatWallpapers: [:], useSystemFont: true, "
        "fontSize: .regular, listsFontSize: .regular, chatBubbleSettings: .default, "
        "automaticThemeSwitchSetting: AutomaticThemeSwitchSetting(force: false, trigger: .system, "
        "theme: .builtin(.night)), largeEmoji: true, reduceMotion: false)"
    )
    new_default = (
        "return PresentationThemeSettings(theme: .builtin(.dayClassic), themePreferredBaseTheme: [:], "
        "themeSpecificAccentColors: [:], themeSpecificChatWallpapers: [:], useSystemFont: true, "
        "fontSize: .regular, listsFontSize: .regular, chatBubbleSettings: .default, "
        "automaticThemeSwitchSetting: AutomaticThemeSwitchSetting(force: false, trigger: .explicitNone, "
        "theme: .builtin(.night)), largeEmoji: true, reduceMotion: false)"
    )
    if new_default in t:
        print("DarkDefault: already applied")
        return
    if old_default in t:
        t = t.replace(old_default, new_default, 1)
        settings_file.write_text(t, encoding="utf-8")
        print("DarkDefault: defaultSettings theme -> .night (trigger .explicitNone)")
    else:
        print("DarkDefault: WARNING defaultSettings line not found (upstream drift) — skipped")


def _add_aorus_build_dep(build_path: Path) -> None:
    """Add the AorusBadge dependency to a Bazel BUILD file (idempotent)."""
    if not build_path.is_file():
        return
    bt = build_path.read_text(encoding="utf-8")
    if "//submodules/AorusBadge:AorusBadge" in bt:
        return
    needle = '        "//submodules/TelegramPresentationData:TelegramPresentationData",\n'
    if needle in bt:
        bt = bt.replace(needle, needle + '        "//submodules/AorusBadge:AorusBadge",\n', 1)
        build_path.write_text(bt, encoding="utf-8")
        print(f"Badges: added AorusBadge dep to {build_path.parent.name} BUILD")
    else:
        print(f"Badges: WARNING {build_path.parent.name} BUILD needle not found")


def _add_aorusgramui_build_dep(tg: Path, package: str, label: str) -> bool:
    """Give a module access to aorusL()/AorusL10nTable (idempotent).

    AorusGramUI owns the single translation table the whole client reads, so any module
    that shows AorusGram strings needs the dep. AorusGramUI itself depends on none of
    these packages, so no cycle is possible.

    Returns True when the dep is present afterwards. The caller must not add the import
    unless it is — an import without the dep does not fail softly, it fails the build.
    """
    build_path = tg / package / "BUILD"
    if not build_path.is_file():
        print(f"L10n: {package} BUILD not found — skipped")
        return False
    bt = build_path.read_text(encoding="utf-8")
    if "//submodules/AorusGramUI" in bt:
        return True
    for needle in (
        f'        "{label}",\n',
        '        "//submodules/Display",\n',
        '        "//submodules/Display:Display",\n',
    ):
        if needle in bt:
            bt = bt.replace(needle, needle + '        "//submodules/AorusGramUI",\n', 1)
            build_path.write_text(bt, encoding="utf-8")
            print(f"L10n: added AorusGramUI dep to {package}")
            return True
    # Last resort: the first deps list in the file. Every swift_library has one, so this
    # only misses if the BUILD has no deps at all.
    match = re.search(r"^(\s*)deps = \[\n", bt, re.M)
    if match:
        indent = match.group(1) + "    "
        bt = (
            bt[: match.end()]
            + f'{indent}"//submodules/AorusGramUI",\n'
            + bt[match.end() :]
        )
        build_path.write_text(bt, encoding="utf-8")
        print(f"L10n: added AorusGramUI dep to {package} (deps anchor)")
        return True
    print(f"L10n: WARNING — no dep anchor in {package} BUILD, translations will not build")
    return False


def _ensure_aorusgramui_import(path: Path) -> None:
    """Make aorusL() visible in a patched Telegram file (idempotent)."""
    if not path.is_file():
        return
    t = path.read_text(encoding="utf-8")
    if "import AorusGramUI" in t:
        return
    # Anchoring on "\nimport " alone misses a file whose only import is its very first line —
    # match at the start of the text too.
    match = re.search(r"^import ", t, re.M)
    if match is None:
        print(f"L10n: WARNING — no import block in {path.name}, aorusL will not resolve")
        return
    t = t[: match.start()] + "import AorusGramUI\n" + t[match.start() :]
    path.write_text(t, encoding="utf-8")
    print(f"L10n: added import AorusGramUI to {path.name}")


def patch_translation_deps(tg: Path) -> None:
    """Wire up every module that ended up calling aorusL().

    Each AorusGram string in the client resolves through one table that lives in
    AorusGramUI, and the patches above inject those strings into Telegram's own files. Which
    files those are shifts whenever a patch moves its anchor, so the list is discovered from
    the patched tree rather than written down here — a hardcoded list is exactly how
    ChatEmptyNode ended up calling aorusL() with no dep and failing the build.

    Must run last, after every patch has written its injection.

    AorusGramUI depends on none of these packages, so no cycle is possible. TelegramCore is
    the exception it cannot serve — it sits below AorusGramUI, and its two edit-history
    labels are resolved locally instead.
    """
    submodules = tg / "submodules"
    if not submodules.is_dir():
        print("L10n: submodules not found — skipped")
        return

    wired = 0
    for swift_file in sorted(submodules.rglob("*.swift")):
        if "AorusGramUI" in swift_file.parts:
            continue
        body = swift_file.read_text(encoding="utf-8", errors="replace")
        # Comments name the helper too; only real call sites need the dep. AorusLang counts
        # as well — a file can reach for the language or its locale without calling aorusL.
        code = "\n".join(line.split("//")[0] for line in body.split("\n"))
        if "aorusL(" not in code and "AorusLang." not in code:
            continue
        package = swift_file.parent
        while package != tg and not (package / "BUILD").is_file():
            package = package.parent
        if package == tg:
            print(f"L10n: WARNING — no BUILD owns {swift_file.name}, aorusL will not resolve")
            continue
        relative = package.relative_to(tg).as_posix()
        # The import is only added once the dep is in place: an import without it is a build
        # failure, while skipping both merely leaves that one screen in English.
        if not _add_aorusgramui_build_dep(tg, relative, "//submodules/Display"):
            continue
        _ensure_aorusgramui_import(swift_file)
        wired += 1
    print(f"L10n: {wired} file(s) outside AorusGramUI wired to the translation table")


def patch_aorus_badges(tg: Path) -> None:
    """Local AorusGram badge system.

    1. Native verified: TelegramCore `isVerified` returns true for the AorusGram
       channel/chat ids, so the genuine Telegram checkmark is shown in every
       surface (chat list, header, profile, search) with no custom rendering.
    2. Custom user badges (DEV tag, meme cat) are injected into the chat-list /
       search rows via the existing EmojiStatusComponent `.image` slot, which is
       laid out AFTER the premium/credibility icon — so it never replaces a
       system badge and respects the premium-first ordering.
    """
    # --- 1. Native verified flag for AorusGram channels/chats ---
    peer_utils = tg / "submodules/TelegramCore/Sources/Utils/PeerUtils.swift"
    if peer_utils.is_file():
        t = peer_utils.read_text(encoding="utf-8")
        anchor = "    var isVerified: Bool {\n        switch self {"
        if "AorusGram local verification" in t:
            print("Badges: PeerUtils isVerified already patched")
        elif anchor in t:
            injected = (
                "    var isVerified: Bool {\n"
                "        // AorusGram local verification — show the native Telegram checkmark\n"
                "        // for our official channel/chat without any server flag.\n"
                "        if [3956524111, 3710166840, 8887700542].contains(self.id.id._internalGetInt64Value()) {\n"
                "            return true\n"
                "        }\n"
                "        switch self {"
            )
            t = t.replace(anchor, injected, 1)
            peer_utils.write_text(t, encoding="utf-8")
            print("Badges: patched PeerUtils isVerified (native verified for AorusGram peers)")
        else:
            print("Badges: WARNING isVerified anchor not found in PeerUtils")
    else:
        print("Badges: PeerUtils.swift not found — skipped")

    # --- 2. DEV / meme badge image in chat-list & search rows (display only) ---
    # Per product decision the tap→toast lives ONLY in the profile; the list and
    # search just show the badge in the verified slot (after premium).
    chat_list_item = tg / "submodules/ChatListUI/Sources/Node/ChatListItem.swift"
    if chat_list_item.is_file():
        t = chat_list_item.read_text(encoding="utf-8")
        if "import AorusBadge" not in t:
            t = t.replace("import Foundation\n", "import Foundation\nimport AorusBadge\n", 1)
        # Inject before each `if peer.isVerified {` (two indentation variants).
        # Anchors/markers are newline-prefixed so a shorter indent never matches as
        # a leading-space substring of a deeper-indented injected line.
        for indent in ("                            ", "                    "):
            anchor = f"\n{indent}if peer.isVerified {{"
            inject_marker = f"\n{indent}if currentVerifiedIconContent == nil, let aorusBadgeImage = AorusBadge.image(forPeerRawId:"
            inject = (
                f"\n{indent}if currentVerifiedIconContent == nil, let aorusBadgeImage = AorusBadge.image(forPeerRawId: peer.id.id._internalGetInt64Value(), height: 16.0, accent: item.presentationData.theme.list.itemAccentColor) {{\n"
                f"{indent}    currentVerifiedIconContent = .image(image: aorusBadgeImage, tintColor: nil)\n"
                f"{indent}}}\n"
                f"{indent}if peer.isVerified {{"
            )
            if inject_marker in t:
                continue
            if anchor in t:
                t = t.replace(anchor, inject, 1)
        chat_list_item.write_text(t, encoding="utf-8")
        print("Badges: patched ChatListItem (DEV/meme image in verified slot, display only)")
    else:
        print("Badges: ChatListItem.swift not found — skipped")

    # --- 2b. Chat header (ChatTitleComponent): DEV/meme badge, display only ---
    title_comp = tg / "submodules/TelegramUI/Components/ChatTitleView/Sources/ChatTitleComponent.swift"
    if title_comp.is_file():
        t = title_comp.read_text(encoding="utf-8")
