                + "                    if let aorusBadgeImage {\n"
                + "                        let aorusBadgeView: UIImageView\n"
                + "                        if let current = strongSelf.aorusBadgeView {\n"
                + "                            aorusBadgeView = current\n"
                + "                        } else {\n"
                + "                            aorusBadgeView = UIImageView()\n"
                + "                            aorusBadgeView.contentMode = .scaleAspectFit\n"
