        "\n"
        "    // MARK: Keychain mirror (generic password items; survive uninstall/reinstall).\n"
        "    //\n"
        "    // Fake-premium personalizations live only on this device (the server rejects\n"
        "    // them), so UserDefaults alone loses them on reinstall. Every persisted value\n"
        "    // is mirrored into the Keychain and read back from there when the defaults\n"
        "    // entry is missing — the same durable pattern as the account backup.\n"
        "    private static let keychainService = \"AorusGramPremium\"\n"
        "\n"
        "    private static func keychainSet(_ data: Data, account: String) {\n"
        "        let base: [String: Any] = [\n"
        "            kSecClass as String: kSecClassGenericPassword,\n"
        "            kSecAttrService as String: keychainService,\n"
        "            kSecAttrAccount as String: account\n"
        "        ]\n"
        "        SecItemDelete(base as CFDictionary)\n"
        "        var add = base\n"
        "        add[kSecValueData as String] = data\n"
        "        add[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly\n"
        "        SecItemAdd(add as CFDictionary, nil)\n"
        "    }\n"
        "\n"
        "    private static func keychainGet(account: String) -> Data? {\n"
        "        let query: [String: Any] = [\n"
        "            kSecClass as String: kSecClassGenericPassword,\n"
        "            kSecAttrService as String: keychainService,\n"
        "            kSecAttrAccount as String: account,\n"
        "            kSecReturnData as String: true,\n"
        "            kSecMatchLimit as String: kSecMatchLimitOne\n"
        "        ]\n"
        "        var result: AnyObject?\n"
        "        let status = SecItemCopyMatching(query as CFDictionary, &result)\n"
        "        guard status == errSecSuccess, let data = result as? Data else {\n"
        "            return nil\n"
        "        }\n"
        "        return data\n"
        "    }\n"
        "\n"
        "    private static func keychainDelete(account: String) {\n"
        "        let base: [String: Any] = [\n"
        "            kSecClass as String: kSecClassGenericPassword,\n"
        "            kSecAttrService as String: keychainService,\n"
        "            kSecAttrAccount as String: account\n"
        "        ]\n"
        "        SecItemDelete(base as CFDictionary)\n"
        "    }\n"
        "\n"
        "    public static func persistEmojiStatus(_ status: PeerEmojiStatus?, rawId: Int64) {\n"
        "        let key = emojiStatusKey(rawId)\n"
        "        if let status, let data = try? JSONEncoder().encode(status) {\n"
        "            UserDefaults.standard.set(data, forKey: key)\n"
        "            keychainSet(data, account: key)\n"
        "        } else {\n"
        "            UserDefaults.standard.removeObject(forKey: key)\n"
        "            keychainDelete(account: key)\n"
        "        }\n"
        "    }\n"
        "\n"
        "    public static func persistedEmojiStatus(_ rawId: Int64) -> PeerEmojiStatus? {\n"
        "        guard isEnabled else { return nil }\n"
        "        let key = emojiStatusKey(rawId)\n"
        "        var data = UserDefaults.standard.data(forKey: key)\n"
        "        if data == nil, let recovered = keychainGet(account: key) {\n"
        "            // Fresh install with a surviving keychain copy — restore the fast cache.\n"
        "            UserDefaults.standard.set(recovered, forKey: key)\n"
        "            data = recovered\n"
        "        }\n"
