def patch_voice_twin_recorder(tg: Path) -> None:
    """Apply the Voice Twin transform to OUTGOING voice messages.

    Captured microphone PCM (Int16, mono, 48 kHz) passes through
    ManagedAudioRecorder.processAndDisposeAudioBuffer just before Opus encoding.
    We call AorusVoiceTwin (AorusGram core module, which the main TelegramUI
    module already links against) to mutate the samples in place when the
    feature is enabled — no re-encoding, identical sample count, so the
    recorder's packet accounting is untouched.
    """
    path = tg / "submodules/TelegramUI/Sources/ManagedAudioRecorder.swift"
    if not path.is_file():
        print("VoiceTwin: ManagedAudioRecorder.swift not found, skip")
        return
    t = path.read_text(encoding="utf-8")
    sentinel = "// AorusGram: voice twin"
    if sentinel in t:
        print("VoiceTwin: already injected")
        return
    anchor = "func processAndDisposeAudioBuffer(_ buffer: AudioBuffer) {"
    if anchor not in t:
        print("VoiceTwin: processAndDisposeAudioBuffer anchor not found — skipped")
        return

    # 1) ensure `import AorusGram` (core module is a TelegramUI dep)
    if "import AorusGram" not in t:
        needle = "import Foundation"
        pos = t.find(needle)
        if pos != -1:
            le = t.find("\n", pos)
            if le != -1:
                t = t[:le + 1] + "import AorusGram\n" + t[le + 1:]
                print("VoiceTwin: added import AorusGram")
        else:
            t = "import AorusGram\n" + t
            print("VoiceTwin: prepended import AorusGram (no import Foundation anchor)")

    # 2) inject the in-place transform at the very top of the buffer handler
    inject = anchor + "\n" + (
        "        " + sentinel + "\n"
        "        AorusVoiceTwin.shared.processBuffer(buffer)"
    )
    t = t.replace(anchor, inject, 1)
    path.write_text(t, encoding="utf-8")
    print("VoiceTwin: injected processBuffer call into recorder")


def patch_voice_twin_video_notes(tg: Path) -> None:
    """Apply Voice Twin to video notes (round videos) / camera audio.

    CameraOutput.processVideoRecording computes `let type = CMFormatDescriptionGetMediaType(...)`
    once, then branches: a round-video path (appends `processedSampleBuffer`) and an
    else path that appends the raw `sampleBuffer` (this is where audio is written).
    The literal `videoRecorder.appendSampleBuffer(sampleBuffer)` occurs more than once
    (a video fallback inside the round-video branch AND the audio append), so anchoring
    on it and replacing the first match hooked the VIDEO fallback — a no-op for audio,
    which is why round-video voice was never transformed.

    Instead we transform the audio in place ONCE right after `type` is computed, before
    any branch. AorusVoiceTwin.processSampleBuffer mutates the CMSampleBuffer's PCM data
    in place, so whichever append fires later writes the already-transformed audio. It
    reads the buffer format and transforms mono Int16/Float32 PCM only — anything else
    is a safe no-op, so it can never corrupt the recording or crash the camera pipeline.

    Requires the Camera module to link the AorusGram core module. AorusGram depends
    only on Display, so Camera -> AorusGram introduces no dependency cycle.
    """
    out = tg / "submodules/Camera/Sources/CameraOutput.swift"
    if not out.is_file():
        print("VoiceTwinVideo: CameraOutput.swift not found, skip")
        return
    t = out.read_text(encoding="utf-8")
    sentinel = "// AorusGram: voice twin video"
    if sentinel in t:
        print("VoiceTwinVideo: already injected")
        return
    anchor = "let type = CMFormatDescriptionGetMediaType(formatDescriptor)"
    if anchor not in t:
        print("VoiceTwinVideo: media-type anchor not found — skipped")
        return

    # 1) ensure `import AorusGram`
    if "import AorusGram" not in t:
        pos = t.find("import Foundation")
        if pos != -1:
            le = t.find("\n", pos)
            t = t[:le + 1] + "import AorusGram\n" + t[le + 1:]
            print("VoiceTwinVideo: added import AorusGram to CameraOutput")
        else:
            t = "import AorusGram\n" + t

    # 2) transform audio buffers in place once, right after the media type is known,
    #    so every downstream append (audio or round-video fallback) sees mutated PCM.
    idx = t.find(anchor)
    line_start = t.rfind("\n", 0, idx) + 1
    indent = t[line_start:idx]
    inject = (
        anchor + "\n"
        + indent + "if type == kCMMediaType_Audio { AorusVoiceTwin.shared.processSampleBuffer(sampleBuffer) }  "
        + sentinel
    )
    t = t.replace(anchor, inject, 1)
    out.write_text(t, encoding="utf-8")
    print("VoiceTwinVideo: hooked CameraOutput audio (transform-before-branch)")

    # 3) Camera BUILD must link AorusGram core
    build = tg / "submodules/Camera/BUILD"
    if build.is_file():
        bt = build.read_text(encoding="utf-8")
        if "//submodules/AorusGram:AorusGram" in bt:
            print("VoiceTwinVideo: Camera BUILD dep already present")
        else:
            idx = bt.find("deps = [")
            if idx != -1:
                insert_at = bt.find("\n", idx) + 1
                bt = bt[:insert_at] + '        "//submodules/AorusGram:AorusGram",\n' + bt[insert_at:]
                build.write_text(bt, encoding="utf-8")
                print("VoiceTwinVideo: added AorusGram dep to Camera BUILD")
            else:
                print("VoiceTwinVideo: WARNING — Camera BUILD deps anchor not found")
    else:
        print("VoiceTwinVideo: Camera BUILD not found")


def patch_glass_global_toggle(tg: Path) -> None:
    """Make the "Эффекты стекла" switch disable ALL glass in the client — including
    Telegram's own native iOS 26 liquid glass (nav back-button / title capsules, etc.),
    not just the AorusGram-added surfaces.

    Every glass surface in the app funnels through GlassBackgroundView.update(...),
    which only builds/keeps the UIGlassEffect while `isVisible` is true (the shadow,
    foreground and glass layers are all gated on it). So the single, comprehensive
    gate is to force `isVisible = false` at the top of the internal update method when
    the toggle is off: one place turns off glass everywhere, engine-wide. When the key
    is on (default) behaviour is byte-for-byte unchanged. Read live per-update so it
    applies as soon as views re-lay-out (the settings toggle also shows a restart
    notice for the surfaces that only build their layers once).
    """
    path = tg / "submodules/TelegramUI/Components/GlassBackgroundComponent/Sources/GlassBackgroundComponent.swift"
    if not path.is_file():
        print("GlassToggle: GlassBackgroundComponent.swift not found — skip")
        return
    t = path.read_text(encoding="utf-8")
    # NOTE: do NOT early-return when the engine gate is already present — the context
    # menu patch below is independent and must still run (on cache-hit builds the engine
    # gate can already be applied while the context-menu gate is not).
    if "AorusGram: global glass gate" in t:
        print("GlassToggle: engine gate already present")
    else:
        anchor = "    func update(size: CGSize, shape: Shape, isDark: Bool, tintColor: TintColor, isInteractive: Bool = false, isVisible: Bool = true, transition: ComponentTransition) {\n"
        inject = (
            anchor
            + "        // AorusGram: global glass gate — one switch disables every glass surface\n"
            + "        // (Telegram's native capsules included) by forcing the whole effect off.\n"
            + "        let isVisible = isVisible && ((UserDefaults.standard.object(forKey: \"aorusgram_feature_glass_ui\") as? Bool) ?? true)\n"
        )
        if anchor in t:
            t = t.replace(anchor, inject, 1)
            path.write_text(t, encoding="utf-8")
            print("GlassToggle: global glass gate injected into GlassBackgroundView.update")
        else:
            print("GlassToggle: WARNING GlassBackgroundView.update anchor not found — glass NOT globally gated")

    # Context menus apply UIGlassEffect DIRECTLY (LensTransitionContainerEffectViewImpl),
    # bypassing GlassBackgroundView, so the global gate above does not reach them. Gate
    # this one too: when glass is off, fall back to a plain systemMaterial blur so the
    # menu stays readable but drops the iOS 26 liquid-glass look.
    ctx = tg / "submodules/TelegramUI/Components/ContextControllerImpl/Sources/ContextControllerActionsStackNode.swift"
    if ctx.is_file():
        ct = ctx.read_text(encoding="utf-8")
        ctx_anchor = "            self.glassView.effect = glassEffectValue\n"
        ctx_repl = (
            "            // AorusGram: honor the global glass toggle in context menus\n"
            "            if ((UserDefaults.standard.object(forKey: \"aorusgram_feature_glass_ui\") as? Bool) ?? true) {\n"
            "                self.glassView.effect = glassEffectValue\n"
            "            } else {\n"
            "                self.glassView.effect = nil\n"
            "                self.glassView.backgroundColor = .clear\n"
            "                self.glassView.contentView.backgroundColor = .clear\n"
            "            }\n"
        )
        if "AorusGram: honor the global glass toggle in context menus" in ct:
            print("GlassToggle: context menu already patched")
        elif ctx_anchor in ct:
            ct = ct.replace(ctx_anchor, ctx_repl, 1)
            ctx.write_text(ct, encoding="utf-8")
            print("GlassToggle: gated context-menu UIGlassEffect")
        else:
            print("GlassToggle: WARNING context-menu glass anchor not found")
    else:
        print("GlassToggle: ContextControllerActionsStackNode.swift not found — skip context menu")


def patch_mask_picker_call(tg: Path) -> None:
    """A fifth call button that slides in a strip of masks to choose from.

    The masks themselves were already rendered into outgoing frames by
    patch_video_masks(); what was missing was any way to change which one without
    leaving the call for Settings. This adds a button next to Video and, above the
    button row, a horizontally scrollable strip of circles — built-in presets first,
    then the user's own masks, each with its artwork and name.

    The strip lives in the leaf module AorusMaskPicker (UIKit only, no deps) because
    CallScreen sits far below AorusGramUI and must not reach up into the settings UI.

    Geometry note: the stock row is 56pt buttons with 36pt gaps, which is 332pt for
    four and 424pt for five — wider than a 393pt screen. Rather than clipping, the
    gaps shrink first and then the buttons, so five fit on every supported device.
    """
    # ---------------------------------------------------------------- ButtonGroupView
    group = tg / "submodules/TelegramUI/Components/Calls/CallScreen/Sources/Components/ButtonGroupView.swift"
    if not group.is_file():
        raise RuntimeError("MaskPicker: ButtonGroupView.swift not found")
    t = group.read_text(encoding="utf-8")
    sentinel = "// AorusGram: mask button"

    if sentinel not in t:
        if "import AorusMaskPicker" not in t:
            t = t.replace("import TelegramPresentationData\n",
                          "import TelegramPresentationData\nimport AorusMaskPicker\n", 1)

        key_anchor = (
            "                case microphone\n"
            "                case end\n"
            "            }\n"
        )
        if key_anchor not in t:
            raise RuntimeError("MaskPicker: Button.Content.Key anchor not found")
        t = t.replace(key_anchor,
                      "                case microphone\n"
                      "                case end\n"
                      "                case mask " + sentinel + "\n"
                      "            }\n", 1)

        content_anchor = (
            "            case microphone(isMuted: Bool)\n"
            "            case end\n"
        )
        if content_anchor not in t:
            raise RuntimeError("MaskPicker: Button.Content case anchor not found")
        t = t.replace(content_anchor,
                      content_anchor + "            case mask(isActive: Bool) " + sentinel + "\n", 1)

        key_switch_anchor = (
                "                case .end:\n"
                "                    return .end\n"
                "                }\n"
        )
        if key_switch_anchor not in t:
            raise RuntimeError("MaskPicker: Content.key switch anchor not found")
        t = t.replace(key_switch_anchor,
                      "                case .end:\n"
                      "                    return .end\n"
                      "                case .mask:\n"
                      "                    return .mask\n"
                      "                }\n", 1)

        # Adaptive sizing. `insets` are the screen's safe-area insets; 16pt a side keeps
        # the row clear of the rounded display corners.
        size_anchor = (
            "        let buttonSize: CGFloat = 56.0\n"
            "        let buttonSpacing: CGFloat = 36.0\n"
        )
        if size_anchor not in t:
            raise RuntimeError("MaskPicker: button metrics anchor not found")
        t = t.replace(size_anchor,
            "        " + sentinel + ": five buttons do not fit at the stock 56/36 (5*56 + 4*36 = 424pt\n"
            "        // against a 393pt screen), so the gaps give way first and only then the buttons.\n"
            "        var buttonSize: CGFloat = 56.0\n"
            "        var buttonSpacing: CGFloat = 36.0\n"
            "        if buttons.count > 4 {\n"
            "            let count = CGFloat(buttons.count)\n"
            "            let available = size.width - insets.left - insets.right - 32.0\n"
            "            if buttonSize * count + buttonSpacing * (count - 1.0) > available {\n"
            "                let minSpacing: CGFloat = 12.0\n"
            "                buttonSpacing = max(minSpacing, min(buttonSpacing, (available - buttonSize * count) / (count - 1.0)))\n"
            "                if buttonSize * count + buttonSpacing * (count - 1.0) > available {\n"
            "                    buttonSize = max(44.0, floor((available - buttonSpacing * (count - 1.0)) / count))\n"
            "                }\n"
            "            }\n"
            "        }\n", 1)

        icon_anchor = (
            "            case .end:\n"
            "                title = strings.Call_End\n"
            "                image = UIImage(bundleImageName: \"Call/End\")\n"
            "                isActive = false\n"
            "                isDestructive = true\n"
            "            }\n"
        )
        if icon_anchor not in t:
            raise RuntimeError("MaskPicker: button icon switch anchor not found")
        t = t.replace(icon_anchor,
            icon_anchor[:-len("            }\n")] +
            "            case let .mask(isActiveValue):\n"
            "                " + sentinel + ": a system symbol, so its weight tracks the OS\n"
            "                // instead of a bitmap that drifts away from the buttons beside it.\n"
            "                title = AorusMaskCatalogue.buttonTitle\n"
            "                image = AorusMaskPickerView.buttonIcon()\n"
            "                isActive = isActiveValue\n"
            "            }\n", 1)

        # The host needs to know where the row starts to sit the strip above it.
        row_top_anchor = "    private var buttons: [Button]?\n"
        if row_top_anchor not in t:
            raise RuntimeError("MaskPicker: buttons storage anchor not found")
        t = t.replace(row_top_anchor,
                      row_top_anchor +
                      "    " + sentinel + ": top of the laid-out row, read by PrivateCallScreen\n"
                      "    // so the mask strip can be positioned directly above it.\n"
                      "    private(set) var aorusButtonRowTop: CGFloat = 0.0\n", 1)

        y_anchor = "        var buttonX: CGFloat = floor((size.width - buttonSize * CGFloat(buttons.count) - buttonSpacing * CGFloat(buttons.count - 1)) * 0.5)\n"
        if y_anchor not in t:
            raise RuntimeError("MaskPicker: buttonX anchor not found")
        t = t.replace(y_anchor, "        self.aorusButtonRowTop = buttonY\n" + y_anchor, 1)

        group.write_text(t, encoding="utf-8")
        print("MaskPicker: patched ButtonGroupView (mask button + adaptive row)")
    else:
        print("MaskPicker: ButtonGroupView already patched")

    # ------------------------------------------------------------- PrivateCallScreen
    screen = tg / "submodules/TelegramUI/Components/Calls/CallScreen/Sources/PrivateCallScreen.swift"
    if not screen.is_file():
        raise RuntimeError("MaskPicker: PrivateCallScreen.swift not found")
    t = screen.read_text(encoding="utf-8")

    if sentinel not in t:
        if "import AorusMaskPicker" not in t:
            t = t.replace("import ComponentFlow\n", "import ComponentFlow\nimport AorusMaskPicker\n", 1)

        prop_anchor = "    private let buttonGroupView: ButtonGroupView\n"
        if prop_anchor not in t:
            raise RuntimeError("MaskPicker: buttonGroupView property anchor not found")
        t = t.replace(prop_anchor,
                      prop_anchor +
                      "    " + sentinel + ": created on first use, so a call without masks pays nothing.\n"
                      "    private var aorusMaskPickerView: AorusMaskPickerView?\n"
                      "    private var aorusMaskPickerVisible: Bool = false\n", 1)

        button_anchor = (
            "            ButtonGroupView.Button(content: .microphone(isMuted: params.state.isLocalAudioMuted), isEnabled: !isTerminated, action: { [weak self] in\n"
        )
        if button_anchor not in t:
            raise RuntimeError("MaskPicker: call button array anchor not found")
        t = t.replace(button_anchor,
            "            " + sentinel + ": sits right after Video, as the mask only affects outgoing video.\n"
            "            ButtonGroupView.Button(content: .mask(isActive: self.aorusMaskPickerVisible), isEnabled: !isTerminated, action: { [weak self] in\n"
            "                guard let self else {\n"
            "                    return\n"
            "                }\n"
            "                self.aorusToggleMaskPicker()\n"
            "            }),\n" + button_anchor, 1)

        # Drop the button again when it would do nothing — cheaper than branching the literal.
        # The mask is only ever composited into an OUTGOING video frame, so on an audio call
        # the control would be dead weight in a row that is already one button wider than
        # upstream designed for. Same condition the flip-camera button uses below.
        filter_anchor = "        if self.activeLocalVideoSource != nil {\n"
        if filter_anchor not in t:
            raise RuntimeError("MaskPicker: activeLocalVideoSource anchor not found")
        t = t.replace(filter_anchor,
            "        if !AorusMaskCatalogue.isEnabled || self.activeLocalVideoSource == nil {\n"
            "            buttons.removeAll(where: { if case .mask = $0.content { return true } else { return false } })\n"
            "            // Collapse it directly rather than through aorusSetMaskPicker(): we are inside\n"
            "            // the layout pass, and that helper asks for another one.\n"
            "            self.aorusMaskPickerVisible = false\n"
            "            self.aorusMaskPickerView?.setVisible(false, animated: false)\n"
            "        }\n" + filter_anchor, 1)

        layout_anchor = "        let contentBottomInset = self.buttonGroupView.update(size: params.size, insets: params.insets, minWidth: wideContentWidth, controlsHidden: currentAreControlsHidden, displayClose: displayClose, strings: params.state.strings, buttons: buttons, notices: notices, isAnimatedOutToGroupCall: self.isAnimatedOutToGroupCall, transition: transition)\n"
        if layout_anchor not in t:
            raise RuntimeError("MaskPicker: buttonGroupView.update anchor not found")
        t = t.replace(layout_anchor,
            layout_anchor +
            "        " + sentinel + ": hang the strip off the measured top of the button row rather\n"
            "        // than recomputing the row geometry here, which would drift the moment upstream\n"
            "        // changes a constant.\n"
            "        if let aorusMaskPicker = self.aorusMaskPickerView {\n"
            "            let aorusPickerHeight = AorusMaskPickerView.panelHeight\n"
            "            let aorusPickerWidth = max(0.0, params.size.width - params.insets.left - params.insets.right - 24.0)\n"
            "            aorusMaskPicker.frame = CGRect(\n"
            "                x: params.insets.left + 12.0,\n"
            "                y: self.buttonGroupView.aorusButtonRowTop - aorusPickerHeight - 16.0,\n"
            "                width: aorusPickerWidth,\n"
            "                height: aorusPickerHeight)\n"
            "            if currentAreControlsHidden && self.aorusMaskPickerVisible {\n"
            "                self.aorusMaskPickerVisible = false\n"
            "                aorusMaskPicker.setVisible(false, animated: true)\n"
            "            }\n"
            "        }\n", 1)

        methods_anchor = "    private func update(transition: ComponentTransition) {\n"
        if methods_anchor not in t:
            raise RuntimeError("MaskPicker: update(params:) anchor not found")
        t = t.replace(methods_anchor,
            "    " + sentinel + ": show/hide plumbing for the strip.\n"
            "    private func aorusToggleMaskPicker() {\n"
            "        self.aorusSetMaskPicker(visible: !self.aorusMaskPickerVisible, animated: true)\n"
            "    }\n"
            "    \n"
            "    private func aorusSetMaskPicker(visible: Bool, animated: Bool) {\n"
            "        if visible && self.aorusMaskPickerView == nil {\n"
            "            let pickerView = AorusMaskPickerView(accentColor: UIColor(red: 0.39, green: 0.82, blue: 1.0, alpha: 1.0))\n"
            "            pickerView.onSelect = { [weak self] _ in\n"
            "                guard let self else {\n"
            "                    return\n"
            "                }\n"
            "                self.update(transition: ComponentTransition.easeInOut(duration: 0.2))\n"
            "            }\n"
            "            self.aorusMaskPickerView = pickerView\n"
            "            self.insertSubview(pickerView, belowSubview: self.buttonGroupView)\n"
            "        }\n"
            "        self.aorusMaskPickerVisible = visible\n"
            "        self.aorusMaskPickerView?.setVisible(visible, animated: animated)\n"
            "        self.update(transition: animated ? ComponentTransition.easeInOut(duration: 0.3) : ComponentTransition.immediate)\n"
            "    }\n"
            "    \n" + methods_anchor, 1)

        screen.write_text(t, encoding="utf-8")
        print("MaskPicker: patched PrivateCallScreen (button + strip)")
    else:
        print("MaskPicker: PrivateCallScreen already patched")

    # ------------------------------------------------------------------------- BUILD
    build = tg / "submodules/TelegramUI/Components/Calls/CallScreen/BUILD"
    if not build.is_file():
        raise RuntimeError("MaskPicker: CallScreen BUILD not found")
    bt = build.read_text(encoding="utf-8")
    if "//submodules/AorusMaskPicker:AorusMaskPicker" in bt:
        print("MaskPicker: CallScreen BUILD dep already present")
        return
    needle = '        "//submodules/Display",\n'
    if needle not in bt:
        raise RuntimeError("MaskPicker: CallScreen BUILD deps anchor not found")
    bt = bt.replace(needle, needle + '        "//submodules/AorusMaskPicker:AorusMaskPicker",\n', 1)
    build.write_text(bt, encoding="utf-8")
    print("MaskPicker: added AorusMaskPicker dep to CallScreen BUILD")


def patch_mask_picker_round_video(tg: Path) -> None:
    """The same mask strip in the round-video recorder.

    The camera panel is a CombinedComponent, not a view hierarchy, so the strip cannot
    simply be inserted as a subview the way the call screen does it. Two small components
    are injected into the file instead — a button and a host for the picker — both backed
    by plain UIViews this repo owns, so nothing has to be assumed about CameraButton's or
    Image's internals. The glass background is reused verbatim from the flash button, so
    the new control is visually identical to the two beside it.

    Visibility lives in the screen's own State: a CombinedComponent body is rebuilt from
    state, and holding it anywhere else would lose it on the next recompose.
    """
    path = tg / "submodules/TelegramUI/Components/VideoMessageCameraScreen/Sources/VideoMessageCameraScreen.swift"
    if not path.is_file():
        raise RuntimeError("MaskPickerRV: VideoMessageCameraScreen.swift not found")
    t = path.read_text(encoding="utf-8")
    sentinel = "// AorusGram: round-video mask strip"
    if sentinel in t:
        print("MaskPickerRV: already patched")
        return

    # ---------------------------------------------------------------- components
    import_anchor = "import CameraButtonComponent\n"
    if import_anchor not in t:
        raise RuntimeError("MaskPickerRV: import anchor not found")
    components = (
        import_anchor
        + "import AorusMaskPicker\n"
        + "\n"
        + sentinel + ": the control that opens the strip.\n"
        + "//\n"
        + "// A component of our own rather than Telegram's CameraButton so the icon, the hit area\n"
        + "// and the pressed state are all things this repo owns — the button sits between two\n"
        + "// stock ones and only has to match them visually, which the shared glass background\n"
        + "// behind it already guarantees.\n"
        + "final class AorusMaskButtonComponent: Component {\n"
        + "    typealias EnvironmentType = Empty\n"
        + "    \n"
        + "    let isActive: Bool\n"
        + "    let action: () -> Void\n"
        + "    \n"
        + "    init(isActive: Bool, action: @escaping () -> Void) {\n"
        + "        self.isActive = isActive\n"
        + "        self.action = action\n"
        + "    }\n"
        + "    \n"
        + "    static func ==(lhs: AorusMaskButtonComponent, rhs: AorusMaskButtonComponent) -> Bool {\n"
        + "        return lhs.isActive == rhs.isActive\n"
        + "    }\n"
        + "    \n"
        + "    final class View: UIView {\n"
        + "        private let iconView = UIImageView()\n"
        + "        private var component: AorusMaskButtonComponent?\n"
        + "        \n"
        + "        override init(frame: CGRect) {\n"
        + "            super.init(frame: frame)\n"
        + "            self.iconView.contentMode = .center\n"
        + "            self.addSubview(self.iconView)\n"
        + "            self.addGestureRecognizer(UITapGestureRecognizer(target: self, action: #selector(self.handleTap)))\n"
        + "        }\n"
        + "        \n"
        + "        required init?(coder: NSCoder) {\n"
        + "            preconditionFailure()\n"
        + "        }\n"
        + "        \n"
        + "        @objc private func handleTap() {\n"
        + "            self.component?.action()\n"
        + "        }\n"
        + "        \n"
        + "        func update(component: AorusMaskButtonComponent, availableSize: CGSize, transition: ComponentTransition) -> CGSize {\n"
        + "            self.component = component\n"
        + "            let size = CGSize(width: 40.0, height: 40.0)\n"
        + "            let tint = component.isActive ? UIColor(red: 0.58, green: 0.35, blue: 0.96, alpha: 1.0) : UIColor.white\n"
        + "            self.iconView.image = AorusMaskPickerView.buttonIcon(pointSize: 20.0, color: tint)\n"
        + "            self.iconView.frame = CGRect(origin: CGPoint(), size: size)\n"
        + "            return size\n"
        + "        }\n"
        + "    }\n"
        + "    \n"
        + "    func makeView() -> View {\n"
        + "        return View(frame: CGRect())\n"
        + "    }\n"
        + "    \n"
        + "    func update(view: View, availableSize: CGSize, state: EmptyComponentState, environment: Environment<EnvironmentType>, transition: ComponentTransition) -> CGSize {\n"
        + "        return view.update(component: self, availableSize: availableSize, transition: transition)\n"
        + "    }\n"
        + "}\n"
        + "\n"
        + sentinel + ": a host so the shared UIKit strip can live inside a component tree.\n"
        + "final class AorusMaskPickerComponent: Component {\n"
        + "    typealias EnvironmentType = Empty\n"
        + "    \n"
        + "    let isVisible: Bool\n"
        + "    let onSelect: (String) -> Void\n"
        + "    \n"
        + "    init(isVisible: Bool, onSelect: @escaping (String) -> Void) {\n"
        + "        self.isVisible = isVisible\n"
        + "        self.onSelect = onSelect\n"
        + "    }\n"
        + "    \n"
        + "    static func ==(lhs: AorusMaskPickerComponent, rhs: AorusMaskPickerComponent) -> Bool {\n"
        + "        return lhs.isVisible == rhs.isVisible\n"
        + "    }\n"
        + "    \n"
        + "    final class View: UIView {\n"
        + "        private let picker = AorusMaskPickerView(accentColor: UIColor(red: 0.58, green: 0.35, blue: 0.96, alpha: 1.0))\n"
        + "        private var component: AorusMaskPickerComponent?\n"
        + "        \n"
        + "        override init(frame: CGRect) {\n"
        + "            super.init(frame: frame)\n"
        + "            self.addSubview(self.picker)\n"
        + "        }\n"
        + "        \n"
        + "        required init?(coder: NSCoder) {\n"
        + "            preconditionFailure()\n"
        + "        }\n"
        + "        \n"
        + "        func update(component: AorusMaskPickerComponent, availableSize: CGSize, transition: ComponentTransition) -> CGSize {\n"
        + "            // The very first update must not animate: the strip would otherwise slide in\n"
        + "            // once on its own the moment the panel is first laid out.\n"
        + "            let isFirst = self.component == nil\n"
        + "            self.component = component\n"
        + "            self.picker.onSelect = component.onSelect\n"
        + "            let size = CGSize(width: availableSize.width, height: AorusMaskPickerView.panelHeight)\n"
        + "            self.picker.frame = CGRect(origin: CGPoint(), size: size)\n"
        + "            self.picker.setVisible(component.isVisible, animated: !isFirst)\n"
        + "            return size\n"
        + "        }\n"
        + "    }\n"
        + "    \n"
        + "    func makeView() -> View {\n"
        + "        return View(frame: CGRect())\n"
        + "    }\n"
        + "    \n"
        + "    func update(view: View, availableSize: CGSize, state: EmptyComponentState, environment: Environment<EnvironmentType>, transition: ComponentTransition) -> CGSize {\n"
        + "        return view.update(component: self, availableSize: availableSize, transition: transition)\n"
        + "    }\n"
        + "}\n"
    )
    t = t.replace(import_anchor, components, 1)

    # ---------------------------------------------------------------------- state
    state_anchor = "    final class State: ComponentState {\n"
    if state_anchor not in t:
        raise RuntimeError("MaskPickerRV: State class anchor not found")
    t = t.replace(state_anchor,
        state_anchor
        + "        " + sentinel + ": a CombinedComponent body is rebuilt from state, so the\n"
        + "        // strip's visibility has to live here or it is lost on the next recompose.\n"
        + "        var aorusMaskPickerVisible = false\n"
        + "        \n"
        + "        func aorusToggleMaskPicker() {\n"
        + "            self.aorusMaskPickerVisible = !self.aorusMaskPickerVisible\n"
        + "            self.updated(transition: .immediate)\n"
        + "        }\n"
        + "        \n", 1)

    # --------------------------------------------------------------------- children
    child_anchor = (
        "        let flashButtonBackground = Child(GlassBackgroundComponent.self)\n"
        "        let flashButton = Child(CameraButton.self)\n"
    )
    if child_anchor not in t:
        raise RuntimeError("MaskPickerRV: Child declaration anchor not found")
    t = t.replace(child_anchor,
        child_anchor
        + "        " + sentinel + "\n"
        + "        let aorusMaskButtonBackground = Child(GlassBackgroundComponent.self)\n"
        + "        let aorusMaskButton = Child(AorusMaskButtonComponent.self)\n"
        + "        let aorusMaskPicker = Child(AorusMaskPickerComponent.self)\n", 1)

    # --------------------------------------------------------------------- placement
    place_anchor = (
        "                    context.add(flashButton\n"
        "                        .position(CGPoint(x: flipButton.size.width + sideInset + flashButton.size.width / 2.0 + 11.0, y: availableSize.height - flashButton.size.height / 2.0 - 8.0))\n"
        "                        .appear(.default(scale: true, alpha: true))\n"
        "                        .disappear(.default(scale: true, alpha: true))\n"
        "                    )\n"
    )
    if place_anchor not in t:
        raise RuntimeError("MaskPickerRV: flash button placement anchor not found")
    t = t.replace(place_anchor,
        place_anchor
        + "                    \n"
        + "                    " + sentinel + ": third in the row, after the flash button.\n"
        + "                    if AorusMaskCatalogue.isEnabled {\n"
        + "                        let aorusMaskButtonValue = aorusMaskButton.update(\n"
        + "                            component: AorusMaskButtonComponent(\n"
        + "                                isActive: state.aorusMaskPickerVisible,\n"
        + "                                action: { [weak state] in\n"
        + "                                    state?.aorusToggleMaskPicker()\n"
        + "                                }\n"
        + "                            ),\n"
        + "                            availableSize: CGSize(width: 40.0, height: 40.0),\n"
        + "                            transition: context.transition\n"
        + "                        )\n"
        + "                        let aorusMaskBackgroundValue = aorusMaskButtonBackground.update(\n"
        + "                            component: GlassBackgroundComponent(\n"
        + "                                size: CGSize(width: 40.0, height: 40.0),\n"
        + "                                cornerRadius: 40.0 * 0.5,\n"
        + "                                isDark: environment.theme.overallDarkAppearance,\n"
        + "                                tintColor: .init(kind: .panel)\n"
        + "                            ),\n"
        + "                            availableSize: CGSize(width: 40.0, height: 40.0),\n"
        + "                            transition: .immediate\n"
        + "                        )\n"
        + "                        // Left edge of the flash button plus its width and the same 11pt gap\n"
        + "                        // the flash button leaves after the flip button.\n"
        + "                        let aorusMaskCentreX = flipButton.size.width + sideInset + flashButton.size.width + 11.0 + 11.0 + aorusMaskButtonValue.size.width / 2.0\n"
        + "                        let aorusMaskCentreY = availableSize.height - aorusMaskButtonValue.size.height / 2.0 - 8.0\n"
        + "                        context.add(aorusMaskBackgroundValue\n"
        + "                            .position(CGPoint(x: aorusMaskCentreX, y: aorusMaskCentreY))\n"
        + "                            .appear(.default(scale: true, alpha: true))\n"
        + "                            .disappear(.default(scale: true, alpha: true))\n"
        + "                        )\n"
        + "                        context.add(aorusMaskButtonValue\n"
        + "                            .position(CGPoint(x: aorusMaskCentreX, y: aorusMaskCentreY))\n"
        + "                            .appear(.default(scale: true, alpha: true))\n"
        + "                            .disappear(.default(scale: true, alpha: true))\n"
        + "                        )\n"
        + "                        \n"
        + "                        // The strip is added whatever its state: it owns its own show/hide\n"
        + "                        // animation, and removing it from the tree would cut that short.\n"
        + "                        let aorusPickerValue = aorusMaskPicker.update(\n"
        + "                            component: AorusMaskPickerComponent(\n"
        + "                                isVisible: state.aorusMaskPickerVisible,\n"
        + "                                onSelect: { [weak state] _ in\n"
        + "                                    state?.updated(transition: .immediate)\n"
        + "                                }\n"
        + "                            ),\n"
        + "                            availableSize: CGSize(width: max(0.0, availableSize.width - 24.0), height: AorusMaskPickerView.panelHeight),\n"
        + "                            transition: context.transition\n"
        + "                        )\n"
        + "                        context.add(aorusPickerValue\n"
        + "                            .position(CGPoint(x: availableSize.width / 2.0, y: aorusMaskCentreY - 20.0 - 12.0 - aorusPickerValue.size.height / 2.0))\n"
        + "                        )\n"
        + "                    }\n", 1)

    path.write_text(t, encoding="utf-8")
    print("MaskPickerRV: patched VideoMessageCameraScreen (button + strip)")

    # ------------------------------------------------------------------------- BUILD
    build = tg / "submodules/TelegramUI/Components/VideoMessageCameraScreen/BUILD"
    if not build.is_file():
        raise RuntimeError("MaskPickerRV: VideoMessageCameraScreen BUILD not found")
    bt = build.read_text(encoding="utf-8")
    if "//submodules/AorusMaskPicker:AorusMaskPicker" in bt:
        print("MaskPickerRV: BUILD dep already present")
        return
    needle = '        "//submodules/Display",\n'
    if needle not in bt:
        raise RuntimeError("MaskPickerRV: BUILD deps anchor not found")
    bt = bt.replace(needle, needle + '        "//submodules/AorusMaskPicker:AorusMaskPicker",\n', 1)
    build.write_text(bt, encoding="utf-8")
    print("MaskPickerRV: added AorusMaskPicker dep to VideoMessageCameraScreen BUILD")


def patch_video_masks(tg: Path) -> None:
    """Render Aorus face masks into outgoing call and round-video frames.

    Vision runs away from the capture thread and updates a retained pose snapshot.
    Calls remain fail-open on unsupported inputs. Round-video recording alone
    skips original video frames until the asynchronous tracker has rendered a
    masked frame, so the encoded file cannot begin with an exposed face.
    """
    camera = tg / "submodules/Camera/Sources/CameraOutput.swift"
    if camera.is_file():
        text = camera.read_text(encoding="utf-8")
        text = text.replace(
            "AorusVideoMaskProcessor.shared.process(sampleBuffer: sampleBuffer, orientation: orientation)",
            "AorusVideoMaskProcessor.shared.process(sampleBuffer: sampleBuffer, orientation: orientation, mirrored: self.currentPosition == .front)"
        )
        # Migrate already-patched cached Telegram trees away from the unsafe
        # synchronous Vision request. Detection must never block capture or
        # recorder finalization.
        text = text.replace(", synchronouslyAcquireInitialPose: publishesPreview", "")
        text = text.replace(", synchronouslyAcquireInitialPose: true", "")
        sentinel = "// AorusGram: real-time video mask"
        stream_sentinel = "// AorusGram: stream-isolated round-video mask"
        recording_gate_sentinel = "// AorusGram: discard unmasked recording frames"
        needs_recording_gate_migration = sentinel in text and recording_gate_sentinel not in text
        mask_block = (
            "        var effectiveSampleBuffer = sampleBuffer\n"
            "        var shouldRecordSampleBuffer = true " + recording_gate_sentinel + "\n"
            "        if self.isVideoMessage, sampleBuffer.type == kCMMediaType_Video { " + sentinel + "\n"
            "            let orientation: Int32\n"
            "            switch self.captureOrientation {\n"
            "            case .portrait: orientation = 6\n"
            "            case .portraitUpsideDown: orientation = 8\n"
            "            case .landscapeRight: orientation = 1\n"
            "            case .landscapeLeft: orientation = 3\n"
            "            @unknown default: orientation = 6\n"
            "            }\n"
            "            " + stream_sentinel + "\n"
            "            var isFrontSource = self.currentPosition == .front\n"
            "            if #available(iOS 13.0, *) {\n"
            "                if let sourcePosition = connection.inputPorts.first?.sourceDevicePosition, sourcePosition != .unspecified {\n"
            "                    isFrontSource = sourcePosition == .front\n"
            "                }\n"
            "            }\n"
            "            let selectedPosition = self.masterOutput?.currentPosition ?? self.currentPosition\n"
            "            let publishesPreview = self.exclusive || (isFrontSource ? selectedPosition == .front : selectedPosition == .back)\n"
            "            let processor = isFrontSource ? AorusVideoMaskProcessor.roundVideoFront : AorusVideoMaskProcessor.roundVideoBack\n"
            "            if let masked = processor.process(sampleBuffer: sampleBuffer, orientation: orientation, mirrored: isFrontSource, publishesPreview: publishesPreview) {\n"
            "                effectiveSampleBuffer = masked\n"
            "            } else if processor.shouldDiscardUnmaskedVideoFrame {\n"
            "                shouldRecordSampleBuffer = false\n"
            "            }\n"
            "        }\n\n"
        )
        recorder_block = (
            "        if let masterOutput = self.masterOutput {\n"
            "            masterOutput.processVideoRecording(effectiveSampleBuffer, fromAdditionalOutput: true)\n"
            "        } else {\n"
            "            self.processVideoRecording(effectiveSampleBuffer, fromAdditionalOutput: false)\n"
            "        }\n"
        )
        gated_recorder_block = (
            "        if shouldRecordSampleBuffer {\n"
            "            if let masterOutput = self.masterOutput {\n"
            "                masterOutput.processVideoRecording(effectiveSampleBuffer, fromAdditionalOutput: true)\n"
            "            } else {\n"
            "                self.processVideoRecording(effectiveSampleBuffer, fromAdditionalOutput: false)\n"
            "            }\n"
            "        }\n"
        )
        if sentinel in text and stream_sentinel not in text:
            legacy_pattern = re.compile(
                r"        var effectiveSampleBuffer = sampleBuffer\n"
                r".*?"
                r"        }\n\n"
                r"(?=        if let masterOutput = self\.masterOutput)",
                re.DOTALL,
            )
            text, count = legacy_pattern.subn(mask_block, text, count=1)
            if count != 1:
                raise RuntimeError("VideoMasks: cached round-video mask block migration failed")
            print("VideoMasks: migrated cached pipeline to isolated camera streams")
        if needs_recording_gate_migration:
            if recording_gate_sentinel not in text:
                cached_pattern = re.compile(
                    r"        var effectiveSampleBuffer = sampleBuffer\n"
                    r".*?"
                    r"        }\n\n"
                    r"(?=        if let masterOutput = self\.masterOutput)",
                    re.DOTALL,
                )
                text, count = cached_pattern.subn(mask_block, text, count=1)
                if count != 1:
                    raise RuntimeError("VideoMasks: cached initial-frame gate migration failed")
            if recorder_block not in text:
                raise RuntimeError("VideoMasks: cached recorder block migration anchor not found")
            text = text.replace(recorder_block, gated_recorder_block, 1)
            print("VideoMasks: protected cached recording from unmasked initial frames")
        if sentinel not in text:
            if "import AorusGram\n" not in text:
                anchor = "import Foundation\n"
                if anchor not in text:
                    raise RuntimeError("VideoMasks: CameraOutput import anchor not found")
                text = text.replace(anchor, anchor + "import AorusGram\n", 1)

            anchor = (
                "        if let masterOutput = self.masterOutput {\n"
                "            masterOutput.processVideoRecording(sampleBuffer, fromAdditionalOutput: true)\n"
                "        } else {\n"
                "            self.processVideoRecording(sampleBuffer, fromAdditionalOutput: false)\n"
                "        }\n"
                "        \n"
                "        if let videoPixelBuffer = CMSampleBufferGetImageBuffer(sampleBuffer) {\n"
                "            self.processSampleBuffer?(sampleBuffer, videoPixelBuffer, connection)\n"
            )
            replacement = (
                mask_block
                + gated_recorder_block
                + "        \n"
                "        if let videoPixelBuffer = CMSampleBufferGetImageBuffer(effectiveSampleBuffer) {\n"
                "            self.processSampleBuffer?(effectiveSampleBuffer, videoPixelBuffer, connection)\n"
            )
            if anchor not in text:
                raise RuntimeError("VideoMasks: CameraOutput capture anchor not found")
            text = text.replace(anchor, replacement, 1)
            print("VideoMasks: round-video recording pipeline patched")
        else:
            print("VideoMasks: round-video pipeline already patched")
        camera.write_text(text, encoding="utf-8")
    else:
        raise RuntimeError("VideoMasks: CameraOutput.swift not found")

    camera_preview = tg / "submodules/Camera/Sources/CameraPreviewView.swift"
    if not camera_preview.is_file():
        raise RuntimeError("VideoMasks: CameraPreviewView.swift not found")
    text = camera_preview.read_text(encoding="utf-8")
    preview_sentinel = "// AorusGram: local round-video mask preview"
    if preview_sentinel not in text:
        if "import AorusGram\n" not in text:
            anchor = "import Foundation\n"
            if anchor not in text:
                raise RuntimeError("VideoMasks: CameraPreviewView import anchor not found")
            text = text.replace(anchor, anchor + "import AorusGram\n", 1)
        property_anchor = "    private let placeholderView = UIImageView()\n"
        if property_anchor not in text:
            raise RuntimeError("VideoMasks: CameraPreviewView property anchor not found")
        text = text.replace(property_anchor, property_anchor + "    private var aorusMaskOverlayView: AorusVideoMaskOverlayView?\n", 1)
        init_anchor = "        self.addSubview(self.placeholderView)\n"
        init_replacement = (
            init_anchor
            + "        if roundVideo { " + preview_sentinel + "\n"
            + "            let overlayView = AorusVideoMaskOverlayView(frame: self.bounds)\n"
            + "            self.aorusMaskOverlayView = overlayView\n"
            + "            self.addSubview(overlayView)\n"
            + "        }\n"
        )
        if init_anchor not in text:
            raise RuntimeError("VideoMasks: CameraPreviewView init anchor not found")
        text = text.replace(init_anchor, init_replacement, 1)
        layout_anchor = "        self.placeholderView.frame = self.bounds.insetBy(dx: -1.0, dy: -1.0)\n"
        if layout_anchor not in text:
            raise RuntimeError("VideoMasks: CameraPreviewView layout anchor not found")
        text = text.replace(layout_anchor, layout_anchor + "        self.aorusMaskOverlayView?.frame = self.bounds\n", 1)
        camera_preview.write_text(text, encoding="utf-8")
        print("VideoMasks: local round-video preview overlay patched")
    else:
        print("VideoMasks: local round-video preview already patched")

    camera_build = tg / "submodules/Camera/BUILD"
    if camera_build.is_file():
        text = camera_build.read_text(encoding="utf-8")
        if "//submodules/AorusGram:AorusGram" not in text:
            anchor = "    deps = [\n"
            if anchor not in text:
                raise RuntimeError("VideoMasks: Camera BUILD deps anchor not found")
            text = text.replace(anchor, anchor + '        "//submodules/AorusGram:AorusGram",\n', 1)
            camera_build.write_text(text, encoding="utf-8")

