def patch_video_mask_call_phase(tg: Path) -> None:
    """Publish Telegram's one-to-one call phase for the mask compositor.

    While a call is waiting/ringing/connecting, the compositor only prepares a
    single masked frame and leaves the native local AVCapture preview untouched.
    Active/reconnecting calls resume the normal outgoing masked-frame pipeline.
    """
    path = tg / "submodules/TelegramCallsUI/Sources/PresentationCall.swift"
    if not path.is_file():
        raise RuntimeError("VideoMasks: PresentationCall.swift not found")
    text = path.read_text(encoding="utf-8")
    sentinel = "// AorusGram: publish video-mask call phase"

    init_anchor = "        self.isOutgoing = isOutgoing\n"
    init_block = (
        init_anchor
        + "        UserDefaults.standard.set(1, forKey: \"aorusgram_video_mask_call_phase\") " + sentinel + "\n"
    )
    if sentinel not in text:
        if init_anchor not in text:
            raise RuntimeError("VideoMasks: PresentationCall init phase anchor not found")
        text = text.replace(init_anchor, init_block, 1)

    deinit_anchor = "    deinit {\n"
    deinit_block = (
        deinit_anchor
        + "        UserDefaults.standard.set(0, forKey: \"aorusgram_video_mask_call_phase\")\n"
    )
    deinit_marker = "deinit {\n        UserDefaults.standard.set(0, forKey: \"aorusgram_video_mask_call_phase\")"
    if deinit_marker not in text:
        if deinit_anchor not in text:
            raise RuntimeError("VideoMasks: PresentationCall deinit phase anchor not found")
        text = text.replace(deinit_anchor, deinit_block, 1)

    conference_anchor = (
        "        if isConference {\n"
        "            if self.currentTone != nil {\n"
    )
    conference_block = (
        "        if isConference {\n"
        "            UserDefaults.standard.set(0, forKey: \"aorusgram_video_mask_call_phase\")\n"
        "            if self.currentTone != nil {\n"
    )
    conference_marker = "if isConference {\n            UserDefaults.standard.set(0, forKey: \"aorusgram_video_mask_call_phase\")"
    if conference_marker not in text:
        if conference_anchor not in text:
            raise RuntimeError("VideoMasks: PresentationCall conference phase anchor not found")
        text = text.replace(conference_anchor, conference_block, 1)

    # Migrate the first implementation away from matching PresentationCallState's
    # associated-value enum. The concrete Telegram call-context branches are both
    # simpler and resilient to enum signature changes across source updates.
    legacy_publish_block = (
        "            if let presentationState {\n"
        "                let aorusVideoMaskCallPhase: Int\n"
        "                switch presentationState.state {\n"
        "                case .active, .reconnecting:\n"
        "                    aorusVideoMaskCallPhase = 2\n"
        "                case .terminating, .terminated:\n"
        "                    aorusVideoMaskCallPhase = 0\n"
        "                default:\n"
        "                    aorusVideoMaskCallPhase = 1\n"
        "                }\n"
        "                UserDefaults.standard.set(aorusVideoMaskCallPhase, forKey: \"aorusgram_video_mask_call_phase\")\n"
        "                self.statePromise.set(presentationState)\n"
    )
    publish_anchor = (
        "            if let presentationState {\n"
        "                self.statePromise.set(presentationState)\n"
    )
    if legacy_publish_block in text:
        text = text.replace(legacy_publish_block, publish_anchor, 1)

    connected_anchor = "                    case .connected:\n"
    connected_block = (
        connected_anchor
        + "                        UserDefaults.standard.set(2, forKey: \"aorusgram_video_mask_call_phase\")\n"
    )
    connected_marker = "case .connected:\n                        UserDefaults.standard.set(2, forKey: \"aorusgram_video_mask_call_phase\")"
    if connected_marker not in text:
        if connected_anchor not in text:
            raise RuntimeError("VideoMasks: connected call phase anchor not found")
        text = text.replace(connected_anchor, connected_block, 1)

    reconnecting_anchor = "                    case .reconnecting:\n"
    reconnecting_block = (
        reconnecting_anchor
        + "                        UserDefaults.standard.set(2, forKey: \"aorusgram_video_mask_call_phase\")\n"
    )
    reconnecting_marker = "case .reconnecting:\n                        UserDefaults.standard.set(2, forKey: \"aorusgram_video_mask_call_phase\")"
    if reconnecting_marker not in text:
        if reconnecting_anchor not in text:
            raise RuntimeError("VideoMasks: reconnecting call phase anchor not found")
        text = text.replace(reconnecting_anchor, reconnecting_block, 1)

    path.write_text(text, encoding="utf-8")
    print("VideoMasks: one-to-one call phase published for nonblocking local preview")


# Self-contained C++ port of the validated Swift Voice Twin DSP
# (AorusGram/Sources/Features/AorusVoiceTwin.swift). Runs on the WebRTC capture
# thread; mutates the microphone PCM in place inside RecordedDataIsAvailable,
# before the encoder. Pure C++ + an ObjC-only UserDefaults read — no module
# dependencies, so it adds nothing to TgVoipWebrtc's link graph and cannot create
# a dependency cycle. iOS delivers the mic as mono Int16 PCM after the hardware
# voice-processing AEC/NS, so the transform applies to clean near-end voice only;
# any other PCM layout is a safe no-op (original audio passes through untouched).
_AORUS_CALL_VOICE_TWIN_HEADER = r"""#ifndef AorusCallVoiceTwin_h
#define AorusCallVoiceTwin_h

// AorusGram: voice twin (calls) — formant-preserving real-time voice transform.
// Faithful C++ port of the Swift AorusVoiceTwin DSP. See the patch comment in
// scripts/aorus_branding.py (patch_voice_twin_calls) for the rationale.

#include <cstdint>
#include <cstddef>
#include <vector>
#include <cmath>

#ifdef __OBJC__
#import <Foundation/Foundation.h>
#endif

class AorusCallVoiceTwin {
public:
    AorusCallVoiceTwin() {
        xh.assign(kOrder, 0.0f);
        yh.assign(kOrder, 0.0f);
        pred.assign(kOrder, 0.0f);
        autoc.assign(kOrder + 1, 0.0f);
        win.assign(kFrame, 0.0f);
        scratch.assign(kFrame, 0.0f);
        ring.assign(kRingSize, 0.0f);
        hann.assign(kFrame, 0.0f);
        for (int i = 0; i < kFrame; i++) {
            hann[i] = 0.5f - 0.5f * std::cos(2.0f * (float)M_PI * (float)i / (float)(kFrame - 1));
        }
    }

    // Refresh enabled flag + preset from UserDefaults. Throttled by the caller so
    // the real-time path does not hit the defaults store on every 10 ms frame.
    void refreshParams() {
#ifdef __OBJC__
        NSUserDefaults *d = [NSUserDefaults standardUserDefaults];
        _enabled = [d boolForKey:@"aorusgram_voice_twin_enabled"];
        NSString *preset = [d stringForKey:@"aorusgram_voice_twin_preset"];
        float semis = -5.0f;
        float ringHz = 0.0f;
        float ringMix = 0.0f;
        float tone = 0.95f;
        float drive = 1.03f;
        bool formantMove = false;
        // Mirrors AorusVoiceTwin.params() exactly: wetMix is 1.0 everywhere (no dry
        // pitch bleed) and gender/age presets move the formants with the pitch.
        if ([preset isEqualToString:@"male"]) { semis = -4.5f; tone = 0.92f; drive = 1.02f; formantMove = true; }
        else if ([preset isEqualToString:@"female"]) { semis = 4.0f; tone = 1.06f; drive = 1.0f; formantMove = true; }
        else if ([preset isEqualToString:@"robot"]) { semis = 0.0f; ringHz = 90.0f; ringMix = 0.80f; tone = 0.85f; drive = 1.10f; }
        else if ([preset isEqualToString:@"child"] || [preset isEqualToString:@"high"]) { semis = 7.5f; tone = 1.10f; drive = 0.98f; formantMove = true; }
        else { semis = -5.0f; ringHz = 40.0f; ringMix = 0.08f; tone = 0.95f; drive = 1.03f; }
        _ratio = std::pow(2.0f, semis / 12.0f);
        _ringHz = ringHz;
        _ringMix = ringMix;
        _wetMix = 1.0f;
        _tone = tone;
        _drive = drive;
        _formantMove = formantMove;
#endif
    }

    bool enabled() const { return _enabled; }

    // Transform interleaved PCM in place. Only mono Int16 is processed; anything
    // else is a safe no-op so the call audio can never be corrupted.
    void process(void *samples, size_t nSamples, size_t nBytesPerSample, size_t nChannels, uint32_t sampleRate) {
        if (!_enabled) { return; }
        if (samples == nullptr || nSamples == 0 || nChannels != 1 || nBytesPerSample != 2) { return; }
        if (_ratio == 1.0f && _ringMix <= 0.0f) { return; }
        const float sr = sampleRate > 0 ? (float)sampleRate : 48000.0f;
        const float ringStep = _ringHz > 0.0f ? (2.0f * (float)M_PI * _ringHz / sr) : 0.0f;
        int16_t *p = (int16_t *)samples;
        for (size_t i = 0; i < nSamples; i++) {
            float y = transformSample((float)p[i] / 32768.0f, ringStep);
            float v = y * 32767.0f;
            if (v > 32767.0f) { v = 32767.0f; }
            if (v < -32768.0f) { v = -32768.0f; }
            p[i] = (int16_t)v;
        }
    }

private:
    static constexpr int kOrder = 24;
    static constexpr int kFrame = 1024;
    static constexpr int kHop = 256;
    static constexpr float kGamma = 0.995f;     // bandwidth expansion (pole damping)
    static constexpr float kPreemph = 0.95f;    // analysis pre-emphasis / output de-emphasis
    static constexpr int kRingSize = 8192;
    static constexpr float kGrain = 1024.0f;

    float transformSample(float x0, float ringStep) {
        float y;
        if (_ratio == 1.0f) {
            y = x0;
        } else if (_formantMove) {
            // Plain pitch shift of the full signal → formants move with the pitch
            // (natural gender/age change).
            y = granStep(x0, _ratio);
        } else {
            // Formant-preserving LPC shift (disguise / robot base).
            y = formantStep(x0, _ratio);
        }
        y = x0 * (1.0f - _wetMix) + y * _wetMix;
        y = applyTone(y);
        if (ringStep > 0.0f && _ringMix > 0.0f) {
            const float modulated = y * std::cos(ringModPhase);
            y = y * (1.0f - _ringMix) + modulated * _ringMix;
            ringModPhase += ringStep;
            if (ringModPhase > 2.0f * (float)M_PI) { ringModPhase -= 2.0f * (float)M_PI; }
        }
        if (_drive > 1.0f) {
            y = std::tanh(y * _drive) / std::tanh(_drive);
        } else {
            y *= _drive;
        }
        if (y > 1.0f) { y = 1.0f; }
        if (y < -1.0f) { y = -1.0f; }
        return y;
    }

    float applyTone(float x) {
        toneLP = 0.86f * toneLP + 0.14f * x;
        if (_tone >= 1.0f) {
            return x + (x - toneLP) * (_tone - 1.0f);
        } else {
            return toneLP + (x - toneLP) * _tone;
        }
    }

    float formantStep(float x0, float ratio) {
        const float xp = x0 - kPreemph * prevIn;
        prevIn = x0;

        win[wpos] = xp;
        wpos++;
        if (wpos >= kFrame) { wpos = 0; }
        if (filled < kFrame) { filled++; }

        if (cnt % kHop == 0 && filled >= kFrame) { updateLPC(); }
        cnt++;

        float e = xp;
        for (int k = 0; k < kOrder; k++) { e -= pred[k] * xh[k]; }

        const float es = granStep(e, ratio);

        float y = es;
        for (int k = 0; k < kOrder; k++) { y += pred[k] * yh[k]; }

        if (!std::isfinite(y) || std::fabs(y) > 8.0f) {
            for (int k = 0; k < kOrder; k++) { yh[k] = 0.0f; }
            y = es;
        }

        int k = kOrder - 1;
        while (k > 0) { xh[k] = xh[k - 1]; yh[k] = yh[k - 1]; k--; }
        xh[0] = xp;
        yh[0] = y;

        deemph = y + kPreemph * deemph;
        float yo = deemph;

        inEnergy = 0.999f * inEnergy + 0.001f * x0 * x0;
        outEnergy = 0.999f * outEnergy + 0.001f * yo * yo;
        float gain = std::sqrt((inEnergy + 1e-9f) / (outEnergy + 1e-9f));
        if (gain > 4.0f) { gain = 4.0f; }
        yo *= gain;

        if (yo > 1.0f) { yo = 1.0f; }
        if (yo < -1.0f) { yo = -1.0f; }
        return yo;
    }

    void updateLPC() {
        for (int i = 0; i < kFrame; i++) { scratch[i] = win[(wpos + i) % kFrame] * hann[i]; }
        for (int lag = 0; lag <= kOrder; lag++) {
            float acc = 0.0f;
            for (int i = lag; i < kFrame; i++) { acc += scratch[i] * scratch[i - lag]; }
            autoc[lag] = acc;
        }
        if (autoc[0] <= 1e-9f) { zeroPred(); return; }
        autoc[0] *= 1.0002f;   // white-noise floor regularisation

        // Levinson-Durbin on fixed-size stack arrays (kOrder is a compile-time
        // constant) — no heap traffic on the real-time call-capture thread.
        float a[kOrder + 1] = { 0.0f };
        float e = autoc[0];
        for (int i = 1; i <= kOrder; i++) {
            float acc = autoc[i];
            for (int j = 1; j < i; j++) { acc += a[j] * autoc[i - j]; }
            const float k = -acc / e;
            if (!std::isfinite(k) || std::fabs(k) >= 0.999f) { zeroPred(); return; }
            float na[kOrder + 1];
            for (int j = 1; j < i; j++) { na[j] = a[j] + k * a[i - j]; }
            na[i] = k;
            for (int j = 1; j <= i; j++) { a[j] = na[j]; }
            e *= (1.0f - k * k);
            if (e <= 0.0f) { zeroPred(); return; }
        }
        // Predictor coefficients (-a[k+1]) with bandwidth expansion (pole damping).
        float g = 1.0f;
        for (int k = 0; k < kOrder; k++) { g *= kGamma; pred[k] = (-a[k + 1]) * g; }
    }

    void zeroPred() { for (int k = 0; k < kOrder; k++) { pred[k] = 0.0f; } }

    float granStep(float x, float ratio) {
        const int n = kRingSize;
        const float g = kGrain;
        const float half = g * 0.5f;
        ring[writeIndex] = x;

        float y;
        if (ratio == 1.0f) {
            y = x;
        } else {
            const float p1 = phase;
            float p2 = phase + half;
            if (p2 >= g) { p2 -= g; }
            const float r1 = readRing((float)writeIndex - p1, n);
            const float r2 = readRing((float)writeIndex - p2, n);
            // Raised-cosine (Hann) crossfade — each tap fades to zero AT its own grain
            // wrap discontinuity instead of peaking there (the old triangular window),
            // which removes the periodic warble.
            const float w1 = 0.5f * (1.0f - std::cos(2.0f * (float)M_PI * p1 / g));
            y = r1 * w1 + r2 * (1.0f - w1);
        }

        writeIndex++;
        if (writeIndex >= n) { writeIndex = 0; }
        phase += (1.0f - ratio);
        while (phase >= g) { phase -= g; }
        while (phase < 0.0f) { phase += g; }
        return y;
    }

    float readRing(float pos, int n) {
        float fp = pos;
        const float nf = (float)n;
        while (fp < 0.0f) { fp += nf; }
        while (fp >= nf) { fp -= nf; }
        const int i0 = (int)fp;
        const float frac = fp - (float)i0;
        const int i1 = (i0 + 1) % n;
        return ring[i0] * (1.0f - frac) + ring[i1] * frac;
    }

    // Granular residual pitch-shifter state.
    std::vector<float> ring;
    int writeIndex = 0;
    float phase = 0.0f;

    // LPC analysis / filter state.
    std::vector<float> win;
    int wpos = 0;
    int filled = 0;
    std::vector<float> xh;       // inverse-filter input history
    std::vector<float> yh;       // synthesis-filter output history
    std::vector<float> pred;     // LPC predictor coefficients
    std::vector<float> hann;
    std::vector<float> scratch;
    std::vector<float> autoc;
    int cnt = 0;
    float prevIn = 0.0f;
    float deemph = 0.0f;
    float inEnergy = 1e-6f;
    float outEnergy = 1e-6f;

    // Ring modulation phase (robot).
    float ringModPhase = 0.0f;
    float toneLP = 0.0f;

    // Active configuration (refreshed from UserDefaults).
    bool _enabled = false;
    float _ratio = 1.0f;
    float _ringHz = 0.0f;
    float _ringMix = 0.0f;
    float _wetMix = 1.0f;
    float _tone = 0.96f;
    float _drive = 1.04f;
    bool _formantMove = false;
};

#endif /* AorusCallVoiceTwin_h */
"""


def patch_voice_twin_calls(tg: Path) -> None:
    """Apply Voice Twin to OUTGOING audio/video CALL audio (tgcalls / WebRTC).

    Telegram calls capture the microphone through the native iOS audio device
    module. `WrappedAudioDeviceModuleIOS` registers itself as that module's audio
    callback, so the captured PCM lands in `RecordedDataIsAvailable(...)` right
    before it is forwarded to the WebRTC voice engine for encoding. We transform
    the samples in place there — the encoder then transmits the modified voice.

    The DSP is a self-contained C++ port of the Swift Voice Twin (written to a new
    header alongside the .mm). It has no module dependencies, so TgVoipWebrtc gains
    no new link edges and there is zero risk of a dependency cycle. UserDefaults is
    read (throttled) on the ObjC side; the same flat keys the settings screen
    writes (`aorusgram_voice_twin_enabled` / `aorusgram_voice_twin_preset`) drive
    it, identical to the voice-message and video-note paths.

    iOS delivers mono Int16 PCM after the hardware voice-processing AEC/NS, so the
    transform sees clean near-end voice; any other layout is a safe no-op.
    """
    mm = tg / "submodules/TgVoipWebrtc/Sources/OngoingCallThreadLocalContext.mm"
    if not mm.is_file():
        print("VoiceTwinCalls: OngoingCallThreadLocalContext.mm not found, skip")
        return
    t = mm.read_text(encoding="utf-8")
    sentinel = "// AorusGram: voice twin (calls)"
    if sentinel in t:
        print("VoiceTwinCalls: already injected")
        return

    # 1) Write the self-contained DSP header next to the .mm.
    header = tg / "submodules/TgVoipWebrtc/Sources/AorusCallVoiceTwin.h"
    header.write_text(_AORUS_CALL_VOICE_TWIN_HEADER, encoding="utf-8")
    print("VoiceTwinCalls: wrote AorusCallVoiceTwin.h")

    # 2) Include the header (before the class that holds the DSP instance).
    inc_anchor = "#import <TdBinding/TdBinding.h>\n"
    if inc_anchor in t:
        t = t.replace(inc_anchor, inc_anchor + '#import "AorusCallVoiceTwin.h"\n', 1)
    else:
        print("VoiceTwinCalls: WARNING — include anchor not found")
        return

    # 3) Add the per-capture DSP instance + refresh counter to WrappedAudioDeviceModuleIOS.
    mem_anchor = "    std::vector<int16_t> _mixAudioSamples;\n};"
    if mem_anchor in t:
        t = t.replace(
            mem_anchor,
            "    std::vector<int16_t> _mixAudioSamples;\n"
            "    " + sentinel + " — per-capture DSP state\n"
            "    AorusCallVoiceTwin _aorusVoiceTwin;\n"
            "    int _aorusVoiceTwinRefresh = 0;\n};",
            1,
        )
    else:
        print("VoiceTwinCalls: WARNING — member anchor not found")
        return

    # 4) Transform the mic PCM in place at the top of both RecordedDataIsAvailable
    #    overloads (only one is invoked by the ADM per build; patching both is safe).
    inject = (
        "    ) override {\n"
        "        " + sentinel + "\n"
        "        if ((_aorusVoiceTwinRefresh++ % 50) == 0) { _aorusVoiceTwin.refreshParams(); }\n"
        "        if (_aorusVoiceTwin.enabled()) {\n"
        "            _aorusVoiceTwin.process(const_cast<void *>(audioSamples), nSamples, nBytesPerSample, nChannels, samplesPerSec);\n"
        "        }\n"
        "        _mutex.Lock();"
    )
    anchor1 = "        uint32_t& newMicLevel\n    ) override {\n        _mutex.Lock();"
    anchor2 = "        absl::optional<int64_t> estimatedCaptureTimeNS\n    ) override {\n        _mutex.Lock();"
    n = 0
    if anchor1 in t:
        t = t.replace(anchor1, "        uint32_t& newMicLevel\n" + inject, 1); n += 1
    if anchor2 in t:
        t = t.replace(anchor2, "        absl::optional<int64_t> estimatedCaptureTimeNS\n" + inject, 1); n += 1
    if n == 0:
        print("VoiceTwinCalls: WARNING — no RecordedDataIsAvailable anchor matched")
        return

    mm.write_text(t, encoding="utf-8")
    print(f"VoiceTwinCalls: hooked RecordedDataIsAvailable ({n}/2 overloads)")


def patch_bypass_story_screenshot(tg: Path) -> None:
    """Always-on (stock, no UI entry) bypass of story screenshot protection.

    A protected story (`isForwardingDisabled`) feeds `captureProtected:` /
    `isCaptureProtected:` into the story media views. Those flags both blank the
    frame under a secure-text-entry layer (so screenshots come out black) and
    overlay the "Screenshot Blocked" banner. Forcing them to false at every story
    render site removes the black capture and the banner. The forward/download
    button logic reads `isForwardingDisabled` separately and is left untouched.
    """
    f = tg / "submodules/TelegramUI/Components/Stories/StoryContainerScreen/Sources/StoryItemContentComponent.swift"
    if not f.is_file():
        print("StoryScreenshot: StoryItemContentComponent.swift not found, skip")
        return
    t = f.read_text(encoding="utf-8")
    if "AorusGram: story screenshot bypass" in t:
        print("StoryScreenshot: already patched")
        return
    n = 0
    for key in ("captureProtected: component.item.isForwardingDisabled,",
                "isCaptureProtected: component.item.isForwardingDisabled,"):
        cnt = t.count(key)
        if cnt:
            repl = key.split(":", 1)[0] + ": false, // AorusGram: story screenshot bypass"
            t = t.replace(key, repl)
            n += cnt
    if n:
        f.write_text(t, encoding="utf-8")
        print(f"StoryScreenshot: neutralised capture protection at {n} story render site(s)")
    else:
        print("StoryScreenshot: WARNING — no capture-protection anchors found")


# AMOLED helper injected into TelegramPresentationData. Forces true-black surfaces
# on dark themes only; light themes and the chat wallpaper on light themes are
# left untouched. Reads the flat key the settings screen writes.
_AORUS_AMOLED_HELPER = (
    "// AorusGram: AMOLED dark mode — force true-black surfaces on dark themes only.\n"
    "private func aorusAmoledEnabled() -> Bool {\n"
    "    return UserDefaults.standard.bool(forKey: \"aorusgram_amoled\")\n"
    "}\n"
    "\n"
    "// AorusGram: Interface 2.0 — glass surfaces everywhere the theme reaches.\n"
    "// Applied after AMOLED so a true-black block still becomes translucent: the two\n"
    "// settings compose rather than fight. Only the item fills are touched — the page\n"
    "// behind them stays opaque, which is what a pane of glass needs to read as glass\n"
    "// instead of as a washed-out card.\n"
    "private func aorusInterfaceV2Enabled() -> Bool {\n"
    "    return UserDefaults.standard.bool(forKey: \"aorusgram_interface_v2\")\n"
    "}\n"
    "\n"
    "func aorusApplyInterfaceV2Theme(_ theme: PresentationTheme) -> PresentationTheme {\n"
    "    guard aorusInterfaceV2Enabled() else { return theme }\n"
    "    let dark = theme.overallDarkAppearance\n"
    "    let fill = UIColor(white: dark ? 1.0 : 0.0, alpha: dark ? 0.10 : 0.04)\n"
    "    let separator = UIColor(white: dark ? 1.0 : 0.0, alpha: dark ? 0.12 : 0.08)\n"
    "    let list = theme.list.withUpdated(itemBlocksBackgroundColor: fill, itemModalBlocksBackgroundColor: fill, itemBlocksSeparatorColor: separator)\n"
    "    return PresentationTheme(name: theme.name, index: theme.index, referenceTheme: theme.referenceTheme, overallDarkAppearance: theme.overallDarkAppearance, intro: theme.intro, passcode: theme.passcode, rootController: theme.rootController, list: list, chatList: theme.chatList, chat: theme.chat, actionSheet: theme.actionSheet, contextMenu: theme.contextMenu, inAppNotification: theme.inAppNotification, chart: theme.chart, preview: theme.preview)\n"
    "}\n"
    "\n"
    "func aorusApplyAmoledTheme(_ theme: PresentationTheme) -> PresentationTheme {\n"
    "    guard aorusAmoledEnabled(), theme.overallDarkAppearance else { return aorusApplyInterfaceV2Theme(theme) }\n"
    "    let black = UIColor(rgb: 0x000000)\n"
    "    let navigationBar = theme.rootController.navigationBar.withUpdated(blurredBackgroundColor: black, opaqueBackgroundColor: black)\n"
    "    let tabBar = theme.rootController.tabBar.withUpdated(backgroundColor: black)\n"
    "    let navigationSearchBar = theme.rootController.navigationSearchBar.withUpdated(backgroundColor: black)\n"
    "    let rootController = theme.rootController.withUpdated(tabBar: tabBar, navigationBar: navigationBar, navigationSearchBar: navigationSearchBar)\n"
    "    let list = theme.list.withUpdated(blocksBackgroundColor: black, modalBlocksBackgroundColor: black, plainBackgroundColor: black, modalPlainBackgroundColor: black, itemBlocksBackgroundColor: black, itemModalBlocksBackgroundColor: black)\n"
    "    let chatList = theme.chatList.withUpdated(backgroundColor: black, itemBackgroundColor: black, pinnedItemBackgroundColor: black)\n"
    "    let inputPanel = theme.chat.inputPanel.withUpdated(panelBackgroundColor: black, panelBackgroundColorNoWallpaper: black)\n"
    "    let chat = theme.chat.withUpdated(defaultWallpaper: .color(0x000000), inputPanel: inputPanel)\n"
    "    return aorusApplyInterfaceV2Theme(PresentationTheme(name: theme.name, index: theme.index, referenceTheme: theme.referenceTheme, overallDarkAppearance: theme.overallDarkAppearance, intro: theme.intro, passcode: theme.passcode, rootController: rootController, list: list, chatList: chatList, chat: chat, actionSheet: theme.actionSheet, contextMenu: theme.contextMenu, inAppNotification: theme.inAppNotification, chart: theme.chart, preview: theme.preview))\n"
    "}\n"
    "\n"
    "// AorusGram: true when the user has explicitly picked a chat wallpaper for the\n"
    "// theme the wallpaper picker writes under. Mirrors the write key used by\n"
    "// uploadCustomWallpaper() and WallpaperGalleryController exactly (colored index\n"
    "// first, plain theme index second), so an explicit choice is never mistaken for\n"
    "// \"nothing set\". AMOLED must not paint over a wallpaper the user just chose.\n"
    "func aorusHasUserChosenWallpaper(settings: PresentationThemeSettings, autoNightModeTriggered: Bool) -> Bool {\n"
    "    let reference: PresentationThemeReference = autoNightModeTriggered ? settings.automaticThemeSwitchSetting.theme : settings.theme\n"
    "    let accentColor = settings.themeSpecificAccentColors[reference.index]\n"
    "    if settings.themeSpecificChatWallpapers[coloredThemeIndex(reference: reference, accentColor: accentColor)] != nil {\n"
    "        return true\n"
    "    }\n"
    "    return settings.themeSpecificChatWallpapers[reference.index] != nil\n"
    "}\n"
    "\n"
    "func aorusAmoledWallpaper(_ wallpaper: TelegramWallpaper, dark: Bool, settings: PresentationThemeSettings, autoNightModeTriggered: Bool) -> TelegramWallpaper {\n"
    "    guard aorusAmoledEnabled(), dark else {\n"
    "        return wallpaper\n"
    "    }\n"
    "    // AMOLED only supplies a background where the theme's default would otherwise\n"
    "    // show. A wallpaper the user picked wins — otherwise the wallpaper grid could\n"
    "    // never show a selection (it compares against presentationData.chatWallpaper)\n"
    "    // and tapping a photo would appear to do nothing at all.\n"
    "    if aorusHasUserChosenWallpaper(settings: settings, autoNightModeTriggered: autoNightModeTriggered) {\n"
    "        return wallpaper\n"
    "    }\n"
    "    return .color(0x000000)\n"
    "}\n"
    "\n"
    "// Re-emits whenever the AMOLED flag flips, so the presentation pipeline re-runs\n"
    "// and the transform is applied/removed live. Account shared-data writes dedup\n"
    "// identical values, so a settings re-commit cannot drive this — hence a direct\n"
    "// NotificationCenter trigger, debounced to the AMOLED flag only (no spurious\n"
    "// theme rebuilds when unrelated settings change).\n"
    "func aorusAmoledTrigger() -> Signal<Void, NoError> {\n"
    "    return Signal { subscriber in\n"
    "        subscriber.putNext(Void())\n"
    "        var lastValue = UserDefaults.standard.bool(forKey: \"aorusgram_amoled\")\n"
    "        let observer = NotificationCenter.default.addObserver(forName: Notification.Name(\"aorusgram_settings_changed\"), object: nil, queue: OperationQueue.main) { _ in\n"
    "            let newValue = UserDefaults.standard.bool(forKey: \"aorusgram_amoled\")\n"
    "            if newValue != lastValue {\n"
    "                lastValue = newValue\n"
    "                subscriber.putNext(Void())\n"
    "            }\n"
    "        }\n"
    "        return ActionDisposable {\n"
    "            NotificationCenter.default.removeObserver(observer)\n"
    "        }\n"
    "    }\n"
    "}\n"
    "\n"
)


def patch_amoled_theme(tg: Path) -> None:
    """AMOLED dark mode — toggled in AorusGram → Interface.

    Injects a self-contained transform into TelegramPresentationData and applies
    it at the two points where the final PresentationData is built (the initial
    snapshot and the live signal). When the flag is on and the resolved theme is
    dark, every elevated surface (nav bar, tab bar, search bar, list blocks/items,
    chat-list rows, input panel) and the chat wallpaper are forced to pure black;
    the built-in Night theme already uses black for the plain backgrounds. Light
    themes are returned unchanged. Live updates are driven by the settings-change
    observer (patch_settings_live_refresh), which re-commits the theme settings.
    """
    f = tg / "submodules/TelegramPresentationData/Sources/PresentationData.swift"
    if not f.is_file():
        print("Amoled: PresentationData.swift not found, skip")
        return
    t = f.read_text(encoding="utf-8")
    if "aorusApplyAmoledTheme" in t:
        print("Amoled: already patched")
        return

    helper_anchor = "public func currentPresentationDataAndSettings("
    if helper_anchor not in t:
        print("Amoled: WARNING — helper anchor not found")
        return
    t = t.replace(helper_anchor, _AORUS_AMOLED_HELPER + helper_anchor, 1)

    # Apply to the initial snapshot (currentPresentationDataAndSettings).
    init_old = "theme: theme, autoNightModeTriggered: autoNightModeTriggered, chatWallpaper: effectiveChatWallpaper,"
    init_new = ("theme: aorusApplyAmoledTheme(theme), autoNightModeTriggered: autoNightModeTriggered, "
                "chatWallpaper: aorusAmoledWallpaper(effectiveChatWallpaper, dark: theme.overallDarkAppearance, settings: themeSettings, autoNightModeTriggered: autoNightModeTriggered),")
    # Apply to the live signal (updatedPresentationData).
    live_old = "theme: themeValue, autoNightModeTriggered: autoNightModeTriggered, chatWallpaper: effectiveChatWallpaper,"
    live_new = ("theme: aorusApplyAmoledTheme(themeValue), autoNightModeTriggered: autoNightModeTriggered, "
                "chatWallpaper: aorusAmoledWallpaper(effectiveChatWallpaper, dark: themeValue.overallDarkAppearance, settings: themeSettings, autoNightModeTriggered: autoNightModeTriggered),")
    n = 0
    if init_old in t:
        t = t.replace(init_old, init_new, 1); n += 1
    if live_old in t:
        t = t.replace(live_old, live_new, 1); n += 1

    # Merge the AMOLED trigger into the live theme pipeline so toggling re-emits.
    trig_old = (
        "                    return automaticThemeShouldSwitch(themeSettings.automaticThemeSwitchSetting, systemUserInterfaceStyle: systemUserInterfaceStyle)\n"
        "                    |> distinctUntilChanged\n"
        "                    |> map { autoNightModeTriggered in\n"
    )
    trig_new = (
        "                    return combineLatest(automaticThemeShouldSwitch(themeSettings.automaticThemeSwitchSetting, systemUserInterfaceStyle: systemUserInterfaceStyle)\n"
        "                    |> distinctUntilChanged, aorusAmoledTrigger())\n"
        "                    |> map { autoNightModeTriggered, _ in\n"
    )
    trig = 0
    if trig_old in t:
        t = t.replace(trig_old, trig_new, 1); trig = 1

    if n == 2 and trig == 1:
        f.write_text(t, encoding="utf-8")
        print("Amoled: injected helper, applied at 2 PresentationData sites, wired live trigger")
    else:
        print(f"Amoled: WARNING — applied {n}/2 sites, trigger {trig}/1")


def patch_hide_tabs(tg: Path) -> None:
    """Hide the Contacts / Calls tabs in the bottom tab bar (AorusGram → Interface).

    `TelegramRootController` builds the tab list in addRootControllers (initial)
    and updateRootControllers (rebuild). Gate the Contacts and Calls appends on the
    flat keys the settings screen writes. The chats tab stays at `count - 2` and
    settings at `count - 1` regardless of which optional tabs are present, so the
    selected-index arithmetic is unaffected. The live observer rebuilds the bar
    when either flag changes.
    """
    f = tg / "submodules/TelegramUI/Sources/TelegramRootController.swift"
    if not f.is_file():
        print("HideTabs: TelegramRootController.swift not found, skip")
        return
    t = f.read_text(encoding="utf-8")
    if "AorusGram: hide contacts tab" in t:
        print("HideTabs: already patched")
        return

    edits = [
        # addRootControllers — Contacts
        ("        controllers.append(contactsController)\n",
         "        if !UserDefaults.standard.bool(forKey: \"aorusgram_hide_contacts_tab\") { // AorusGram: hide contacts tab\n"
         "            controllers.append(contactsController)\n"
         "        }\n"),
        # addRootControllers — Calls
        ("        if showCallsTab {\n            controllers.append(callListController)\n        }",
         "        if showCallsTab && !UserDefaults.standard.bool(forKey: \"aorusgram_hide_calls_tab\") { // AorusGram: hide calls tab\n"
         "            controllers.append(callListController)\n        }"),
        # updateRootControllers — Contacts
        ("        controllers.append(self.contactsController!)\n",
         "        if !UserDefaults.standard.bool(forKey: \"aorusgram_hide_contacts_tab\") { // AorusGram: hide contacts tab\n"
         "            controllers.append(self.contactsController!)\n"
         "        }\n"),
        # updateRootControllers — Calls
        ("        if showCallsTab {\n            controllers.append(self.callListController!)\n        }",
         "        if showCallsTab && !UserDefaults.standard.bool(forKey: \"aorusgram_hide_calls_tab\") { // AorusGram: hide calls tab\n"
         "            controllers.append(self.callListController!)\n        }"),
    ]
    n = 0
    for old, new in edits:
        if old in t:
            t = t.replace(old, new, 1); n += 1
    if n == len(edits):
        f.write_text(t, encoding="utf-8")
        print(f"HideTabs: gated Contacts/Calls appends ({n} sites)")
    else:
        print(f"HideTabs: WARNING — matched {n}/{len(edits)} anchors")


def patch_tab_bar_visibility_controls(tg: Path) -> None:
    """Hide Search / tab titles live while preserving Telegram's native tab bar.

    Search is removed at the composition boundary, before width calculation. Tab
    titles are hidden inside TabBarComponent, where the component also reduces its
    real height and vertically centres icons. TabBarController's temporary insets
    use the same adjustment, preventing a one-frame content jump during rebuilds.
    """
    component_file = (
        tg
        / "submodules/TelegramUI/Components/TabBarComponent/Sources/TabBarComponent.swift"
    )
    node_file = tg / "submodules/TabBarUI/Sources/TabBarContollerNode.swift"
    controller_file = tg / "submodules/TabBarUI/Sources/TabBarController.swift"
    if not component_file.is_file() or not node_file.is_file() or not controller_file.is_file():
        print("TabBarVisibility: required tab-bar sources not found, skip")
        return

    component = component_file.read_text(encoding="utf-8")
    if "AorusGram: hide tab titles" not in component:
        original = component
        replacements = [
            (
                "    public let search: Search?\n"
                "    public let selectedId: AnyHashable?\n",
                "    public let search: Search?\n"
                "    public let hideTitles: Bool // AorusGram: hide tab titles\n"
                "    public let selectedId: AnyHashable?\n",
            ),
            (
                "        items: [Item],\n"
                "        search: Search?,\n"
                "        selectedId: AnyHashable?,\n",
                "        items: [Item],\n"
                "        search: Search?,\n"
                "        hideTitles: Bool = false,\n"
                "        selectedId: AnyHashable?,\n",
            ),
            (
                "        self.items = items\n"
                "        self.search = search\n"
                "        self.selectedId = selectedId\n",
                "        self.items = items\n"
                "        self.search = search\n"
                "        self.hideTitles = hideTitles\n"
                "        self.selectedId = selectedId\n",
            ),
            (
                "        if lhs.search != rhs.search {\n"
                "            return false\n"
                "        }\n"
                "        if lhs.selectedId != rhs.selectedId {\n",
                "        if lhs.search != rhs.search {\n"
                "            return false\n"
                "        }\n"
                "        if lhs.hideTitles != rhs.hideTitles {\n"
                "            return false\n"
                "        }\n"
                "        if lhs.selectedId != rhs.selectedId {\n",
            ),
            (
                "            let barHeight: CGFloat = 56.0 + innerInset * 2.0\n",
                "            let itemHeight: CGFloat = component.hideTitles ? 48.0 : 56.0\n"
                "            let barHeight: CGFloat = itemHeight + innerInset * 2.0\n",
            ),
            (
                "                    containerSize: CGSize(width: 200.0, height: 56.0)\n",
                "                    containerSize: CGSize(width: 200.0, height: itemHeight)\n",
            ),
            (
                "            let itemHeight: CGFloat = 56.0\n"
                "            let contentWidth: CGFloat = innerInset * 2.0 + totalItemsWidth\n",
                "            let contentWidth: CGFloat = innerInset * 2.0 + totalItemsWidth\n",
            ),
            (
                "    let isCompact: Bool\n"
                "    let isSelected: Bool\n",
                "    let isCompact: Bool\n"
                "    let hideTitle: Bool\n"
                "    let isSelected: Bool\n",
            ),
            (
                "    init(item: TabBarComponent.Item, theme: PresentationTheme, isCompact: Bool, isSelected: Bool, tintSelectedItem: Bool, isUnconstrained: Bool) {\n"
                "        self.item = item\n"
                "        self.theme = theme\n"
                "        self.isCompact = isCompact\n"
                "        self.isSelected = isSelected\n",
                "    init(item: TabBarComponent.Item, theme: PresentationTheme, isCompact: Bool, hideTitle: Bool, isSelected: Bool, tintSelectedItem: Bool, isUnconstrained: Bool) {\n"
                "        self.item = item\n"
                "        self.theme = theme\n"
                "        self.isCompact = isCompact\n"
                "        self.hideTitle = hideTitle\n"
                "        self.isSelected = isSelected\n",
            ),
            (
                "        if lhs.isCompact != rhs.isCompact {\n"
                "            return false\n"
                "        }\n"
                "        if lhs.isSelected != rhs.isSelected {\n",
                "        if lhs.isCompact != rhs.isCompact {\n"
                "            return false\n"
                "        }\n"
                "        if lhs.hideTitle != rhs.hideTitle {\n"
                "            return false\n"
                "        }\n"
                "        if lhs.isSelected != rhs.isSelected {\n",
            ),
            (
                "                alphaTransition.setAlpha(view: titleView, alpha: component.isCompact ? 0.0 : 1.0)\n",
                "                alphaTransition.setAlpha(view: titleView, alpha: (component.isCompact || component.hideTitle) ? 0.0 : 1.0)\n",
            ),
            (
                "                return CGSize(width: titleSize.width + 10.0 * 2.0, height: availableSize.height)\n",
                "                return CGSize(width: component.hideTitle ? 48.0 : titleSize.width + 10.0 * 2.0, height: availableSize.height)\n",
            ),
        ]
        for old, new in replacements:
            if old not in component:
                print(f"TabBarVisibility: WARNING — component anchor missing: {old.splitlines()[0]!r}")
                component = original
                break
            component = component.replace(old, new, 1)

        if component != original:
            compact_anchors = (
                "                        isCompact: false,\n"
                "                        isSelected: false,\n",
                "                        isCompact: component.search?.isActive == true,\n"
                "                        isSelected: false,\n",
                "                        isCompact: component.search?.isActive == true,\n"
                "                        isSelected: true,\n",
            )
            for old in compact_anchors:
                if old not in component:
                    print("TabBarVisibility: WARNING — ItemComponent construction anchor missing")
                    component = original
                    break
                component = component.replace(
                    old,
                    old.replace(
                        "                        isSelected:",
                        "                        hideTitle: component.hideTitles,\n"
                        "                        isSelected:",
                    ),
                    1,
                )

        if component != original:
            icon_replacements = [
                (
                    "y: -4.0), size: iconSize).offsetBy(dx: tabBarItem.animationOffset.x",
                    "y: component.hideTitle ? floor((availableSize.height - iconSize.height) * 0.5) : -4.0), size: iconSize).offsetBy(dx: tabBarItem.animationOffset.x",
                ),
                (
                    "y: 3.0), size: iconSize)\n",
                    "y: component.hideTitle ? floor((availableSize.height - iconSize.height) * 0.5) : 3.0), size: iconSize)\n",
                ),
                (
                    "y: -4.0), size: iconSize).offsetBy(dx: offset.x",
                    "y: component.hideTitle ? floor((availableSize.height - iconSize.height) * 0.5) : -4.0), size: iconSize).offsetBy(dx: offset.x",
                ),
                (
                    "y: 8.0), size: iconSize)\n",
                    "y: component.hideTitle ? floor((availableSize.height - iconSize.height) * 0.5) : 8.0), size: iconSize)\n",
                ),
            ]
            for old, new in icon_replacements:
                if old not in component:
                    print(f"TabBarVisibility: WARNING — icon anchor missing: {old!r}")
                    component = original
                    break
                component = component.replace(old, new, 1)

        if component != original:
            component_file.write_text(component, encoding="utf-8")
            print("TabBarVisibility: native title hiding and compact height injected")
    else:
        print("TabBarVisibility: TabBarComponent already patched")

    # Compact mode is intentionally independent from title visibility. It keeps
    # Telegram's native item rendering and touch targets, but sizes the glass
    # panel to the intrinsic width of the visible tabs instead of stretching it
    # across all available space. This migration also upgrades cached CI trees
    # that already contain the earlier title-hiding patch.
    component = component_file.read_text(encoding="utf-8")
    if "AorusGram: compact tab panel" not in component:
        original = component
        compact_replacements = [
            (
                "    public let hideTitles: Bool // AorusGram: hide tab titles\n"
                "    public let selectedId: AnyHashable?\n",
                "    public let hideTitles: Bool // AorusGram: hide tab titles\n"
                "    public let compactPanel: Bool // AorusGram: compact tab panel\n"
                "    public let selectedId: AnyHashable?\n",
            ),
            (
                "        hideTitles: Bool = false,\n"
                "        selectedId: AnyHashable?,\n",
                "        hideTitles: Bool = false,\n"
                "        compactPanel: Bool = false,\n"
                "        selectedId: AnyHashable?,\n",
            ),
            (
                "        self.hideTitles = hideTitles\n"
                "        self.selectedId = selectedId\n",
                "        self.hideTitles = hideTitles\n"
                "        self.compactPanel = compactPanel\n"
                "        self.selectedId = selectedId\n",
            ),
            (
                "        if lhs.hideTitles != rhs.hideTitles {\n"
                "            return false\n"
                "        }\n"
                "        if lhs.selectedId != rhs.selectedId {\n",
                "        if lhs.hideTitles != rhs.hideTitles {\n"
                "            return false\n"
                "        }\n"
                "        if lhs.compactPanel != rhs.compactPanel {\n"
                "            return false\n"
                "        }\n"
                "        if lhs.selectedId != rhs.selectedId {\n",
            ),
            (
                "            let equalWidth = floorToScreenPixels(availableItemsWidth / CGFloat(component.items.count))\n",
                "            let minimumItemsWidth = 48.0 * CGFloat(component.items.count)\n"
                "            let layoutItemsWidth = component.compactPanel ? min(availableItemsWidth, max(minimumItemsWidth, unboundItemWidthSum)) : availableItemsWidth\n"
                "            let equalWidth = floorToScreenPixels(layoutItemsWidth / CGFloat(component.items.count))\n",
            ),
            (
                "                let itemWeightNorm: CGFloat = availableItemsWidth / unboundItemWidthSum\n",
                "                let itemWeightNorm: CGFloat = layoutItemsWidth / unboundItemWidthSum\n",
            ),
            (
                "                return CGSize(width: component.hideTitle ? 48.0 : titleSize.width + 10.0 * 2.0, height: availableSize.height)\n",
                "                return CGSize(width: component.hideTitle ? 48.0 : max(48.0, titleSize.width + 10.0 * 2.0), height: availableSize.height)\n",
            ),
        ]
        for old, new in compact_replacements:
            if old not in component:
                print(f"TabBarVisibility: WARNING — compact component anchor missing: {old.splitlines()[0]!r}")
                component = original
                break
            component = component.replace(old, new, 1)
        if component != original:
            component_file.write_text(component, encoding="utf-8")
            print("TabBarVisibility: compact native panel sizing injected")
    else:
        print("TabBarVisibility: compact panel already patched")

    # The stock inactive-search frame is based on the full available width because
    # the stock tabs always fill it. In compact mode the component returns a smaller
    # width, so anchor Search to that actual width or it ends up outside the panel.
    component = component_file.read_text(encoding="utf-8")
    compact_search_anchor = (
        "                    searchFrame = CGRect(origin: CGPoint(x: availableSize.width - searchSize.width, y: 0.0), size: searchSize)\n"
    )
    if "AorusGram: compact tab panel" in component and compact_search_anchor in component:
        component = component.replace(
            compact_search_anchor,
            "                    searchFrame = CGRect(origin: CGPoint(x: size.width - searchSize.width, y: 0.0), size: searchSize) // AorusGram: compact search position\n",
            1,
        )
        component_file.write_text(component, encoding="utf-8")
        print("TabBarVisibility: compact search position aligned")

    node = node_file.read_text(encoding="utf-8")
    if "AorusGram: hide search button" not in node:
        original = node
        old = "                search: self.currentController?.tabBarSearchState.flatMap { tabBarSearchState in\n"
        new = (
            "                search: UserDefaults.standard.bool(forKey: \"aorusgram_hide_search_button\") ? nil : self.currentController?.tabBarSearchState.flatMap { tabBarSearchState in // AorusGram: hide search button\n"
        )
        hide_titles_anchor = "                selectedId: selectedId,\n"
        if old in node and hide_titles_anchor in node:
            node = node.replace(old, new, 1)
            node = node.replace(
                hide_titles_anchor,
                "                hideTitles: UserDefaults.standard.bool(forKey: \"aorusgram_hide_tab_titles\"),\n"
                + hide_titles_anchor,
                1,
            )
            node_file.write_text(node, encoding="utf-8")
            print("TabBarVisibility: search composition and title mode wired")
        else:
            print("TabBarVisibility: WARNING — TabBarContollerNode anchors missing")
            node = original
    else:
        print("TabBarVisibility: TabBarContollerNode already patched")

    node = node_file.read_text(encoding="utf-8")
    if "compactPanel: UserDefaults.standard.bool" not in node:
        anchor = (
            "                hideTitles: UserDefaults.standard.bool(forKey: \"aorusgram_hide_tab_titles\"),\n"
        )
        if anchor in node:
            node = node.replace(
                anchor,
                anchor
                + "                compactPanel: UserDefaults.standard.bool(forKey: \"aorusgram_compact_tab_bar\"),\n",
                1,
            )
            node_file.write_text(node, encoding="utf-8")
            print("TabBarVisibility: compact panel setting wired")
        else:
            print("TabBarVisibility: WARNING — compact panel node anchor missing")
    else:
        print("TabBarVisibility: compact panel setting already wired")

    controller = controller_file.read_text(encoding="utf-8")
    if "AorusGram: compact tab titles" not in controller:
        original = controller
        anchor = (
            "                    let bottomInset: CGFloat = validLayout.insets(options: options).bottom\n"
            "                    if !validLayout.safeInsets.left.isZero {\n"
            "                        tabBarHeight = 34.0 + bottomInset\n"
            "                    } else {\n"
            "                        tabBarHeight = 49.0 + bottomInset\n"
            "                    }\n"
        )
        replacement = (
            "                    let bottomInset: CGFloat = validLayout.insets(options: options).bottom\n"
            "                    let aorusTabTitleAdjustment: CGFloat = UserDefaults.standard.bool(forKey: \"aorusgram_hide_tab_titles\") ? 8.0 : 0.0 // AorusGram: compact tab titles\n"
            "                    if !validLayout.safeInsets.left.isZero {\n"
            "                        tabBarHeight = 34.0 - aorusTabTitleAdjustment + bottomInset\n"
            "                    } else {\n"
            "                        tabBarHeight = 49.0 - aorusTabTitleAdjustment + bottomInset\n"
            "                    }\n"
        )
        anchor2 = anchor.replace("validLayout", "updatedLayout").replace("                    ", "            ")
        replacement2 = replacement.replace("validLayout", "updatedLayout").replace("                    ", "            ")
        if anchor in controller and anchor2 in controller:
            controller = controller.replace(anchor, replacement, 1)
            controller = controller.replace(anchor2, replacement2, 1)
            controller_file.write_text(controller, encoding="utf-8")
            print("TabBarVisibility: temporary controller insets aligned")
        else:
            print("TabBarVisibility: WARNING — TabBarController inset anchors missing")
            controller = original
    else:
        print("TabBarVisibility: TabBarController already patched")


def patch_action_confirmation(tg: Path) -> None:
    """Confirmation prompts in front of calls and of sending a just-recorded message.

    Both are single-tap, irreversible and easy to trigger by accident. Rather than sprinkling
    checks over the many UI entry points, each is gated at its one choke point: AccountContextImpl
    owns every call the app can place, and ChatControllerImpl owns both ways a recorded voice or
    video message reaches the wire. Each method keeps its name and gains a private
    aorusPerform... twin holding the original body, so nothing downstream changes.
    """
    acc = tg / "submodules/TelegramUI/Sources/AccountContext.swift"
    if acc.is_file():
        t = acc.read_text(encoding="utf-8")
        if "aorusPerformRequestCall" in t:
            print("ActionConfirm: AccountContext already patched")
        else:
            if "import AorusGramUI\n" not in t:
                t = t.replace("import AccountContext\n", "import AccountContext\nimport AorusGramUI\n", 1)

            edits = [
                (
                    "    public func requestCall(peerId: PeerId, isVideo: Bool, completion: @escaping () -> Void) {\n",
                    "    public func requestCall(peerId: PeerId, isVideo: Bool, completion: @escaping () -> Void) {\n"
                    "        aorusConfirmCall(self, isVideo: isVideo, parentController: nil) { [weak self] in // AorusGram: Action confirmation\n"
                    "            self?.aorusPerformRequestCall(peerId: peerId, isVideo: isVideo, completion: completion)\n"
                    "        }\n"
                    "    }\n"
                    "\n"
                    "    private func aorusPerformRequestCall(peerId: PeerId, isVideo: Bool, completion: @escaping () -> Void) {\n",
                ),
                (
                    "    public func joinGroupCall(peerId: PeerId, invite: String?, requestJoinAsPeerId: ((@escaping (PeerId?) -> Void) -> Void)?, activeCall: EngineGroupCallDescription) {\n",
                    "    public func joinGroupCall(peerId: PeerId, invite: String?, requestJoinAsPeerId: ((@escaping (PeerId?) -> Void) -> Void)?, activeCall: EngineGroupCallDescription) {\n"
                    "        aorusConfirmGroupCall(self, parentController: nil) { [weak self] in // AorusGram: Action confirmation\n"
                    "            self?.aorusPerformJoinGroupCall(peerId: peerId, invite: invite, requestJoinAsPeerId: requestJoinAsPeerId, activeCall: activeCall)\n"
                    "        }\n"
                    "    }\n"
                    "\n"
                    "    private func aorusPerformJoinGroupCall(peerId: PeerId, invite: String?, requestJoinAsPeerId: ((@escaping (PeerId?) -> Void) -> Void)?, activeCall: EngineGroupCallDescription) {\n",
                ),
                (
                    "    public func joinConferenceCall(call: JoinCallLinkInformation, isVideo: Bool, unmuteByDefault: Bool) {\n",
                    "    public func joinConferenceCall(call: JoinCallLinkInformation, isVideo: Bool, unmuteByDefault: Bool) {\n"
                    "        aorusConfirmGroupCall(self, parentController: nil) { [weak self] in // AorusGram: Action confirmation\n"
                    "            self?.aorusPerformJoinConferenceCall(call: call, isVideo: isVideo, unmuteByDefault: unmuteByDefault)\n"
                    "        }\n"
                    "    }\n"
                    "\n"
                    "    private func aorusPerformJoinConferenceCall(call: JoinCallLinkInformation, isVideo: Bool, unmuteByDefault: Bool) {\n",
                ),
            ]
            applied = 0
            for old, new in edits:
                if t.count(old) == 1:
                    t = t.replace(old, new, 1)
                    applied += 1
            if applied == len(edits):
                acc.write_text(t, encoding="utf-8")
                print("ActionConfirm: call entry points gated")
            else:
                print(f"ActionConfirm: WARNING matched {applied}/{len(edits)} call anchors — not written")
    else:
        print("ActionConfirm: AccountContext.swift not found — skip")

    rec = tg / "submodules/TelegramUI/Sources/Chat/ChatControllerMediaRecording.swift"
    if not rec.is_file():
        print("ActionConfirm: ChatControllerMediaRecording.swift not found — skip")
        return
    t = rec.read_text(encoding="utf-8")
    if "aorusPerformSendMediaRecording" in t:
        print("ActionConfirm: recording paths already patched")
        return
    if "import AorusGramUI\n" not in t:
        t = t.replace("import AccountContext\n", "import AccountContext\nimport AorusGramUI\n", 1)

    dismiss_old = "    func dismissMediaRecorder(_ action: ChatFinishMediaRecordingAction) {\n"
    dismiss_new = (
        "    func dismissMediaRecorder(_ action: ChatFinishMediaRecordingAction) {\n"
        "        // AorusGram: Action confirmation. This is the release-to-send path, the one that\n"
        "        // fires the moment a finger lifts. Park the recording in the preview panel first,\n"
        "        // so declining leaves it intact to send deliberately or discard, and accepting\n"
        "        // sends it through exactly the route the preview's own send button uses.\n"
        "        var aorusIsSendAction = false\n"
        "        var aorusViewOnce = false\n"
        "        // The payload matters: `.send` carries whether the user armed the one-time\n"
        "        // toggle, and matching the case without binding it -- which is what stood here --\n"
        "        // dropped that flag on the floor. The recording then went out as an ordinary\n"
        "        // voice message, every time, on the release-to-send path.\n"
        "        if case let .send(viewOnce) = action {\n"
        "            aorusIsSendAction = true\n"
        "            aorusViewOnce = viewOnce\n"
        "        }\n"
        "        if aorusIsSendAction, aorusActionConfirmationIsEnabled() {\n"
        "            let aorusIsVideo = self.videoRecorderValue != nil\n"
        "            self.aorusPerformDismissMediaRecorder(.preview)\n"
        "            aorusConfirmRecordedMessage(self.context, isVideo: aorusIsVideo, parentController: self) { [weak self] in\n"
        "                self?.aorusSendRecordedMessageWhenReady(viewOnce: aorusViewOnce)\n"
        "            }\n"
        "            return\n"
        "        }\n"
        "        self.aorusPerformDismissMediaRecorder(action)\n"
        "    }\n"
        "\n"
        "    // Moving to .preview stops the recorder and stores the draft through a signal, so the\n"
        "    // draft is not there yet when the prompt appears. Confirming therefore waits for it\n"
        "    // rather than sending into a nil draft, which would silently drop the recording.\n"
        "    func aorusSendRecordedMessageWhenReady(viewOnce: Bool, attempt: Int = 0) {\n"
        "        if self.presentationInterfaceState.interfaceState.mediaDraftState != nil {\n"
        "            self.aorusPerformSendMediaRecording(viewOnce: viewOnce)\n"
        "            return\n"
        "        }\n"
        "        guard attempt < 20 else {\n"
        "            return\n"
        "        }\n"
        "        Queue.mainQueue().after(0.1) { [weak self] in\n"
        "            self?.aorusSendRecordedMessageWhenReady(viewOnce: viewOnce, attempt: attempt + 1)\n"
        "        }\n"
        "    }\n"
        "\n"
        "    func aorusPerformDismissMediaRecorder(_ action: ChatFinishMediaRecordingAction) {\n"
    )

    send_old = (
        "    func sendMediaRecording(\n"
        "        silentPosting: Bool? = nil,\n"
        "        scheduleTime: Int32? = nil,\n"
        "        repeatPeriod: Int32? = nil,\n"
        "        viewOnce: Bool = false,\n"
        "        messageEffect: ChatSendMessageEffect? = nil,\n"
        "        postpone: Bool = false\n"
        "    ) {\n"
    )
    send_new = (
        "    func sendMediaRecording(\n"
        "        silentPosting: Bool? = nil,\n"
        "        scheduleTime: Int32? = nil,\n"
        "        repeatPeriod: Int32? = nil,\n"
        "        viewOnce: Bool = false,\n"
        "        messageEffect: ChatSendMessageEffect? = nil,\n"
        "        postpone: Bool = false\n"
        "    ) {\n"
        "        var aorusIsVideo = false // AorusGram: Action confirmation\n"
        "        if case .some(.video) = self.presentationInterfaceState.interfaceState.mediaDraftState {\n"
        "            aorusIsVideo = true\n"
        "        }\n"
        "        aorusConfirmRecordedMessage(self.context, isVideo: aorusIsVideo, parentController: self) { [weak self] in\n"
        "            self?.aorusPerformSendMediaRecording(silentPosting: silentPosting, scheduleTime: scheduleTime, repeatPeriod: repeatPeriod, viewOnce: viewOnce, messageEffect: messageEffect, postpone: postpone)\n"
        "        }\n"
        "    }\n"
        "\n"
        "    func aorusPerformSendMediaRecording(\n"
        "        silentPosting: Bool? = nil,\n"
        "        scheduleTime: Int32? = nil,\n"
        "        repeatPeriod: Int32? = nil,\n"
        "        viewOnce: Bool = false,\n"
        "        messageEffect: ChatSendMessageEffect? = nil,\n"
        "        postpone: Bool = false\n"
        "    ) {\n"
    )

    if t.count(dismiss_old) == 1 and t.count(send_old) == 1:
        t = t.replace(dismiss_old, dismiss_new, 1)
        t = t.replace(send_old, send_new, 1)
        rec.write_text(t, encoding="utf-8")
        print("ActionConfirm: recorded voice/video send gated")
    else:
        print(
            "ActionConfirm: WARNING recording anchors not unique "
            f"(dismiss={t.count(dismiss_old)}, send={t.count(send_old)}) — not written"
        )


def patch_wall_postbox_paging(tg: Path) -> None:
    """Expose a bounded, cursor-based message fetch for the Wall.

    Postbox.scanTopMessages always starts at the newest row and its callback only stops the
    current 10-row batch. It therefore cannot implement deep pagination and performs the same
    large scan on every Wall page. This small Transaction API keeps the table private while
    letting the Wall start exactly at its current frontier.
    """
    path = tg / "submodules/Postbox/Sources/Postbox.swift"
    if not path.is_file():
        print("WallPaging: Postbox.swift not found — skip")
        return

    t = path.read_text(encoding="utf-8")
    if "public func aorusWallMessages(" in t:
        print("WallPaging: cursor API already patched")
        return

    anchor = (
        "    public func scanTopMessages(peerId: PeerId, namespace: MessageId.Namespace, limit: Int, _ f: (Message) -> Bool) {\n"
        "        assert(!self.disposed)\n"
        "        self.postbox?.scanTopMessages(peerId: peerId, namespace: namespace, limit: limit, f)\n"
        "    }\n"
    )
    replacement = (
        "    // AorusGram: bounded cursor fetch for the Wall. Unlike scanTopMessages this starts\n"
        "    // at the reader's frontier and can continue through arbitrarily old local history.\n"
        "    public func aorusWallMessages(peerId: PeerId, namespace: MessageId.Namespace, before: MessageIndex, limit: Int) -> [Message] {\n"
        "        assert(!self.disposed)\n"
        "        guard limit > 0, before.id.peerId == peerId, before.id.namespace == namespace, let postbox = self.postbox else {\n"
        "            return []\n"
        "        }\n"
        "        return postbox.messageHistoryTable.fetch(\n"
        "            peerId: peerId,\n"
        "            namespace: namespace,\n"
        "            tag: nil,\n"
        "            customTag: nil,\n"
        "            threadId: nil,\n"
        "            from: before,\n"
        "            includeFrom: false,\n"
        "            to: MessageIndex.lowerBound(peerId: peerId, namespace: namespace),\n"
        "            ignoreMessagesInTimestampRange: nil,\n"
        "            ignoreMessageIds: Set(),\n"
        "            limit: limit\n"
        "        ).map(postbox.renderIntermediateMessage(_:))\n"
        "    }\n"
        "\n"
        + anchor
    )
    if anchor in t:
        path.write_text(t.replace(anchor, replacement, 1), encoding="utf-8")
        print("WallPaging: added bounded cursor API to Postbox.Transaction")
    else:
        print("WallPaging: WARNING — scanTopMessages anchor not found")


def patch_wall_tab(tg: Path) -> None:
    """Add the native AorusGram Wall tab and wire its chat lifecycle."""
    account_context = tg / "submodules/AccountContext/Sources/ChatController.swift"
    root = tg / "submodules/TelegramUI/Sources/TelegramRootController.swift"
    content_data = tg / "submodules/TelegramUI/Sources/ChatControllerContentData.swift"
    chat_controller = tg / "submodules/TelegramUI/Sources/ChatController.swift"
    chat_controller_node = tg / "submodules/TelegramUI/Sources/ChatControllerNode.swift"
    context_menu = tg / "submodules/TelegramUI/Sources/Chat/ChatControllerOpenMessageContextMenu.swift"
    empty_node = tg / "submodules/TelegramUI/Components/Chat/ChatEmptyNode/Sources/ChatEmptyNode.swift"
    bubble_node = tg / "submodules/TelegramUI/Components/Chat/ChatMessageBubbleItemNode/Sources/ChatMessageBubbleItemNode.swift"

    if not root.is_file():
        print("Wall: TelegramRootController.swift not found, skip")
        return

    if account_context.is_file():
        t = account_context.read_text(encoding="utf-8")
        if "var aorusIsWall: Bool { get }" not in t:
            protocol_anchor = (
                "public protocol ChatCustomContentsProtocol: AnyObject {\n"
                "    var kind: ChatCustomContentsKind { get }\n"
            )
            protocol_replacement = (
                "public protocol ChatCustomContentsProtocol: AnyObject {\n"
                "    var kind: ChatCustomContentsKind { get }\n"
                "    var aorusIsWall: Bool { get }\n"
            )
            extension_anchor = (
                "}\n"
                "\n"
                "public enum ChatHistoryListDisplayHeaders {\n"
            )
            extension_replacement = (
                "}\n"
                "\n"
                "public extension ChatCustomContentsProtocol {\n"
                "    var aorusIsWall: Bool {\n"
                "        return false\n"
                "    }\n"
                "}\n"
                "\n"
                "public enum ChatHistoryListDisplayHeaders {\n"
            )
            if protocol_anchor in t and extension_anchor in t:
                t = t.replace(protocol_anchor, protocol_replacement, 1)
                t = t.replace(extension_anchor, extension_replacement, 1)
                account_context.write_text(t, encoding="utf-8")
                print("Wall: shared custom-content marker integrated")
            else:
                print("Wall: WARNING — custom-content protocol anchors not found")
        else:
            print("Wall: shared custom-content marker already patched")
    else:
        print("Wall: WARNING — AccountContext ChatController.swift not found")

    # The Telegram checkout is restored from a persistent CI cache. Migrate output
    # produced by older versions of this script even when the individual feature
    # patchers report "already patched".
    legacy_type_checks = (
        ("!(customChatContents is AorusWallChatContents)", "!customChatContents.aorusIsWall"),
        ("contents is AorusWallChatContents", "contents.aorusIsWall"),
        (
            'String(reflecting: type(of: customChatContents)).contains("AorusWallChatContents")',
            "customChatContents.aorusIsWall",
        ),
    )
    migrated_checks = 0
    for path in (chat_controller, chat_controller_node, context_menu, empty_node, bubble_node):
        if not path.is_file():
            continue
        t = path.read_text(encoding="utf-8")
        original = t
        for old, new in legacy_type_checks:
            migrated_checks += t.count(old)
            t = t.replace(old, new)
        if t != original:
            path.write_text(t, encoding="utf-8")
    if migrated_checks:
        print(f"Wall: migrated {migrated_checks} cached concrete-type check(s)")

    t = root.read_text(encoding="utf-8")
    if "AorusGram: Wall tab" not in t:
        edits = [
            (
                "    public var accountSettingsController: PeerInfoScreen?\n",
                "    public var accountSettingsController: PeerInfoScreen?\n"
                "    public var aorusWallController: ViewController? // AorusGram: Wall tab\n",
            ),
            (
                "        controllers.append(accountSettingsController)\n"
                "                \n"
                "        tabBarController.setControllers(controllers, selectedIndex: restoreSettignsController != nil ? (controllers.count - 1) : (controllers.count - 2))\n",
                "        controllers.append(accountSettingsController)\n"
                "        let aorusWallEnabled = UserDefaults.standard.object(forKey: \"aorusgram_wall_enabled\") == nil ? true : UserDefaults.standard.bool(forKey: \"aorusgram_wall_enabled\")\n"
                "        let aorusWallController: ViewController? = aorusWallEnabled ? makeAorusWallController(context: self.context) : nil\n"
                "        if let aorusWallController {\n"
                "            controllers.append(aorusWallController)\n"
                "        }\n"
                "                \n"
                "        let selectedIndex: Int\n"
                "        if restoreSettignsController != nil {\n"
                "            selectedIndex = controllers.firstIndex(where: { $0 === accountSettingsController }) ?? 0\n"
                "        } else {\n"
                "            selectedIndex = controllers.firstIndex(where: { $0 === chatListController }) ?? 0\n"
                "        }\n"
                "        tabBarController.setControllers(controllers, selectedIndex: selectedIndex)\n",
            ),
            (
                "        self.accountSettingsController = accountSettingsController\n"
                "        self.rootTabController = tabBarController\n",
                "        self.accountSettingsController = accountSettingsController\n"
                "        self.aorusWallController = aorusWallController\n"
                "        self.rootTabController = tabBarController\n",
            ),
            (
                "        controllers.append(self.accountSettingsController!)\n"
                "        \n"
                "        rootTabController.setControllers(controllers, selectedIndex: nil)\n",
                "        controllers.append(self.accountSettingsController!)\n"
                "        let aorusWallEnabled = UserDefaults.standard.object(forKey: \"aorusgram_wall_enabled\") == nil ? true : UserDefaults.standard.bool(forKey: \"aorusgram_wall_enabled\")\n"
                "        if aorusWallEnabled {\n"
                "            if self.aorusWallController == nil {\n"
                "                self.aorusWallController = makeAorusWallController(context: self.context)\n"
                "            }\n"
                "            if let aorusWallController = self.aorusWallController {\n"
                "                controllers.append(aorusWallController)\n"
                "            }\n"
                "        } else {\n"
                "            self.aorusWallController = nil\n"
                "        }\n"
                "        \n"
                "        rootTabController.setControllers(controllers, selectedIndex: nil)\n",
            ),
        ]
        matched = 0
        for old, new in edits:
            if old in t:
                t = t.replace(old, new, 1)
                matched += 1
        if matched != len(edits):
            print(f"Wall: WARNING — root anchors matched {matched}/{len(edits)}")
            return
        root.write_text(t, encoding="utf-8")
        print("Wall: root tab integrated")
    else:
        old_default = '(UserDefaults.standard.object(forKey: "aorusgram_wall_enabled") as? Bool) ?? true'
        new_default = 'UserDefaults.standard.object(forKey: "aorusgram_wall_enabled") == nil ? true : UserDefaults.standard.bool(forKey: "aorusgram_wall_enabled")'
        if old_default in t:
            t = t.replace(old_default, new_default)
